#include <stddef.h> // for size_t
#include <stdlib.h> // for malloc and free

char** safe_string_array_alloc_and_copy(const char** input_strings, size_t array_size) {
    size_t total_length = 0;
    size_t i;

    // Check if input array is null or empty
    if (input_strings == NULL || array_size == 0) {
        return NULL;
    }

    // Calculate the total length of all strings in the array
    for (i = 0; i < array_size; i++) {
        total_length += strlen(input_strings[i]) + 1; // +1 for null terminator
    }

    // Allocate memory for the new array and the new strings
    char** output_strings = (char**) malloc(sizeof(char*) * array_size + total_length);

    if (output_strings == NULL) {
        free(input_strings); // Free previously allocated resources if allocation fails
        return NULL;
    }

    // Copy strings into the new array
    for (i = 0; i < array_size; i++) {
        size_t string_length = strlen(input_strings[i]);
        memcpy(output_strings[i] = (char*)(output_strings + array_size + i), input_strings[i], string_length + 1);
    }

    return output_strings;
}
