#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    int id;
    int age;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    int max_weighted_sum;
    int max_transaction_id;
} Metrics;

Metrics update_metrics(Transaction transactions[], int num_transactions, int window_size, double weight) {
    Metrics metrics = {0};
    int valid_transactions = 0;
    int i;
    time_t current_time = time(NULL);
    double sum = 0.0;

    for (i = 0; i < num_transactions; i++) {
        if (transactions[i].timestamp + window_size > current_time) {
            continue;
        }

        if (transactions[i].age <= 3) {
            sum += transactions[i].weight * weight;
            valid_transactions++;

            if (sum > metrics.max_weighted_sum) {
                metrics.max_weighted_sum = sum;
                metrics.max_transaction_id = transactions[i].id;
            }
        }
    }

    return metrics;
}

int main() {
    int num_transactions = 10;
    Transaction transactions[num_transactions];
    int i;
    int window_size = 3;
    double weight = 2.5;
    Metrics metrics;

    for (i = 0; i < num_transactions; i++) {
        transactions[i].id = i + 1;
        transactions[i].age = rand() % 10;
        transactions[i].weight = rand() % 10 + 1.0;
        transactions[i].timestamp = time(NULL) - transactions[i].age;
