#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <errno.h>

#define BUNDLE_ITEM_SIZE 100

typedef struct {
    char name[100];
    char data[BUNDLE_ITEM_SIZE];
} bundle_item_t;

int load_resource_bundle(const char *path, size_t *bundle_size, bundle_item_t **bundle) {
    if (!path || !bundle_size || !bundle) {
        errno = EINVAL;
        return -1;
    }

    char *file_path = malloc(strlen(path) + 1);
    if (!file_path) {
        errno = ENOMEM;
        return -1;
    }
    strcpy(file_path, path);

    struct stat file_stat;
    int rc = lstat(file_path, &file_stat);
    free(file_path);

    if (rc < 0) {
        switch (errno) {
            case ENOENT:
                *bundle_size = 0;
                *bundle = NULL;
                return 0;
            default:
                perror("Error checking resource file");
                return -1;
        }
    }

    if (!S_ISREG(file_stat.st_mode)) {
        perror("Resource file is not a regular file");
        return -1;
    }

    size_t file_size = file_stat.st_size;
    *bundle_size = file_size / (BUNDLE_ITEM_SIZE + sizeof(bundle_item_t));

    *bundle = malloc(*bundle_size * sizeof(bundle_item_t));
    if (!*bundle) {
        free(file_path);
        perror("Error allocating memory for bundle");
        return -1;
    }

    FILE *file = fopen(file_path, "rb");
    if (!file) {
        free(*bundle);
        free(file_path);
        perror("Error opening resource file");
        return -1;
    }

    size_t i = 0;
    while (i < *bundle_size && fread(&((*bundle)[i]), sizeof(bundle_item_t), 1, file) == 1) {
        i++;
    }

    if (ferror(file)) {
        fclose(file);
        free(*bundle);
        free(file_path);
        perror("Error reading resource file");
        return -1;
    }

    fclose(file);

    if (i != *bundle_size) {
        free(*bundle);
        free(file_path);
        perror("Error loading expected number of items from resource file");
        return -1;
    }

    return *bundle_size;
}
