#include <stdlib.h> // for malloc, size_t
#include <stdbool.h> // for bool, true, false

typedef struct Node {
    int offset;
    struct Node *left;
    struct Node *right;
} Node;

Node* insert_offset(Node** root, int offset) {
    if (*root == NULL) {
        *root = malloc(sizeof(Node));
        if (*root == NULL) {
            return NULL;
        }
        (*root)->offset = offset;
        (*root)->left = NULL;
        (*root)->right = NULL;
    } else {
        Node* current = *root;
        Node* parent = NULL;

        while (current != NULL) {
            parent = current;

            if (offset < current->offset) {
                current = current->left;
            } else {
                current = current->right;
            }
        }

        Node* new_node = malloc(sizeof(Node));
        if (new_node == NULL) {
            return NULL;
        }

        new_node->offset = offset;
        new_node->left = NULL;
        new_node->right = NULL;

        if (offset < parent->offset) {
            parent->left = new_node;
        } else {
            parent->right = new_node;
        }
    }

    return *root;
}
