            fprintf(stderr, "Memory allocation failed\n");
            return (TiffInfo) { TIFF_ERROR_MEMORY_ALLOCATION };
        }

        for (i = samples_per_pixel; i < num_components; i++) {
            TIFFGetField(tiff, i, &info.extra_samples_bits_per_sample[i - samples_per_pixel], NULL);
