#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <netdb.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MODE_INVALID (-1)
#define MIN_TCP_PORT 1024
#define MAX_TCP_PORT 65535

void udp_receive_file(const char *filename, int mode) {
    int sockfd, new_sockfd, n;
    struct sockaddr_in serv_addr;
    struct hostent *server;
    char buffer[1024];
    int file_fd;

    if (mode != MODE_VALID && mode != MODE_INVALID) {
        fprintf(stderr, "Invalid file mode: %d\n", mode);
        exit(EXIT_FAILURE);
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    server = gethostbyname("localhost");
    if (server == NULL) {
        fprintf(stderr, "Unknown host: %s\n", "localhost");
        exit(EXIT_FAILURE);
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(12345);
    serv_addr.sin_addr = *((struct in_addr *)server->h_addr);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect");
        exit(EXIT_FAILURE);
    }

    file_fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (file_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    while (1) {
        n = recvfrom(sockfd, buffer, sizeof(buffer), 0, NULL, NULL);
        if (n < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("recvfrom");
            exit(EXIT_FAILURE);
        }

        if (write(file_fd, buffer, n) != n) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        if (n < sizeof(buffer)) {
            break;
        }
    }

    close(sockfd);
    close(file_fd);

    printf("File %s received successfully.\n", filename);
}

int MODE_VALID = 0;
int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <filename> <mode>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int mode = atoi(argv[2]);

    udp_receive_file(argv[1], mode);

    return EXIT_SUCCESS;
}
