                    fclose(file);
                    return 1;
                }
                strings_and_counts_array = temp;
            }

            bool is_string = line[0] == '\'';
            size_t string_length = 0;
            char *string = line + (is_string ? 1 : 1 + strlen(line) - line[line_length - 1] < 1 ? line_length : line_length - 1 - (int)(line[line_length - 1] == '\n' ? 1 : 0));

