void array_copy(size_t *input_size, void **input_data, void **output_data, size_t output_capacity) {
    size_t i, new_size;
    void *new_data;

    if (input_size == NULL || input_data == NULL || output_data == NULL) {
        return;
    }

    if (*input_size == 0) {
        *output_data = malloc(0);
        return;
    }

    if (*input_data == NULL) {
        *output_data = malloc(*input_size * sizeof(**input_data));
        if (*output_data == NULL) {
            return;
        }
        memcpy(*output_data, *input_data, *input_size * sizeof(**input_data));
        return;
    }

    new_size = *input_size;
    new_data = *output_data;

    if (new_size > output_capacity) {
        new_size += output_capacity / 2; // double the capacity

        if (new_size > *input_size * 2) { // if new size is still not enough, calculate a new size
            new_size = *input_size * 2; // double the size of the input array
        }

        new_data = realloc(new_data, new_size * sizeof(**input_data));

        if (new_data == NULL) {
            free(*output_data);
            return;
        }

        *output_data = new_data;
    }

    memcpy(new_data, *input_data, *input_size * sizeof(**input_data));
}
