#include <stdio.h>
#include <stdlib.h>
#include "tiff.h"

void compress_tiff(TIFF *in_tiff, uint8 *buffer, size_t buffer_size) {
    TIFF *out_tiff = TIFFOpen("output.tiff", "w", INT16, in_tiff->ddir_count, NULL);
    if (!out_tiff) {
        TIFFError(TIFFFileName(in_tiff), "Error: Could not open output file for writing.\n");
        free(buffer);
        return;
    }

    for (int i = in_tiff->ddir_count - 1; i >= 0; i--) {
        int row = TIFFScanline(in_tiff, i);
        uint16 length = TIFFScanlineSize(in_tiff);
        uint8 *line_buffer = malloc(length);
        if (!line_buffer) {
            TIFFError(TIFFFileName(in_tiff), "Error: Failed to allocate memory for line buffer.\n");
            TIFFClose(out_tiff);
            free(buffer);
            return;
        }

        if (TIFFReadScanline(in_tiff, line_buffer, i) != length) {
            TIFFError(TIFFFileName(in_tiff), "Error: Failed to read scanline from input file.\n");
            free(line_buffer);
            free(buffer);
            TIFFClose(out_tiff);
            return;
        }

        // Reverse the order of pixels in the scanline
        for (size_t j = 0; j < length / 2; j++) {
            uint8 temp = line_buffer[j];
            line_buffer[j] = line_buffer[length - j - 1];
            line_buffer[length - j - 1] = temp;
        }

        if (TIFFWriteScanline(out_tiff, line_buffer, i) != length) {
            TIFFError(TIFFFileName(out_tiff), "Error: Failed to write compressed scanline to output file.\n");
            free(line_buffer);
            TIFFClose(out_tiff);
            free(buffer);
            return;
        }

        free(line_buffer);
    }

    // Close the output file and free the buffer
    TIFFClose(out_tiff);
    free(buffer);
}
