#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

#define MAX_BLOCK_SIZE 1024
#define RESERVED_SIZE 64

typedef struct {
    uint64_t size;
    int count;
} DistributionEntry;

void calculate_distribution(const void *data, size_t num_items, DistributionEntry *distribution) {
    size_t i;
    for (i = 0; i < num_items; ++i) {
        size_t current_block_size = sizeof(DistributionEntry) + ((size_t) data[i] % MAX_BLOCK_SIZE);
        if (current_block_size > MAX_BLOCK_SIZE) {
            current_block_size = MAX_BLOCK_SIZE;
            ++distribution[MAX_BLOCK_SIZE / sizeof(DistributionEntry)].count;
            data += (current_block_size - sizeof(DistributionEntry));
        }
        distribution[(size_t) data[i] % MAX_BLOCK_SIZE].size += sizeof(data[i]);
        distribution[(size_t) data[i] % MAX_BLOCK_SIZE].count++;
    }

    // Add the reserved size for random characters
    distribution[RESERVED_SIZE / sizeof(DistributionEntry)].size += RESERVED_SIZE;
    distribution[RESERVED_SIZE / sizeof(DistributionEntry)].count++;
}

size_t get_average_size(const void *data, size_t num_items) {
    size_t total_size = 0;
    for (size_t i = 0; i < num_items; ++i) {
        total_size += sizeof(data[i]);
    }
    return total_size / num_items;
}

size_t calculate_distribution_size(size_t num_items) {
    size_t distribution_size = sizeof(DistributionEntry) * (MAX_BLOCK_SIZE / sizeof(DistributionEntry) + 1);
    return distribution_size + num_items;
}

void *allocate_distribution(size_t num_items) {
    size_t distribution_size = calculate_distribution_size(num_items);
    void *distribution = calloc(1, distribution_size);
    if (!distribution) {
        return NULL;
    }

    calculate_distribution(data, num_items, (DistributionEntry *) distribution);

    return distribution;
}
