#define POOL_SIZE 1024 // Define the size of the pool

typedef struct pool_tag {
    void *freelist;
    size_t size;
    size_t allocated;
} pool_t;

pool_t atomic_pool;

static void *__get_pooled_memory(size_t size) {
    void *ptr = atomic_pool.freelist;
    if (ptr) {
        atomic_pool.freelist = *(void **)ptr;
        atomic_pool.allocated -= size;
    } else {
        if (atomic_pool.size <= atomic_pool.allocated + size) {
            // Reallocate the pool if it's not large enough
            atomic_pool.size *= 2;
            atomic_pool.freelist = reallocarray(atomic_pool.freelist, atomic_pool.size, sizeof(void *));
            if (!atomic_pool.freelist) {
                // Handle error
                return NULL;
            }
        }
        ptr = ((char *)atomic_pool.freelist + atomic_pool.allocated);
        atomic_pool.allocated += size;
    }
    memset(ptr, 0, size);
    return ptr;
}

static bool __init_list(void **list, size_t num_elements) {
    size_t i;
    for (i = 0; i < num_elements; i++) {
