    int thread_count;
    int suspension_threshold[MAX_THREADS];
    pthread_mutex_t mutex;
} scheduler_t;

scheduler_t *init_scheduler(int num_threads, void (*cpu_assign_func)(int, int *)) {
    scheduler_t *scheduler = malloc(sizeof(scheduler_t));
    if (!scheduler) {
        perror("Error allocating memory for scheduler");
        return NULL;
    }

    scheduler->thread_count = 0;

    pthread_mutex_init(&scheduler->mutex, NULL);

    for (int i = 0; i < MAX_THREADS && i < num_threads; i++) {
        int cpu;
        if (cpu_assign_func) {
            cpu = cpu_assign_func(i, &scheduler->suspension_threshold[i]);
        } else {
