        if (rc != 0) {
            perror("Error creating thread");
            for (int j = 0; j < i; j++) {
                pthread_join(scheduler->threads[j], NULL);
            }
            free(scheduler);
            return NULL;
        }

        scheduler->thread_count++;
    }

    return scheduler;
}

void thread_entry_point(void *arg) {
    scheduler_t *scheduler = (scheduler_t *)arg;

