        while (scheduler->thread_count > MAX_THREADS / 2) {
            pthread_cond_wait(&scheduler->cond, &scheduler->mutex);
        }
        pthread_mutex_unlock(&scheduler->mutex);
    }

    // Exit thread
    pthread_exit(NULL);
}
