#include <stdio.err.h>
#include <stdlib.h>
#include <OpenCL/OpenCL.h>

cl_command_queue cl_create_command_queue(cl_context context, cl_device_id device_id) {
    cl_command_queue command_queue = NULL;
    cl_int error_code;

    // Validate input parameters
    if (!context || !device_id) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    // Retrieve context information
    size_t context_info_size = 0;
    error_code = clGetContextInfo(context, CL_CONTEXT_INFO_COMMAND_QUEUE_COUNT, 0, NULL, &context_info_size);
    if (error_code != CL_SUCCESS) {
        fprintf(stderr, "Error retrieving context information: %s\n", clGetErrorName(error_code));
        return NULL;
    }

    // Allocate memory for context info array
    cl_context_info context_info[context_info_size / sizeof(cl_context_info)];
    error_code = clGetContextInfo(context, CL_CONTEXT_INFO_COMMAND_QUEUE_COUNT, context_info_size, context_info, NULL);
    if (error_code != CL_SUCCESS) {
        fprintf(stderr, "Error retrieving context information: %s\n", clGetErrorName(error_code));
        free(context_info);
        return NULL;
    }

    // Find an available command queue
    cl_command_queue existing_queue = context_info[0].command_queues[0];
    for (size_t i = 1; i < context_info_size / sizeof(cl_command_queue); i++) {
        if (!existing_queue && context_info[i].command_queues[0]) {
            existing_queue = context_info[i].command_queues[0];
        }
    }

    // If no available command queue is found, create a new one
    if (!existing_queue) {
        error_code = clCreateCommandQueue(context, device_id, 0, &command_queue);
        if (error_code != CL_SUCCESS) {
            fprintf(stderr, "Error creating command queue: %s\n", clGetErrorName(error_code));
            return NULL;
        }
    } else {
        command_queue = existing_queue;
    }

    return command_queue;
}
