#include <linux/sensor,sensortype.h> /* for sensor_sample_fetch_chan and sensor_channel_get */
#include <linux/kernel.h> /* for printk */
#include <linux/string.h> /* for strerror */

static int read_sensor_data(struct device *dev, int accel_channel, int gyro_channel) {
	struct i2c_client *client = to_i2c_client(dev);
	struct sensor_device_ident *ident;
	struct sensor_data accel_data, gyro_data;
	int ret;

	ident = i2c_get_clientdata(client);

	ret = sensor_channel_get(client, accel_channel, &accel_data);
	if (ret < 0) {
		dev_err(dev, "Failed to read accelerometer data: %s\n", strerror(-ret));
		return ret;
	}

	ret = sensor_sample_fetch_chan(client, gyro_channel, &gyro_data);
	if (ret < 0) {
		dev_err(dev, "Failed to read gyroscope data: %s\n", strerror(-ret));
		return ret;
	}

	/* Ensure resource cleanup */
	ret = sensor_channel_release(client, accel_channel);
	if (ret < 0) {
		dev_err(dev, "Failed to release accelerometer channel: %s\n", strerror(-ret));
		return ret;
	}

	ret = sensor_sample_release(client, gyro_channel);
	if (ret < 0) {
		dev_err(dev, "Failed to release gyroscope channel: %s\n", strerror(-ret));
		return ret;
	}

	printk(KERN_INFO "Accelerometer data: x=%d, y=%d, z=%d\n", accel_data.accel.x, accel_data.accel.y, accel_data.accel.z);
	printk(KERN_INFO "Gyroscope data: ax=%d, ay=%d, az=%d, wx=%d, wy=%d, wz=%d\n",
			gyro_data.accel.x, gyro_data.accel.y, gyro_data.accel.z,
			gyro_data.gyro.x, gyro_data.gyro.y, gyro_data.gyro.z);

	return 0;
}
