int string_rotation(const char *str1, const char *str2) {
  size_t str1_len = strlen(str1);
  size_t str2_len = strlen(str2);

  // Check if str2 is a rotation of str1
  if (str1_len != str2_len) {
    return 0;
  }

  // Concatenate str1 with itself and check if str2 is a substring
  size_t concatenated_len = str1_len * 2 + 1;
  char *concatenated = malloc(concatenated_len);
