#define SECRET_LENGTH 32

char *generate_shared_secret(const char *input, time_t timestamp, int entropy) {
    unsigned char md5_digest[MD5_DIGEST_LENGTH];
    char secret[SECRET_LENGTH + 1];
    unsigned int i;

    // Validate input is not NULL
    if (input == NULL) {
        perror("Input string is NULL");
        return NULL;
    }

    // Generate the data to be hashed
    size_t data_length = strlen(input) + sizeof(timestamp) + sizeof(entropy);
    unsigned char *data = malloc(data_length);
    if (data == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    memcpy(data, input, strlen(input));
    memcpy(data + strlen(input), &timestamp, sizeof(timestamp));
    memcpy(data + strlen(input) + sizeof(timestamp), &entropy, sizeof(entropy));

    // Hash the data using MD5
    MD5_CTX md5_context;
    MD5_Init(&md5_context);
    MD5_Update(&md5_context, data, data_length);
    MD5_Final(md5_digest, &md5_context);

    // Convert the binary digest to a hexadecimal string
    for (i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(secret + i * 2, "%02x", md5_digest[i]);
    }

    // Add null terminator
    secret[SECRET_LENGTH] = '\0';

    free(data);

    return strdup(secret);
}
