#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 4096

typedef struct MarFile {
    FILE *file;
    size_t size;
    char buffer[MAX_LINE_LENGTH];
} MarFile;

MarFile *MarFile_open(const char *path, const char *mode) {
    MarFile *file = malloc(sizeof(MarFile));
    if (!file) {
        perror("Out of memory");
        return NULL;
    }

    file->file = fopen(path, mode);
    if (!file->file) {
        free(file);
        perror("Error opening file");
        return NULL;
    }

    file->size = 0;
    return file;
}

bool MarFile_eof(MarFile *file) {
    return feof(file->file);
}

size_t MarFile_readline(MarFile *file, char *buffer, size_t size) {
    size_t bytes_read = fread(buffer, 1, size - 1, file->file);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        size_t line_length = strlen(buffer);
        if (line_length > 0 && buffer[line_length - 1] == '\n') {
            buffer[line_length - 1] = '\0';
            line_length--;
        }
        file->size += bytes_read;
        return line_length + 1;
    }
    return 0;
}

void MarFile_close(MarFile *file) {
    if (file->file) {
        fclose(file->file);
        free(file);
    }
}

int main() {
    MarFile *file = MarFile_open("input.txt", "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    int line_count = 0;
    while (!MarFile_eof(file)) {
        size_t line_length = MarFile_readline(file, file->buffer, sizeof(file->buffer));
        if (line_length > 0) {
            line_count++;
        }
    }

    MarFile_close(file);

    printf("The file contains %d lines.\n", line_count);

    return EXIT_SUCCESS;
}
