function register_new_class($class_name, $extension_dir, $class_entry) {
  $ini_entries = new SplArrayObject();
  $ini_entries->attach(new ArrayIterator([
    'group' => 'my_extension',
    'name' => $class_name,
    'type' => ZEND_REGISTER_INI_ENTRIES,
  ]));

  zend_register_ini_entries($ini_entries->getArrayCopy());

  $class = new ReflectionClass($class_entry->name);
  $reflector = new ReflectionClass($class_name);

  if (!$class->isSubclassOf($class_entry->name)) {
    throw new Exception("Class '{$class_name}' is not a subclass of '{$class_entry->name}'.");
  }

  $new_class = new ReflectionClass($class_name);
  $new_class->setMethod('__clone', new ReflectionMethod($class, '__clone'));
  $new_class->setMethod('__wakeup', new ReflectionMethod($class, '__wakeup'));

  $new_class->setDefaultProperties([
    'frozen' => true,
  ]);

  $new_class->setModifiers(ReflectionClass::IS_FINAL);

  $reflector->setParentClass($new_class);

  spl_autoload_register(function ($class_name) use ($extension_dir) {
    require "$extension_dir/{$class_name}.php";
  });
}
