char *itoa(int value, int base, char *str) {
    int i = 0;
    int sign = 1;

    if (value < 0) {
        sign = -1;
        value = -value;
    }

    str[i++] = '0' + sign * value / base;
    value %= base;

    while (value) {
        str[i++] = '0' + value / base;
        value %= base;
    }

    str[i] = '\0';

    // Reverse the string
    for (int j = 0; j < i / 2; j++) {
        char temp = str[j];
        str[j] = str[i - j - 1];
        str[i - j - 1] = temp;
    }

    return str;
}
