char *read_line_from_stdin() {
    char *line = NULL;
    size_t len = 0;
    ssize_t bytes_read;

    FD_ZERO(&read_fds);
    FD_SET(STDIN_FILENO, &read_fds);

    timeout.tv_sec = 1;
