#define TIME_FORMAT "%H:%M:%S"
#define TIMEZONE_FORMAT "%[^:]+:%+[0-9]+:%+[0-9]+"

typedef struct {
    time_t time;
    char timezone[16];
} parsed_time;

parsed_time parse_time_string(const char *input) {
    parsed_time result = {0};
    char time_str[32] = {0};
    size_t time_len = sizeof(time_str);
    sscanf(input, "%s%s", time_str, result.timezone);

    if (strlen(time_str) > sizeof(time_str)) {
        // Input string is too long
        return result;
    }

    // Check timezone format
    if (!sscanf(result.timezone, TIMEZONE_FORMAT, NULL, &result.time.tm_hour, NULL, &result.time.tm_min, NULL, &result.time.tm_sec, NULL)) {
        // Invalid timezone format
        return result;
    }

    // Adjust for UTC if timezone is positive
    if (result.time.tm_hour >= 0) {
        result.time -= result.timezone_to_utc(result.time);
    }

    // Parse time string
    if (sscanf(time_str, TIME_FORMAT, &result.time.tm_hour, &result.time.tm_min, &result.time.tm_sec) != 3) {
        // Invalid time format
        return result;
    }

    // Adjust for timezone if it's negative
    if (result.time.tm_hour < 0) {
        result.time += result.timezone_to_utc(result.time);
    }

    // Set timezone to UTC
    result.timezone[0] = '\0';

    return result;
}

time_t parsed_time_to_time_t(const parsed_time *pt) {
    struct tm tm = {0};
    tm.tm_year = pt->time.tm_year - 1900;
    tm.tm_mon = pt->time.tm_mon - 1;
    tm.tm_mday = pt->time.tm_mday;
    tm.tm_hour = pt->time.tm_hour;
    tm.tm_min = pt->time.tm_min;
    tm.tm_sec = pt->time.tm_sec;
    return mktime(&tm);
}

time_t parsed_time_timezone_to_utc(const parsed_time *pt) {
    struct tm tm = {0};
    int hours, minutes;

