            pseudo[i] = ch;
            i++;
            wmove(stdscr, 0, i);
            wprintw(stdscr, "%c", ch);
            refresh();
        }
    }

    if (i > MAX_PSEUDO_LENGTH) {
        clear();
        printw("Pseudo too long!\n");
        refresh();
        return -1;
    }

    pseudo[i] = '\0';
    return 0;
}

void display_score(int score) {
    clear();
    printw("Your score: %d\n", score);
    refresh();
    usleep(500000); // Delay for half a second
