typedef struct HelpEntry {
    char *key;
    char *description;
    struct HelpEntry *next;
} HelpEntry;

void print_help_entry(HelpEntry *entry) {
    if (entry != NULL) {
        printf("Key: %s\nDescription: %s\n---\n", entry->key, entry->description);
    }
}

bool match_keyword(const char *keyword, const char *entry_key) {
    size_t keyword_len = strlen(keyword);
    size_t entry_len = strlen(entry_key);

    if (keyword_len > entry_len) {
        return false;
    }

    return strncmp(keyword, entry_key, keyword_len) == 0;
}

HelpEntry *search_help_list(HelpEntry *head, const char *keyword) {
    HelpEntry *current = head;

    while (current != NULL) {
        pthread_mutex_lock(&current->lock);
        if (match_keyword(keyword, current->key)) {
            print_help_entry(current);
            pthread_mutex_unlock(&current->lock);
            return current;
        }
        current = current->next;
        pthread_mutex_unlock(&current->lock);
    }

    return NULL;
}

void lock_help_entry(HelpEntry *entry) {
    if (entry != NULL) {
        pthread_mutex_lock(&entry->lock);
    }
}

void unlock_help_entry(HelpEntry *entry) {
    if (entry != NULL) {
        pthread_mutex_unlock(&entry->lock);
    }
}

void print_help_list(HelpEntry *head) {
    HelpEntry *current = head;

    while (current != NULL) {
        lock_help_entry(current);
        print_help_entry(current);
        unlock_help_entry(current);
        current = current->next;
    }
}

HelpEntry *create_help_entry(const char *key, const char *description) {
    HelpEntry *new_entry = malloc(sizeof(HelpEntry));

    if (new_entry != NULL) {
        new_entry->key = strdup(key);
        new_entry->description = strdup(description);
        new_entry->next = NULL;
        pthread_mutex_init(&new_entry->lock, NULL);
    }

    return new_entry;
}

HelpEntry *add_help_entry(HelpEntry **head, const char *key, const char *description) {
    HelpEntry *new_entry = create_help_entry(key, description);

    if (new_entry != NULL) {
        HelpEntry *current = *head;

        if (*head == NULL) {
            *head = new_entry;
        } else {
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_entry;
        }
    }

    return new_entry;
}

void free_help_list(HelpEntry *head) {
    HelpEntry *current = head;
    HelpEntry *next;

    while (current != NULL) {
        next = current->next;
        free(current->key);
        free(current->description);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&head->lock);
}
