#include <stdint.h>

typedef struct mpeg_ts_stream {
    uint16_t pid;
    uint8_t *packet_buffer;
    size_t packet_size;
    struct mpeg_ts_stream *next;
} mpeg_ts_stream_t;

int init_mpeg_ts_streams(mpeg_ts_stream_t **streams, size_t num_streams, void *pool) {
    mpeg_ts_stream_t *stream;
    int i;

    for (i = 0; i < num_streams; i++) {
        stream = calloc(1, sizeof(mpeg_ts_stream_t));
        if (!stream) {
            apache_log_error(APLOG_MARK, APLOG_ERR, 0, NULL,
                            "Failed to allocate memory for MPEG-TS stream %d", i);
            return -1;
        }

        stream->pid = i + 1; // Set PID based on index
        stream->packet_buffer = NULL;
        stream->packet_size = 0;
        stream->next = NULL;

        apache_pool_cleanup_register(pool, stream, free, apache_pool_cleanup_null);

        *streams = realloc(*streams, sizeof(mpeg_ts_stream_t) * (num_streams + 1));
        if (!*streams) {
            free(stream);
            apache_log_error(APLOG_MARK, APLOG_ERR, 0, NULL,
                            "Failed to reallocate memory for MPEG-TS streams");
            return -1;
        }

        (*streams)[i] = stream;
    }

    return 0;
}

int allocate_packet(mpeg_ts_stream_t *stream, size_t packet_size, void *pool) {
    if (!(stream->packet_buffer = malloc(packet_size))) {
        apache_log_error(APLOG_MARK, APLOG_ERR, 0, NULL,
                        "Failed to allocate memory for MPEG-TS packet of size %zu",
                        packet_size);
        return -1;
    }

    stream->packet_size = packet_size;

    apache_pool_cleanup_register(pool, stream->packet_buffer, free,
                                apache_pool_cleanup_null);

    return 0;
}
