#define CARD_STRUCT_SIZE sizeof(struct Card)

struct Card {
    enum CardType type;
    char name[50];
};

struct Node {
    struct Card card;
    struct Node *next;
};

void initialize_rng(void) {
    unsigned seed[4];
    seed[0] = time(NULL);
    seed[1] = (unsigned) getpid();
    seed[2] = (unsigned) getppid();
    seed[3] = (unsigned) gettimeofday().tv_usec;
    srand48(seed);
}

struct Node *shuffle_deck(struct Node **deck, int num_cards) {
    struct Node *current = *deck;
    struct Node *next;
    struct Node *new_list = NULL;

    initialize_rng();

    for (int i = 0; i < num_cards; i++) {
        next = malloc(CARD_STRUCT_SIZE + sizeof(struct Node));
        memcpy(&next->card, &current->card, CARD_STRUCT_SIZE);
        next->next = NULL;

        if (new_list == NULL) {
            new_list = next;
            *deck = next;
            continue;
        }

        struct Node *prev = new_list;
        int random_index = (int) lrand48() % (i + 1);

        while (prev->next != NULL && random_index > 0) {
            prev = prev->next;
            random_index--;
        }

        next->next = prev->next;
        prev->next = next;
    }

    return new_list;
}

