#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Athlete {
    int id;
    char name[50];
    int hours;
} Athlete;

void initializeDatabase(Athlete** database, int capacity) {
    *database = malloc(capacity * sizeof(Athlete));
}

bool searchAthleteByCode(const Athlete* database, int size, int code) {
    for (int i = 0; i < size; i++) {
        if (database[i].id == code) {
            return true;
        }
    }
    return false;
}

void addAthlete(Athlete* database, int* size, const char* name, int hours) {
    if (*size == capacity) {
        database = realloc(database, (capacity + 10) * sizeof(Athlete));
    }

    database[*size].id = *size + 1;
    strcpy(database[*size].name, name);
    database[*size].hours = hours;
    (*size)++;
}

void updateAthleteHours(Athlete* database, int size, int code, int newHours) {
    if (!searchAthleteByCode(database, size, code)) {
        printf("Athlete with code %d not found.\n", code);
        return;
    }

    database[code - 1].hours = newHours;
}

int main() {
    int capacity = 10;
    Athlete* database;
    int size = 0;

    initializeDatabase(&database, capacity);

    while (true) {
        printf("\n1. Search for an athlete by code\n");
        printf("2. Add a new athlete\n");
        printf("3. Update the number of hours for an existing athlete\n");
        printf("4. Exit\n");

        int choice;
        scanf("%d", &choice);

        switch (choice) {
            case 1: {
                int code;
                printf("Enter athlete code: ");
                scanf("%d", &code);
                if (searchAthleteByCode(database, size, code)) {
                    printf("Athlete %s (ID: %d) found.\n", database[code - 1].name, database[code - 1].id);
                    printf("Current hours: %d\n", database[code - 1].hours);
                } else {
                    printf("Athlete not found.\n");
                }
                break;
            }
            case 2: {
                char name[50];
                int hours;
                printf("Enter athlete name: ");
                scanf("%s", name);
                printf("Enter athlete hours: ");
                scanf("%d", &hours);
                addAthlete(database, &size, name, hours);
                printf("Athlete %s (ID: %d) added.\n", name, database[size - 1].id);
                break;
            }
            case 3: {
                int code, newHours;
                printf("Enter athlete code: ");
                scanf("%d", &code);
                printf("Enter new athlete hours: ");
                scanf("%d", &newHours);
                updateAthleteHours(database, size, code, newHours);
                printf("Athlete %s (ID: %d) hours updated.\n", database[code - 1].name, database[code - 1].id);
                break;
            }
            case 4:
                free(database);
                return 0;
            default:
                printf("Invalid choice.\n");
        }
    }

    return 0;
}
