#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <errno.h>
#include <sys/types.h>
#include <unistd.h>
#include <stdint.h>

typedef struct {
    uint32_t base_addr;
    uint16_t sector_count;
    uint16_t bank_width;
} device_memory_info_t;

void parse_range_string(const char *range_str, uint32_t *start, uint32_t *end) {
    size_t len = strlen(range_str);
    bool valid = true;

    if (len < 6 || strncmp(range_str, "0x", 2) != 0) {
        valid = false;
    } else {
        sscanf(range_str + 2, "%x%x", start, end);
    }

    if (!valid) {
        fprintf(stderr, "Invalid range string: %s\n", range_str);
        exit(EXIT_FAILURE);
    }
}

void check_pointer(const void *ptr, const char *name) {
    if (ptr == NULL) {
        fprintf(stderr, "Error: %s pointer is NULL\n", name);
        exit(EXIT_FAILURE);
    }
}

void print_device_memory_info(const device_memory_info_t *info) {
    printf("Base address: 0x%08x\n", info->base_addr);
    printf("Sector count: %d\n", info->sector_count);
    printf("Bank width: %d bytes\n", info->bank_width);
    printf("End address: 0x%08x\n", info->base_addr + info->sector_count * info->bank_width);
}

void set_env_variables(const char *device_name, const device_memory_info_t *info) {
    char base_addr_str[32];
    char end_addr_str[32];

    snprintf(base_addr_str, sizeof(base_addr_str), "%lx", (long)info->base_addr);
    snprintf(end_addr_str, sizeof(end_addr_str), "%lx", (long)info->base_addr + info->sector_count * info->bank_width);

    setenv(device_name "_BASE_ADDRESS", base_addr_str, 1);
    setenv(device_name "_SECTOR_COUNT", itoa(info->sector_count), 1);
    setenv(device_name "_END_ADDRESS", end_addr_str, 1);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <device_ptr> <range_string>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    check_pointer(argv[1], "device_ptr");

    device_memory_info_t info;
    char range_str[32];

    strcpy(range_str, argv[2]);
    parse_range_string(range_str, &info.base_addr, &info.sector_count);

    info.bank_width = (info.sector_count * sizeof(uint32_t));

    print_device_memory_info(&info);
    set_env_variables("DEVICE", &info);

    return EXIT_SUCCESS;
}
