int search_files(const char *pattern, const char *start_dir, int *matching_files) {
    int count = 0;
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;

    if (!(dir = opendir(start_dir))) {
        perror("opendir");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", start_dir, entry->d_name);

        if (stat(file_path, &file_stat) < 0) {
            perror("stat");
            continue;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            continue;
        }

        if (strstr(entry->d_name, pattern) != NULL) {
            count++;
        }
    }

    closedir(dir);
    *matching_files = count;
    return count;
}
