        ptr += sprintf(ptr, "%d.", DNS_TYPE_PTR);
        ptr += sprintf(ptr, "%d.", 4 * 60); // TTL is 4 minutes
        ptr += sprintf(ptr, "%d.", sizeof(dns_record) + name_len); // Length of the record

        // Initialize a temporary dns_record to fill in the data
