        // Copy the record data to the buffer
        memcpy(ptr, &record, sizeof(record));
        ptr += sizeof(record);

        // Copy the name to the buffer
        memcpy(ptr, record.name, name_len);
        ptr += name_len;

        current_position += sizeof(dns_record) + name_len;
    }

    // Set the final record type and length in the buffer
    ptr -= sizeof(dns_record);
    dns_record final_record;
