#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>

#define MAX_FILE_NAME_LENGTH (GIT_PATH_MAX - sizeof("/my_output_file.ext"))

typedef struct {
    char filename[MAX_FILE_NAME_LENGTH + 1];
    size_t len;
} file_name_info_t;

bool is_valid_file_name(const char *line) {
    size_t line_len = strlen(line);
    if (line_len < 6 || strncmp(line, "open ", 5) != 0) {
        return false;
    }
    size_t fileName_start = 5;
    while (fileName_start < line_len && (line[fileName_start] != ' ' && line[fileName_start] != '\t')) {
        fileName_start++;
    }
    size_t fileName_len = line_len - fileName_start;
    if (fileName_len > MAX_FILE_NAME_LENGTH) {
        return false;
    }
    return true;
}

size_t parse_file_name(const char *buffer, size_t buffer_size, file_name_info_t *file_name_info) {
    size_t index = 0;
    while (index < buffer_size) {
        const char *line_start = buffer + index;
        size_t line_len = 0;
        while (line_len == 0 || (buffer[index] != '\n' && index < buffer_size)) {
            if (index + 1 >= buffer_size) {
                return 0;
