        strncpy(file_name_info->filename, line_start + 5, MAX_FILE_NAME_LENGTH);
        file_name_info->len = strlen(file_name_info->filename);
        if (file_name_info->len > MAX_FILE_NAME_LENGTH) {
            return 0;
        }
        return file_name_info->len;
    }
    return 0;
}
