// Helper function to adjust the scale parameter
void adjust_scale(double *value, int *scale) {
    *scale = (*scale > 0) ? *scale : 0;
    *value *= pow(10, *scale);
}

// Function to display a floating-point number in engineering format
void num_to_engineering_str(double num, int *buf_size, char *buf) {
    int scale = 0;
    int exp = 0;
    double man = modf(num, &num);

    adjust_scale(&num, &scale);

    if (isnan(num)) {
        snprintf(buf, *buf_size, "NaN");
        return;
    }

