bool is_safe_filename(const char *filename) {
  size_t i;
  static const char *unsafe_chars = "/\\\0%:;*?\"<>|";

  for (i = 0; filename[i] != '\0'; i++) {
    if (strchr(unsafe_chars, filename[i]) != NULL) {
