  size_t extension_len = strlen(extension);
  size_t total_len = filename_len + extension_len + 1; // +1 for null terminator
  char *new_string = NULL;

  // Allocate memory for new string
  new_string = calloc(total_len, sizeof(char));
  if (new_string == NULL) {
    perror("calloc failed");
    return NULL;
  }

  // Concatenate file name and extension
  strncat(new_string, filename, filename_len + 1); // +1 for null terminator of filename
  strncat(new_string, extension, extension_len + 1); // +1 for null terminator of extension

  // Validate filename for safety
  if (!is_safe_filename(new_string)) {
