#include <stdio.h>
#include <stdlib.h>
#include <pcap.h>
#include <string.h>

#define MAX_FILTER_LEN 256

int set_pcap_filter(pcap_t *handle, struct bpf_program *prog, char *filter) {
    char error_buffer[PCAP_ERRBUF_SIZE];
    char temp_filter[MAX_FILTER_LEN];

    if (handle == NULL || prog == NULL || filter == NULL) {
        snprintf(error_buffer, PCAP_ERRBUF_SIZE, "Invalid input parameters: handle=%p, prog=%p, filter=%s\n", handle, prog, filter);
        perror(error_buffer);
        return -1;
    }

    strncpy(temp_filter, filter, MAX_FILTER_LEN);
    temp_filter[MAX_FILTER_LEN - 1] = '\0'; // Ensure null termination

    if (pcap_compile(handle, prog, temp_filter, 1, 0) < 0) {
        snprintf(error_buffer, PCAP_ERRBUF_SIZE, "Error compiling filter expression: %s\n", pcap_geterr(handle));
        perror(error_buffer);
        return -1;
    }

    if (pcap_setfilter(handle, prog) < 0) {
        snprintf(error_buffer, PCAP_ERRBUF_SIZE, "Error setting filter expression: %s\n", pcap_geterr(handle));
        perror(error_buffer);
        return -1;
    }

    return 0;
}
