#define MAX_FILENAME_LENGTH 256

void write_image_header(FILE *file) {
    // Standard header information
    uint32_t header[2];
    header[0] = 0x20594444; // DDS 'DDPI'
    header[1] = 0x20445354; // DDS 'DDSS'

    // Table image header information
    uint32_t table_header[11];
    table_header[0] = 0x20444453; // DDS 'DDIT'
    table_header[1] = sizeof(table_header);
    table_header[2] = 0; // Reserved
    table_header[3] = 0; // Height
    table_header[4] = 0; // Width
    table_header[5] = 1; // Layer count
    table_header[6] = 0; // Mipmap count
    table_header[7] = 0; // Reserved
    table_header[8] = 0; // Caps1
    table_header[9] = 0; // Caps2
    table_header[10] = 0; // Caps3

    // Write header and table image header to file
    CFE_FS_WriteHeader(file, 0, sizeof(header), header);
    CFE_PSP_MemCpy(file, &table_header, sizeof(table_header));
}

int create_image_file(const char *filename) {
    FILE *file = NULL;
    int err_rc = CFE_SUCCESS;

    // Validate filename
    if (strlen(filename) > MAX_FILENAME_LENGTH) {
        err_rc = CFE_INVALID_ARGUMENT;
        goto error;
    }

    // Open file for writing and check if it already exists
    file = fopen(filename, "wbin");
    if (file == NULL) {
        err_rc = CFE_FILE_ERROR;
        goto error;
    }

    if (ferror(file)) {
        err_rc = CFE_FILE_ERROR;
        goto error;
    }

    if (feof(file)) {
        err_rc = CFE_FILE_ERROR;
        goto error;
    }

    // Write image header to file
    write_image_header(file);

    // Close file
    fclose(file);

    return CFE_SUCCESS;

error:
    if (file != NULL) {
        fclose(file);
    }
    return err_rc;
}
