void print_key_values(const unsigned char *key, size_t key_len) {
    if (key_len > 0) {
        int i;
        size_t fmt_len = strlen(KEY_PRINT_FORMAT);
        char buffer[fmt_len + 32]; // +32 for key and intermediate values

        snprintf(buffer, sizeof(buffer), KEY_PRINT_FORMAT, key_len, (char *)key, "", "");
        fputs(buffer, stdout);

        // Generate intermediate values
        unsigned char iv[EVP_MAX_IV_LENGTH];
        EVP_BytesToKey(EVP_aes_128(), EVP_md5(), NULL, key, key_len, iv, 2);
        char iv_str[33]; // +1 for null terminator

        for (i = 0; i < EVP_MAX_IV_LENGTH; i++) {
            snprintf(iv_str + i * 2, sizeof(iv_str) - i * 2, "%02x", iv[i]);
        }

        snprintf(buffer, sizeof(buffer), KEY_PRINT_FORMAT, "", iv_str, iv_str + 16);
        fputs(buffer, stdout);
    }
}

void generate_and_print_key(size_t key_len) {
    unsigned char *key;
    sem_wait(&semaphore);

    key = malloc(key_len);
    if (key == NULL) {
        sem_post(&semaphore);
        fprintf(stderr, "Failed to allocate memory for key\n");
        return;
    }

    if (EVP_BytesToKey(EVP_aes_128(), EVP_md5(), NULL, NULL, 0, key, 1) <= 0) {
        free(key);
        sem_post(&semaphore);
        fprintf(stderr, "Failed to generate key\n");
        return;
    }

    print_key_values(key, key_len);
    free(key);
    sem_post(&semaphore);
}

