#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/param.h>
#include <nvpair.h>

#define MAX_PATH_LEN (PATH_MAX + 16) /* Add 16 for parity level and null terminator */

char *raidz_path_with_parity(const char *input_path, int device_id) {
    char *path = calloc(MAX_PATH_LEN, sizeof(char));
    int rc;
    nvlist_t *config;
    uint64_t parity_level;

    if (!path) {
        perror("Calloc failed");
        return NULL;
    }

    strlcpy(path, input_path, MAX_PATH_LEN);

    config = nvlist_create(NV_READONLY, 0);
    rc = nvlist_add_int64(config, "device", device_id, 0);
    if (rc != 0) {
        perror("Failed to add device id to config list");
        free(path);
        nvlist_destroy(config);
        return NULL;
    }

    rc = nvlist_lookup_uint64(config, "parity_level", &parity_level);
    if (rc != 0) {
        perror("Failed to get parity level from config");
        free(path);
        nvlist_destroy(config);
        return NULL;
    }

    if (rc == 0 && parity_level != 0) {
        size_t len = strlen(path);
        if (len + 19 > MAX_PATH_LEN) {
            free(path);
            nvlist_destroy(config);
            return NULL;
        }

        snprintf(path + len, MAX_PATH_LEN - len, "_p%llx", parity_level);
    }

    nvlist_destroy(config);
    return path;
}
```

