#define MAX_VERTICES 100

typedef struct Vertex {
    int id;
    char name[50];
    int in_degree;
    int out_degree;
    struct Vertex *next;
} Vertex;

Vertex *vertices[MAX_VERTICES];

void display_graph() {
    for (int i = 0; i < MAX_VERTICES; i++) {
        if (vertices[i]) {
            printf("Vertex %d: %s\n", vertices[i]->id, vertices[i]->name);
            for (Vertex *v = vertices[i]; v; v = v->next) {
                printf(" -> %d\n", v->id);
            }
        }
    }
}

void modify_vertex(int id, const char *new_name) {
    if (id < 0 || id >= MAX_VERTICES || !vertices[id]) {
        printf("Error: Invalid vertex id.\n");
        return;
    }
    strcpy(vertices[id]->name, new_name);
