    int ret;
    int iv_len = EVP_CIPHER_iv_length(EVP_CIPHER_ctx_get_algorithm(ctx));
    unsigned char iv[iv_len];

    // Initialize the context with the key and IV
    if (encrypt) {
        ret = EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
