#define MAX_LINE_LENGTH 79

void display_message(const char *message, int importance) {
    size_t message_length = strlen(message);
    size_t lines_needed = (message_length + MAX_LINE_LENGTH - 1) / MAX_LINE_LENGTH;
    size_t current_line_length = 0;
    char *line_buffer = malloc(MAX_LINE_LENGTH + 1);

    if (!line_buffer) {
        fprintf(stderr, "Error: Failed to allocate memory for line buffer\n");
        return;
    }

    for (size_t i = 0; i < lines_needed; ++i) {
        size_t line_length = MIN(message_length - (i * MAX_LINE_LENGTH), MAX_LINE_LENGTH);

        strncpy(line_buffer, message + (i * MAX_LINE_LENGTH), line_length);
        line_buffer[line_length] = '\0';

        printf("%s%s", (i > 0 ? "\n" : ""), line_buffer);
        fflush(stdout);
        usleep(100000); // Delay between lines for readability

        current_line_length += line_length + 1; // 1 for the newline character
