void aes_128_ctr_encrypt(uint8_t *input, size_t input_len, const uint8_t *key_schedule) {
    AES_KEY aes_key;
    uint8_t iv[AES_BLOCK_SIZE];
    size_t block_size = AES_BLOCK_SIZE;
    size_t i;

    // Initialize AES key
    AES_set_encrypt_key(key_schedule, 128, &aes_key);

    // Initialize counter with IV
    memset(iv, 0, block_size);

    for (i = 0; i < input_len; i += block_size) {
