#include <stdlib.h>
#include <string.h>

size_t string_length(const char *str);

char *concat_strings(const char *str1, const char *str2) {
    size_t len1 = string_length(str1);
    size_t len2 = string_length(str2);
    size_t total_length = len1 + len2 + 1; // +1 for null terminator
    char *result = malloc(total_length);

    if (result == NULL) {
        free(result);
        return NULL;
    }

    strcpy(result, str1);
    strcat(result, str2);
    result[total_length - 1] = '\0'; // Ensure null terminator is present

    return result;
}

size_t string_length(const char *str) {
    size_t len = 0;
    while (str[len] != '\0') {
        len++;
    }
    return len;
}
