#define SECRET_LENGTH 32

void string_to_hex(unsigned char input[], char output[2 * SECRET_LENGTH + 1]) {
    for (int i = 0; i < SECRET_LENGTH; i++) {
        sprintf(output + (i * 2), "%02x", input[i]);
    }
    output[2 * SECRET_LENGTH] = '\0';
}

void generate_shared_secret(const char *path, int timestamp) {
    MD5_CTX md5;
    unsigned char digest[MD5_DIGEST_LENGTH];
    char path_str[256];
    char timestamp_str[11];

    // Validate input length
    if (strlen(path) > 255 || sizeof(timestamp_str) < (1 + (int)sprintf(timestamp_str, "%d", timestamp))) {
        fprintf(stderr, "Invalid input length\n");
        return;
    }

    // Initialize the MD5 context
    MD5_Init(&md5);

    // Convert path to MD5 input
    strcpy(path_str, path);
    for (size_t i = 0; i < strlen(path_str); i++) {
        path_str[i] = tolower(path_str[i]);
    }
    MD5_Update(&md5, path_str, strlen(path_str));

    // Convert timestamp to MD5 input
    sprintf(timestamp_str, "%d", timestamp);
    MD5_Update(&md5, ltostr(timestamp), strlen(ltostr(timestamp)));

    // Generate the final hash
    MD5_Final(digest, &md5);

    // Convert hash to hexadecimal string
    char secret[2 * MD5_DIGEST_LENGTH + 1];
    string_to_hex(digest, secret);

    // Print or return the shared secret
