void insert_line(char *buffer, size_t *size, size_t cursor_pos, const char *line) {
    size_t line_length = strlen(line);
    size_t new_size;
    char *new_buffer;

    // Check if there's enough space to insert the new line
    if (*size < cursor_pos + line_length + 1) {
        new_size = cursor_pos + line_length + 1;
        new_buffer = realloc(buffer, new_size);

