#include <windows.h>
#include <string.h>
#include <stdlib.h>

#define JAVA_REG_KEY "HKEY_LOCAL_MACHINE\\SOFTWARE\\Wow6432Node\\JavaSoft\\Java Runtime Environment"
#define JAVA_VERSION_VALUE_NAME "CurrentVersion"

typedef struct {
    DWORD type;
    WCHAR data[MAX_PATH];
} REG_VALUE;

int get_jre_path(WCHAR* jre_path, size_t jre_path_size) {
    HKEY hKey;
    LONG result;
    REG_VALUE value;

    result = RegOpenKeyEx(HKEY_LOCAL_MACHINE, JAVA_REG_KEY, 0, KEY_READ, &hKey);
    if (result != ERROR_SUCCESS) {
        return 1;
    }

    result = RegQueryValueEx(hKey, JAVA_VERSION_VALUE_NAME, NULL, NULL, (LPBYTE)&value, sizeof(value));
    if (result != ERROR_SUCCESS) {
        RegCloseKey(hKey);
        return 1;
    }

    size_t version_len = wcslen(value.data);
    if (version_len > jre_path_size) {
        RegCloseKey(hKey);
        return 1;
    }

    wcsncpy(jre_path, value.data, jre_path_size);
    jre_path[jre_path_size] = '\0';

    RegCloseKey(hKey);
    return 0;
}
