#include <iostream>
#include <map>
#include <vector>
#include <cstdlib>

struct Quad {
  int texture_id;
  float x, y, width, height;
};

void initQuads(int num_quads, std::map<int, int> texture_counts, Quad*& quads) {
  quads = new Quad[num_quads];
  if (!quads) {
    std::cerr << "Error: Failed to allocate memory for quads.\n";
    return;
  }

  int current_texture = -1;
  for (int i = 0; i < num_quads; ++i) {
    int texture_id = texture_counts.empty() ? -1 : texture_counts.begin()->first;
    if (texture_id != current_texture) {
      if (current_texture >= 0) {
        ++current_texture;
        continue;
      }
      texture_id = 0; // Default texture
    }

    quads[i].texture_id = texture_id;
    quads[i].x = static_cast<float>(i % 10) / 10.0f;
    quads[i].y = static_cast<float>(i / 10) / 10.0f;
    quads[i].width = 1.0f;
    quads[i].height = 1.0f;

    ++current_texture;
  }
}

void freeQuads(Quad* quads, int num_quads) {
  delete[] quads;
}
