// Function to retrieve all entity IDs on a specified layer from the database
std::vector<std::string> getEntitiesByLayer(const std::string& layerName) {
    try {
        // Initialize MongoDB connection
        auto client = std::make_unique<mongocxx::instance::default_service_context>().createClient(mongocxx::uri{});

        // Connect to the database
        auto database = client->get_database("your_database_name");

        // Create a collection reference
