#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <cstddef>

enum Tile { EMPTY, WALL, FLOOR };

std::vector<std::vector<Tile>> load_map_from_string(const std::string& map_str) {
    size_t num_rows = 0;
    size_t delimiter_pos = 0;
    std::stringstream ss(map_str);
    std::vector<std::vector<Tile>> map;

    while (std::getline(ss, map_str, '\n')) {
        std::vector<Tile> row;
        std::stringstream row_ss(map_str);
        std::string tile_str;

        while (std::getline(row_ss, tile_str, ',')) {
            if (tile_str.empty()) {
                std::cerr << "Invalid map string: empty tile value" << std::endl;
                return map;
            }

            Tile tile;
            if (tile_str == "WALL") {
                tile = WALL;
            } else if (tile_str == "FLOOR") {
                tile = FLOOR;
            } else {
                std::cerr << "Invalid map string: unknown tile value '" << tile_str << "'" << std::endl;
                return map;
            }

            row.push_back(tile);
        }

        if (row.size() == 0) {
            std::cerr << "Invalid map string: missing tiles in row" << std::endl;
            return map;
        }

        map.push_back(row);
        num_rows++;
    }

    if (ss.fail()) {
        std::cerr << "Invalid map string: unexpected end of stream" << std::endl;
        return map;
    }

    if (num_rows == 0) {
        std::cerr << "Invalid map string: empty map" << std::endl;
        return map;
    }

    return map;
}
