class PagePool {
private:
    std::map<int, std::unique_ptr<PageData>> pages;

public:
    PagePool() = default;

    // Create a new page with the given identifier and initialize the page data with the provided pointer
    void create_page(int page_id, char* page_data) {
        if (pages.find(page_id) != pages.end()) {
            std::cerr << "Error: Page with ID " << page_id << " already exists.\n";
            return;
        }

        pages[page_id] = std::make_unique<PageData>(PageData{page_id, page_data});
