void generateWireframeIndices(const int* inputArray, size_t size, int*& points, int*& lines, int*& faces, int*& lineLines, int& primitiveCount) {
    // Allocate memory for output arrays using std::vector for easier memory management
    std::vector<int> tempPoints(size);
    std::vector<std::vector<int>> tempLines;
    std::vector<std::vector<int>> tempFaces;

