#include <iostream>
#include <string>
#include <vector>
#include <random>

struct Triangle {
    double x1, y1;
    double x2, y2;
    double x3, y3;

    Triangle(double x1_, double y1_, double x2_, double y2_, double x3_, double y3_) : x1(x1_), y1(y1_), x2(x2_), y2(y2_), x3(x3_), y3(y3_) {}

    ~Triangle() {
        std::cout << "Deleted triangle: (" << x1 << ", " << y1 << "), (" << x2 << ", " << y2 << "), (" << x3 << ", " << y3 << ")\n";
    }

    void print() const {
        std::string output = "Triangle {" +
