constexpr size_t N = 1024; // Input array size

__global__ void randomize_host(float* h_data) {
  int idx = threadIdx.x + threadIdx.y * gridDim.x;
  h_data[idx] = static_cast<float>(rand() % 1024);
}

__global__ void copy_to_device(const float* h_data, float* d_data) {
  int idx = threadIdx.x + threadIdx.y * gridDim.x;
  d_data[idx] = h_data[idx];
}

__global__ void perform_fft(float* d_data, cufftComplex* plan) {
  cufftExecC2C(plan, d_data, d_data, CUFFT_C2C, 1);
}

__global__ void copy_back_to_host(float* h_data, const float* d_data) {
  int idx = threadIdx.x + threadIdx.y * gridDim.x;
  h_data[idx] = d_data[idx];
}

int main() {
  float* h_data_host;
  float* h_data_device;
  float* d_data_device;
  cufftComplex* plan;

  // Allocate host memory
  h_data_host = static_cast<float*>(malloc(N * N * sizeof(float)));

  // Allocate device memory
  cudaMalloc(&h_data_device, N * N * sizeof(float));
  cudaMalloc(&d_data_device, N * N * sizeof(float));

