  dim3 threads(N, N);
  dim3 blocks(std::ceil(static_cast<float>(N) / 256.0f), std::ceil(static_cast<float>(N) / 256.0f));
  randomize_host<<<blocks, threads>>>(h_data_host);
  cudaDeviceSynchronize();

  // Copy host data to device
  dim3 threads_copy(N, N);
  dim3 blocks_copy(std::ceil(static_cast<float>(N) / 256.0f), std::ceil(static_cast<float>(N) / 256.0f));
  copy_to_device<<<blocks_copy, threads_copy>>>(h_data_host, h_data_device);
  cudaDeviceSynchronize();

  // Initialize cuFFT plan
  cufftPlan2d(&plan, N, N, CUFFT_R2C, CUFFT_FORWARD);

  // Perform FFT on device memory
  perform_fft<<<1, 1>>>(d_data_device, plan);
  cudaDeviceSynchronize();

  // Copy FFT result back to host memory
  copy_back_to_host<<<blocks, threads>>>(h_data_host, d_data_device);
  cudaDeviceSynchronize();

  // Free memory
  free(h_data_host);
  cudaFree(h_data_device);
  cudaFree(d_data_device);
