std::vector<uint8_t> expectedOutput;

void readAndVerifyPixels(GLuint framebuffer, GLenum format, GLenum type, GLsizei width, GLsizei height) {
    // Allocate read buffer
    std::unique_ptr<uint8_t[], decltype(&std::free)> readBuffer(static_cast<uint8_t*>(std::malloc(width * height * GetSizeOfPixelFormat(format, type))), std::free);
    if (readBuffer.get() == nullptr) {
