        std::exit(EXIT_FAILURE);
    }

    // Read pixels from framebuffer
    glReadPixels(0, 0, width, height, format, type, readBuffer.get());
    if (glGetError() != GL_NO_ERROR) {
        std::cerr << "Error reading pixels: " << gluErrorString(glGetError()) << std::endl;
        std::free(readBuffer.release());
        std::exit(EXIT_FAILURE);
    }

    // Validate pixel format and type
    if (format != GL_RGBA || type != GL_UNSIGNED_BYTE) {
        std::cerr << "Invalid pixel format or type" << std::endl;
        std::free(readBuffer.release());
        std::exit(EXIT_FAILURE);
    }

    // Compare pixels with expected output
    if (width * height != expectedOutput.size()) {
        std::cerr << "Mismatched buffer sizes" << std::endl;
        std::free(readBuffer.release());
        std::exit(EXIT_FAILURE);
    }

    if (memcmp(readBuffer.get(), expectedOutput.data(), width * height) != 0) {
        std::cerr << "Mismatched pixel data" << std::endl;
        std::free(readBuffer.release());
        std::exit(EXIT_FAILURE);
    }

    // Zero read buffer for security
    std::memset(readBuffer.get(), 0, width * height * GetSizeOfPixelFormat(format, type));
}

