public byte[] generatePPMImage(PageDocument document, int pageNumber) throws IOException {
    PDDocument pdDocument = document;
    PDPage page = pdDocument.getPage(pageNumber);
    PDRectangle mediaBox = page.getMediaBox();
    float width = 512f; // Display width
    float height = 512f; // Display height
    BufferedImage image = new BufferedImage(
            (int) Math.ceil(mediaBox.getWidth() * width / mediaBox.getHeight() * height),
            (int) Math.ceil(mediaBox.getHeight() * width / mediaBox.getWidth() * height),
            BufferedImage.TYPE_INT_RGB);

