    contentStream.setFillColor(PDColor.WHITE);
    contentStream.fillRect(0, 0, mediaBox.getWidth(), mediaBox.getHeight());
    PDImageXObject pdImage = contentStream.createImageWithBackground(image, Color.WHITE);
    contentStream.drawImage(pdImage, 0, 0, mediaBox.getWidth(), mediaBox.getHeight());
    contentStream.close();

    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    ImageIO.write(image, "png", outputStream);
    byte[] imageData = outputStream.toByteArray();

    ByteArrayInputStream inputStream = new ByteArrayInputStream(imageData);
    int[] pixels = ImageIO.read(inputStream, "png", new int[image.getWidth() * image.getHeight()])
            .flatMapToInt(Arrays::intValue).map(this::getRedValue).toArray();

    byte[] ppmImageData = new byte[image.getWidth() * image.getHeight() * 3];
    for (int i = 0; i < pixels.length; i++) {
        int index = i * 3;
        ppmImageData[index] = (byte) (pixels[i] & 0xff);
        ppmImageData[index + 1] = (byte) (pixels[i] >> 8 & 0xff);
        ppmImageData[index + 2] = (byte) (pixels[i] >> 16 & 0xff);
    }

    pdDocument.close();
    return ppmImageData;
}

private int getRedValue(int pixel) {
    return (pixel >> 16) & 0xff;
}
