#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Node {
    std::string name;
    double duration;
    Node* children;
    size_t num_children;

    Node(const std::string& name, double duration) : name(name), duration(duration), children(nullptr), num_children(0) {}
};

void print_node(const Node* node, const std::vector<double>& transform_matrix, std::ostream& out) {
    if (node == nullptr) {
        return;
    }

    std::stringstream name_stream;
    name_stream << node->name;
    std::string monospaced_name;

    // Apply transformation matrix to name
    for (size_t i = 0; i < name_stream.str().size(); ++i) {
        char c = name_stream.str()[i];
        monospaced_name += (transform_matrix[i] >= 0.0) ? c : ' ';
    }

    out << monospaced_name << ": " << node->duration << std::endl;

    for (size_t i = 0; i < node->num_children; ++i) {
        print_node(node->children[i], transform_matrix, out);
    }
}

void traverse_tree_and_print(const Node* root, const std::vector<double>& transform_matrix, std::ostream& out) {
    if (root == nullptr) {
        return;
    }

    print_node(root, transform_matrix, out);
    traverse_tree_and_print(root->children, transform_matrix, out);
}
