// Function to generate random values for a vector
void fill_random(vector<vector<int>>& image, int width, int height) {
    default_random_engine generator;
    uniform_int_distribution<int> distribution(0, 255);

    image.resize(height);
    for (auto& row : image) {
        row.resize(width);
        for (auto& pixel : row) {
            pixel = distribution(generator);
        }
    }
}

