#include <iostream>
#include <deque>
#include <list>
#include <memory>
#include <thread>
#include <mutex>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <cstring>
#include <cerrno>
#include <stdexcept>

const int MAX_QUEUE_SIZE = 1024;
const int PORT = 8080;

class Connection {
public:
    int socket;
    struct sockaddr_in addr;

    Connection(int sock, const struct sockaddr_in& addr) : socket(sock), addr(addr) {}

    ~Connection() {
        close(socket);
    }
};

std::deque<std::unique_ptr<Connection>> connections;
std::mutex connections_mutex;

void handle_connection(std::unique_ptr<Connection>& connection) {
    char buffer[1024];
    int bytes_received;

    while ((bytes_received = recv(connection->socket, buffer, sizeof(buffer), 0)) > 0) {
        // Process the message here
        std::cout << "Received message: " << buffer << std::endl;

        // Send a response message
        send(connection->socket, "Hello, client!", 13, 0);
    }

    if (bytes_received == -1) {
        if (errno != ECONNRESET && errno != EPIPE) {
            throw std::runtime_error("Error handling connection");
        }
    }

    // Remove the connection from the queue
    std::lock_guard<std::mutex> lock(connections_mutex);
    connections.pop_front();
}

void accept_connections() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);

    if (server_socket == -1) {
        perror("socket()");
        throw std::runtime_error("Error creating socket");
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind()");
        close(server_socket);
        throw std::runtime_error("Error binding socket");
    }

    if (listen(server_socket, MAX_QUEUE_SIZE) == -1) {
        perror("listen()");
        close(server_socket);
        throw std::runtime_error("Error listening on socket");
    }

    while (true) {
        struct sockaddr_in client_addr;
        socklen_t client_addr_len = sizeof(client_addr);
        int new_connection = accept(server_socket, (struct sockaddr*)&client_addr, &client_addr_len);

        if (new_connection == -1) {
            if (errno != EAGAIN && errno != EINTR) {
                perror("accept()");
                continue;
            }
            continue;
        }

        std::unique_ptr<Connection> connection(new Connection(new_connection, client_addr));
        {
            std::lock_guard<std::mutex> lock(connections_mutex);
            connections.push_back(std::move(connection));
        }

        std::thread thread(handle_connection, std::move(connection));
        thread.detach();
    }
}

int main() {
    std::thread accept_thread(accept_connections);
    accept_thread.join();

    return 0;
}
