// Function to compute the hash value of a string using a cryptographic hash function
void hash_string(const uint8_t *data, size_t size, uint8_t *hash) {
    // Initialize the cryptographic hash function
    crypto_hash_init(hash);

    // Process the data in chunks
    size_t chunk_size = 64; // Reasonable chunk size
    while (size > 0) {
        if (validate_size(chunk_size)) {
            crypto_hash_update(hash, data, chunk_size);
            size -= chunk_size;
            data += chunk_size;
        } else {
