            crypto_hash_finalize(hash); // Ensure proper cleanup of the hash function
            // Re-initialize the hash function with a new valid chunk size
            crypto_hash_init(hash);
            chunk_size = 64; // Set a new valid chunk size
        }
    }

    // Finalize the hash function
    crypto_hash_finalize(hash);
}

// Function to compute the hash value of a string and return it as a hexadecimal string
char* hash_string_hex(const char *input, size_t size) {
    // Validate the input size_t is greater than zero
    if (!validate_size(size)) {
        return NULL;
    }

    // Allocate memory for the hash value and the temporary buffer
    size_t hash_size = crypto_hash_size();
