char *calculate_discid(const CDIO_CD_ROM *cd) {
    int i;
    uint64_t sum = 0;
    int num_tracks = cdio_getnumtracks(cd);

    if (num_tracks <= 0) {
        fprintf(stderr, "ERROR: Invalid CD with no tracks\n");
