#include <vector>
#include <unordered_map>
#include <algorithm>
#include <cmath>

using namespace std;

struct Node {
    int id;
    vector<int> neighbors;
};

double Modularity(const vector<Node>& graph, int num_communities) {
    unordered_map<int, int> community;
    double modularity = 0.0;

    for (int i = 0; i < graph.size(); ++i) {
        community[graph[i].id] = i;
    }

    for (int i = 0; i < graph.size(); ++i) {
        int my_community = community[i];
        for (auto neighbor : graph[i].neighbors) {
            int neighbor_community = community[neighbor];
            if (neighbor_community != my_community) {
                modularity += (double)graph[i].neighbors.size() * (double)graph[neighbor].neighbors.size() / (2.0 * num_communities * num_communities);
            }
        }
    }

    return modularity;
}

vector<int> FindBestCommunity(const vector<Node>& graph, int num_communities, int& best_modularity) {
    vector<int> community(graph.size(), -1);
    vector<double> potential(graph.size(), 0.0);

    for (int i = 0; i < graph.size(); ++i) {
        int my_community = community[i];
        double potential_sum = 0.0;

        for (auto neighbor : graph[i].neighbors) {
            int neighbor_community = community[neighbor];
            if (neighbor_community != my_community) {
                potential_sum += (double)graph[i].neighbors.size() * (double)graph[neighbor].neighbors.size() / (2.0 * (num_communities - 1.0) * num_communities);
            }
        }

        potential[i] = potential_sum;
    }

    sort(potential.begin(), potential.end());

    int current_community = 0;
    int num_nodes_in_community = 1;
    double current_modularity = potential[0];
    best_modularity = current_modularity;

    for (int i = 1; i < graph.size() && num_nodes_in_community < num_communities; ++i) {
        if (community[i] == -1) {
            community[i] = current_community;
            current_modularity += potential[i];
            num_nodes_in_community++;
        } else {
            if (num_nodes_in_community < num_communities) {
                current_community++;
                num_nodes_in_community = 1;
            }
        }
    }

    return community;
}

vector<int> RearrangeNodes(const vector<Node>& graph, int num_communities, double epsilon, int max_passes) {
    int best_modularity = 0;
    int passes = 0;

    while (passes < max_passes && best_modularity < epsilon) {
        auto new_community = FindBestCommunity(graph, num_communities, best_modularity);
        swap(graph[new_community[0]].neighbors, graph[new_community.back()].neighbors);
        graph[new_community[0]].id = new_community.back().id;
        graph[new_community.back()].id = new_community[0].id;
        swap(new_community[0], new_community.back());

        best_modularity = Modularity(graph, num_communities);
        passes++;
    }

    return graph;
}
