#include <iostream>
#include <filesystem>
#include <vector>
#include <numeric>
#include <optional>
#include <stdexcept>

namespace fs = std::filesystem;

using DescriptorMatrix = std::vector<std::vector<uint8_t>>;

DescriptorMatrix loadDescriptors(const std::vector<fs::path>& filePaths, bool includeAlpha) {
    size_t numFiles = filePaths.size();
    size_t descriptorSize = includeAlpha ? 3 : 1;
    DescriptorMatrix descriptors(numFiles, std::vector<uint8_t>(descriptorSize));

    for (size_t i = 0; i < numFiles; ++i) {
        fs::path filePath = filePaths[i];
        std::ifstream file(filePath, std::ios::binary);

        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file: " + filePath.string());
        }

        descriptors[i].resize(descriptorSize);

        if (includeAlpha) {
            file.read(reinterpret_cast<char*>(&descriptors[i][0]), descriptorSize * sizeof(uint8_t));
            if (file.gcount() != descriptorSize * sizeof(uint8_t)) {
                throw std::runtime_error("Invalid descriptor size in file: " + filePath.string());
            }
        } else {
            size_t numDescriptors;
            file.read(reinterpret_cast<char*>(&numDescriptors), sizeof(size_t));
            if (file.gcount() != sizeof(size_t)) {
                throw std::runtime_error("Failed to read number of descriptors from file: " + filePath.string());
            }

            if (numDescriptors > static_cast<size_t>(std::numeric_limits<uint8_t>::max())) {
                throw std::runtime_error("Descriptor count exceeds the maximum representable value by a single byte.");
            }

            size_t bytesRead = 0;
            for (size_t j = 0; j < numDescriptors; ++j) {
                file.read(reinterpret_cast<char*>(&descriptors[i][j]), sizeof(uint8_t));
                bytesRead += sizeof(uint8_t);
            }

            if (bytesRead != numDescriptors * sizeof(uint8_t)) {
                throw std::runtime_error("Failed to read all descriptors from file: " + filePath.string());
            }
        }

        file.close();
    }

    return descriptors;
}
