        new flann::Matrix<uint8_t>(new uint8_t[total_descriptors * dimensions],
                                   total_descriptors, dimensions);
    datasets.push_back(data);
    LOG(INFO) << "Loading data for category " << categories[i] << ".";
    int data_index = 0;
    for (size_t j = 0; j < train_list.size(); ++j) {
