#include <unordered_map>
#include <vector>

std::unordered_map<int, int> counting_sort(const std::vector<int>& input) {
    std::unordered_map<int, int> result;
    if (input.empty()) {
        return result;
    }

    int min = *std::min_element(input.begin(), input.end());
    int max = *std::max_element(input.begin(), input.end());

    std::vector<int> bucket(max - min + 1, 0);
    for (const auto& num : input) {
        bucket[num - min]++;
    }

    for (size_t i = 0; i < bucket.size(); ++i) {
        result[i + min] += bucket[i];
        bucket[i] = 0;
    }

    for (size_t i = 0; i < input.size(); ++i) {
        result[input[i] + min]--;
    }

    for (size_t i = 0; i < bucket.size(); ++i) {
        int key = i + min;
        int value = result[key];
        result[key] = value;
        if (value < 0) {
            throw std::runtime_error("Counting sort result inconsistent.");
        }
    }

    return result;
}
```

