#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#define MAX_NODES 1000
#define MAX_EDGE_LENGTH 50

typedef struct {
    bool visited;
    int degree;
    int component;
} Node;

int build_graph(char **edges, int num_edges, Node graph[MAX_NODES]) {
    int num_components = 0;
    for (int i = 0; i < MAX_NODES; i++) {
        graph[i].visited = false;
        graph[i].degree = 0;
        graph[i].component = i;
    }

    for (int i = 0; i < num_edges; i++) {
        char edge[MAX_EDGE_LENGTH][3]; // Assumes edge format: "x y"
        sscanf(edges[i], " %s %s", edge[0], edge[1]);
        int x = atoi(edge[0]);
        int y = atoi(edge[1]);

        if (x >= MAX_NODES || y >= MAX_NODES) {
            fprintf(stderr, "Invalid node index: %d or %d\n", x, y);
            return -1;
        }

        if (!graph[x].visited) {
            graph[x].visited = true;
            graph[x].degree++;
            union_components(&graph[x], &graph[y]);
            num_components++;
        }

        if (!graph[y].visited) {
            graph[y].visited = true;
            graph[y].degree++;
            union_components(&graph[y], &graph[x]);
            num_components++;
        }
    }

    return num_components;
}

void union_components(Node *node1, Node *node2) {
    if (node1->component != node2->component) {
        node1->component = node2->component;
    }
}
