#include <iostream>
#include <lcb/lcb.h>
#include <lcb/lcb_json.h>
#include <lcb/lcb_error.h>
#include <cstring>

int main(int argc, char* argv[]) {
    if (argc < 6) {
        std::cerr << "Usage: " << argv[0] << " <server_address> <username> <password> <bucket_name> <query_string>\n";
        return 1;
    }

    const std::string server_address(argv[1]);
    const std::string username(argv[2]);
    const std::string password(argv[3]);
    const std::string bucket_name(argv[4]);
    const std::string query_string(argc > 5 ? argv[5] : "SELECT * FROM default");

    lcb_t* cluster = lcb_create(NULL);
    lcb_errcode_t rc;

    // Initialize connection
    rc = lcb_cluster_set(cluster, LCB_AUTH_PLAIN, username.c_str(), password.c_str());
    if (rc != LCB_SUCCESS) {
        std::cerr << "Failed to initialize connection: " << lcb_strerror(cluster, rc) << "\n";
        lcb_release(cluster);
        return 1;
    }

    // Connect to the server
    lcb_cluster_t* cluster_info = lcb_cluster_new();
    lcb_cluster_add_node(cluster_info, server_address.c_str(), 8091);
    rc = lcb_cluster_connect(cluster, cluster_info, 1);
    lcb_cluster_free(cluster_info);
    if (rc != LCB_SUCCESS) {
        std::cerr << "Failed to connect to server: " << lcb_strerror(cluster, rc) << "\n";
        lcb_release(cluster);
        return 1;
    }

    // Create a new bucket
    lcb_bucket_t* bucket = lcb_bucket_new(cluster, bucket_name.c_str(), NULL);
    if (!bucket) {
        std::cerr << "Failed to create bucket: " << lcb_strerror(cluster, rc) << "\n";
        lcb_release(cluster);
        return 1;
    }

    // Execute the query
    lcb_query_t* query = lcb_query_new(bucket, query_string.c_str(), LCB_QUERY_TYPE_N1QL);
    lcb_error_t* error = NULL;
    lcb_result_t* result = lcb_query(query, 0, &error);

    if (!result) {
        if (error) {
            std::cerr << "Query failed: " << lcb_strerror(cluster, error->rc) << "\n";
            lcb_error_free(error);
        } else {
            std::cerr << "Query failed: Unknown error\n";
        }
        lcb_query_free(query);
        lcb_release(bucket);
        lcb_release(cluster);
        return 1;
    }

    // Print the results
    int num_rows = lcb_result_num_entries(result);
    for (int i = 0; i < num_rows; ++i) {
        lcb_json_t* json = lcb_result_entry_get_json(result, i);
        if (json) {
            std::cout << lcb_json_tostring(json, 0) << "\n";
            lcb_json_free(json);
        }
    }

    // Clean up
    lcb_result_free(result);
    lcb_query_free(query);
    lcb_bucket_free(bucket);
    lcb_release(cluster);

    return 0;
}
