        check("schedule get", lcb_get(instance, nullptr, gcmd));
        lcb_cmdget_destroy(gcmd);
        lcb_wait(instance, LCB_WAIT_DEFAULT);

        // Now, a query
        lcb_cmdquery_create(&qcmd);
