        check("schedule query", lcb_query(instance, nullptr, qcmd));
        lcb_cmdquery_destroy(qcmd);
        lcb_wait(instance, LCB_WAIT_DEFAULT);
    }

    lcb_destroy(instance);
    controller.stop();
    return 0;
