#include <cstdint>  // for int types
#include <limits>    // for std::numeric_limits
#include <random>    // for random number generation

constexpr int grid_width = 10;
constexpr int grid_height = 10;

struct Coord { int x, y; };

std::random_device rd; // system-wide random number generator
std::mt19937 gen(rd()); // Mersenne Twister pseudo-random number engine
std::uniform_int_distribution<> dis(0, std::numeric_limits<int>::max());

Coord toroidal_wrap(const Coord& coord) {
  int new_x = coord.x;
  int new_y = coord.y;

  if (new_x < 0) new_x += grid_width;
  if (new_x >= grid_width) new_x -= grid_width;

  if (new_y < 0) new_y += grid_height;
  if (new_y >= grid_height) new_y -= grid_height;

  return { new_x, new_y };
}

unsigned int get_cell_id(const Coord& coord) {
  // Toroidal coordinate wrapping
  Coord wrapped_coord = toroidal_wrap(coord);

  // Validate input
  if (wrapped_coord.x < 0 || wrapped_coord.x >= grid_width ||
      wrapped_coord.y < 0 || wrapped_coord.y >= grid_height) {
    // Out-of-bounds coordinates, return an error identifier
    return std::numeric_limits<unsigned int>::max();
  }

  // Generate a random identifier for the cell
  unsigned int id = dis(gen);

  return id;
}
