#include <vector>
#include <string>
#include <cstring>
#include <cstdlib>
#include <stdexcept>

std::vector<std::string> extractTokens(const char* buffer, size_t bufferSize, const char* delimiter, const char specialValue) {
    if (buffer == nullptr || delimiter == nullptr) {
        throw std::invalid_argument("Invalid input parameters.");
    }

    size_t currentPosition = 0;
    size_t tokenStartPosition = 0;
    size_t tokenLength = 0;
    std::vector<std::string> tokens;

    while (currentPosition < bufferSize) {
        if (buffer[currentPosition] == specialValue) {
            currentPosition++;
            continue;
        }

        if (tokenStartPosition == currentPosition) {
            tokenStartPosition = currentPosition;
        }

        while (buffer[currentPosition] != specialValue && currentPosition < bufferSize) {
            tokenLength++;
            currentPosition++;
        }

        if (currentPosition >= bufferSize) {
            tokens.push_back(std::string(buffer + tokenStartPosition, tokenLength));
            break;
        }

        if (buffer[currentPosition] == *delimiter) {
            tokens.push_back(std::string(buffer + tokenStartPosition, tokenLength));
            tokenStartPosition = currentPosition + 1;
            tokenLength = 0;
        }
    }

    if (tokenStartPosition < bufferSize) {
        tokens.push_back(std::string(buffer + tokenStartPosition, bufferSize - tokenStartPosition));
    }

    return tokens;
}
