#define MAX_FILENAME_LENGTH 256
#define MAX_STRING_LENGTH 1024

int create_and_write_file(const char *dir_path, const char *filename, const char *string) {
    char full_path[MAX_FILENAME_LENGTH];
    FILE *file;
    size_t string_len = strlen(string);
    int ret = 0;

    // Validate filename and directory path
    if (strnlen(filename, MAX_FILENAME_LENGTH) > MAX_FILENAME_LENGTH - 1 ||
        strnlen(dir_path, MAX_FILENAME_LENGTH) > MAX_FILENAME_LENGTH - 1) {
        errno = ENAMETOOLONG;
        perror("Filename or directory path too long");
        return -1;
    }

    snprintf(full_path, MAX_FILENAME_LENGTH, "%s/%s", dir_path, filename);

    // Open the file for writing with a context manager
    file = fopen(full_path, "w");
    if (file == NULL) {
        errno = errno;
        perror("Failed to open file for writing");
        return -1;
    }

    // Set the file size to the specified value
    if (fseek(file, string_len - 1, SEEK_SET) != 0) {
        errno = errno;
        perror("Failed to set file size");
        fclose(file);
        return -1;
    }
    if (fwrite(&string_len, sizeof(size_t), 1, file) != 1) {
        errno = errno;
        perror("Failed to write file size");
        fclose(file);
        return -1;
    }

    // Write the string to the file
    if (fwrite(string, 1, string_len, file) != string_len) {
        errno = errno;
        perror("Failed to write string to file");
        fclose(file);
        return -1;
    }

    // Close the file with a context manager
    fclose(file);

    return 0;
}
