#include <system_error>
#include <cstdint>
#include <vector>

struct HeightMap {
    uint32_t width;
    uint32_t height;
    std::vector<int32_t> data;
};

HeightMap read_bitmap_file(const std::string& file_path) {
    std::ifstream file(file_path, std::ios::binary);
    if (!file.is_open()) {
        throw std::system_error(errno, "Failed to open file: " + file_path);
    }

    // Check for valid bitmap file signature
    char signature[2] = {'B', 'M'};
    char file_signature[2];
    file.read(file_signature, sizeof(file_signature));
    if (file_signature[0] != signature[0] || file_signature[1] != signature[1]) {
        file.close();
        throw std::runtime_error("Invalid bitmap file signature");
    }

    // Read DIB header
    uint32_t dib_size;
    file.read(reinterpret_cast<char*>(&dib_size), sizeof(dib_size));
    BITMAPINFO header;
    file.read(reinterpret_cast<char*>(&header), sizeof(header));

    // Validate DIB header
    if (dib_size < sizeof(BITMAPINFO) + header.biSizeImage) {
        file.close();
        throw std::runtime_error("Invalid DIB header size");
    }

    // Allocate memory for height map
    HeightMap height_map;
    height_map.width = header.biWidth;
    height_map.height = header.biHeight;
    height_map.data.resize(height_map.width * height_map.height);

    // Read bitmap data
    uint8_t r, g, b;
    for (size_t y = 0; y < height_map.height; ++y) {
        for (size_t x = 0; x < height_map.width; ++x) {
            file.read(reinterpret_cast<char*>(&b), sizeof(b));
            file.read(reinterpret_cast<char*>(&g), sizeof(g));
            file.read(reinterpret_cast<char*>(&r), sizeof(r));

            height_map.data[y * height_map.width + x] = static_cast<int32_t>(r);
        }
    }

    file.close();

    return height_map;
}
