enum class ShaderType { Vertex, Fragment };

struct ShaderCompileError : std::runtime_error {
  ShaderCompileError(const std::string& message) : std::runtime_error(message) {}
};

GLuint CreateShaderObject(GLenum type, const std::string& source) {
  GLuint shader = glCreateShader(type);
  if (shader == GL_INVALID_VALUE) {
    throw std::runtime_error("Failed to create shader object");
  }

  const GLchar* sources[] = { source.c_str() };
  glShaderSource(shader, 1, sources, nullptr);
  glCompileShader(shader);

  GLint status;
  glGetShaderiv(shader, GL_COMPILE_STATUS, &status);
  if (status == GL_FALSE) {
    GLint infoLogLength;
    glGetShaderiv(shader, GL_INFO_LOG_LENGTH, &infoLogLength);
    if (infoLogLength > 0) {
      std::vector<GLchar> errorLog(infoLogLength);
      glGetShaderInfoLog(shader, infoLogLength, nullptr, &errorLog[0]);
      throw ShaderCompileError(std::string(errorLog.begin(), errorLog.end()));
    }
  }

  return shader;
}

GLuint CreateShader(ShaderType type, const std::string& source) {
  GLuint shader = CreateShaderObject(static_cast<GLenum>(type), source);
  GLuint program = glCreateProgram();
  if (program == GL_INVALID_VALUE) {
    glDeleteShader(shader);
    throw std::runtime_error("Failed to create shader program");
  }

  glAttachShader(program, shader);
  glLinkProgram(program);

  GLint status;
  glGetProgramiv(program, GL_LINK_STATUS, &status);
  if (status == GL_FALSE) {
    GLint infoLogLength;
    glGetProgramiv(program, GL_INFO_LOG_LENGTH, &infoLogLength);
    if (infoLogLength > 0) {
      std::vector<GLchar> errorLog(infoLogLength);
      glGetProgramInfoLog(program, infoLogLength, nullptr, &errorLog[0]);
      throw ShaderCompileError(std::string(errorLog.begin(), errorLog.end()));
    }
  }

  glDetachShader(program, shader);
  glDeleteShader(shader);
  return program;
}
