struct DirectoryListing {
    std::vector<fs::path> files;
    std::vector<fs::path> directories;
};

DirectoryListing get_directory_listing(const fs::path& path, const std::vector<std::string>& allowed_sort_params) {
    DirectoryListing listing;
    try {
        for (const auto& entry : fs::directory_iterator(path)) {
            if (entry.is_regular_file()) {
                listing.files.push_back(entry.path());
            } else if (entry.is_directory()) {
                listing.directories.push_back(entry.path());
            }
        }

        if (!allowed_sort_params.empty()) {
            std::sort(listing.files.begin(), listing.files.end(), [&allowed_sort_params](const auto& a, const auto& b) {
                for (const auto& sort_param : allowed_sort_params) {
                    if (a.filename().string().find(sort_param) == 0) {
                        return true;
                    }
                    if (b.filename().string().find(sort_param) == 0) {
                        return false;
                    }
                }
                return false;
            });
        }
    } catch (const std::exception& e) {
        std::cerr << "Error reading directory: " << e.what() << std::endl;
        throw;
    }
    return listing;
}
