#include <list>

void insertStringAfter(std::forward_list<std::string>& list, const std::string& searchStr, const std::string& insertStr) {
  if (list.empty()) {
    list.push_back(insertStr);
    return;
  }

  auto it = list.begin();
  while (it != list.end() && *it != searchStr) {
    it++;
  }

  if (it == list.end()) {
    list.push_back(insertStr);
  } else {
    it->next()->swap(*list.insert(it, insertStr));
  }
}
```

