#define MAX_FILENAME_LENGTH 256

int save_data_to_file(const char *filename, const char *data) {
    FILE *file;
    size_t len = strlen(data) + 1;
    char intended_path[MAX_FILENAME_LENGTH];
    int ret = 0;

    // Validate filename
    if (filename == NULL || strlen(filename) > MAX_FILENAME_LENGTH - 5) {
        errno = ENAMETOOLONG;
        perror("Invalid filename length");
        return -1;
    }
    strcpy(intended_path, "./");
    strcat(intended_path, filename);
    strcat(intended_path, ".txt");

    // Create file and write data
    file = fopen(intended_path, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return -1;
    }

    if (fwrite(data, len, 1, file) != 1) {
        perror("Failed to write data to file");
        fclose(file);
        return -1;
    }

    // Close file
    fclose(file);

    return 0;
}
