#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>
#include <wchar.h>

#define MAX_BUFFER_SIZE 1024 * 1024 // 1MB

int read_file_to_unicode_string(const char *path, wchar_t **out_str, int *err_rc) {
    int file_descriptor;
    struct stat file_stat;
    size_t read_bytes;
    wchar_t *buffer;

    if (stat(path, &file_stat) < 0) {
        *err_rc = errno;
        return 1;
    }

    if (S_ISDIR(file_stat.st_mode)) {
        *err_rc = ENOTREG;
        return 1;
    }

    if ((file_descriptor = open(path, O_RDONLY)) < 0) {
        *err_rc = errno;
        return 1;
    }

    buffer = (wchar_t *)calloc(MAX_BUFFER_SIZE, sizeof(wchar_t));
    if (!buffer) {
        close(file_descriptor);
        *err_rc = errno;
        return 1;
    }

    read_bytes = 0;
    while (read(file_descriptor, (char *)buffer + read_bytes, MAX_BUFFER_SIZE - read_bytes) > 0) {
        read_bytes += strlen((char *)buffer + read_bytes) * sizeof(wchar_t);
    }

    if (read < 0) {
        free(buffer);
        close(file_descriptor);
        *err_rc = errno;
        return 1;
    }

    if (read_bytes > MAX_BUFFER_SIZE - sizeof(wchar_t)) {
        free(buffer);
        close(file_descriptor);
        *err_rc = ENOMEM;
        return 1;
    }

    wcscat(buffer, L"\0");

    *out_str = buffer;
    *err_rc = 0;

    close(file_descriptor);
    free(buffer);

    return 0;
}
