// Function to find the best combination of values from an array of pairs
// Returns the combination of values that results in the highest total value that is less than or equal to a target value, or -1 if no such combination exists
int64_t find_best_combination(const std::vector<std::pair<int64_t, bool>>& numbers, int64_t target) {
    std::random_device rd; // Seed for random number generator
    std::mt19937 gen(rd()); // Mersenne Twister pseudo-random number generator
    std::uniform_int_distribution<> dis(0, numbers.size() - 1); // Distribution for generating random indices

    int64_t total = 0; // Total value of the selected values
    std::vector<int64_t> selected_numbers; // Vector to store the selected numbers

    while (total < target) {
        size_t index = dis(gen); // Generate a random index
        if (!numbers[index].second) { // Check if the number has not been previously selected
            total += numbers[index].first; // Add the number to the total
            selected_numbers.push_back(numbers[index].first); // Store the number in the vector
            numbers[index].second = true; // Mark the number as selected
        }
    }

    // If the total value exceeds the target, remove the last selected number and decrease the total value
    if (total > target) {
        total -= selected_numbers.back();
        selected_numbers.pop_back();
        numbers[dis(gen)].second = false; // Select a new number
    }

    return total; // Return the total value of the selected numbers
}
