#define SERVER_NAME_REGEX "^[^:]+(:\\d+)?"

typedef struct {
    char *server_name;
    char *password;
} server_info_t;

server_info_t extract_server_info(const char *input) {
    server_info_t result = {NULL, NULL};
    regex_t regex;
    regmatch_t match;
    int reti;

    result.server_name = strdup(input);

    reti = regcomp(&regex, SERVER_NAME_REGEX, REG_EXTENDED);
    if (reti) {
        free(result.server_name);
        regfree(&regex);
        perror("Error compiling regular expression");
        exit(EXIT_FAILURE);
    }

    reti = regexec(&regex, result.server_name, 1, &match, 0);
    if (!reti) {
        size_t server_name_len = match.rm_eo;
        size_t password_len = strlen(result.server_name) - server_name_len;

        result.server_name = malloc(server_name_len + 1);
        strncpy(result.server_name, result.server_name, server_name_len);
        result.server_name[server_name_len] = '\0';

        result.password = malloc(password_len + 1);
        strncpy(result.password, result.server_name + server_name_len + 1, password_len);
        result.password[password_len] = '\0';

        regfree(&regex);
    }

    return result;
}
