typedef struct {
    size_t len;
    char data[1];
} string_t;

static size_t
mb_strlen(const char *str, size_t encoding) {
    size_t len = 0;
    const char *p = str;

    if (encoding == ENCODING_UTF8) {
        while (*p++) len += utf8_next_char_len(p);
    } else {
        while (*p++) len++;
    }

    return len;
}

static int
case_insensitive_match(const char *str1, const char *str2, size_t encoding) {
    string_t *s1 = malloc(mb_strlen(str1, encoding) + 1);
    string_t *s2 = malloc(mb_strlen(str2, encoding) + 1);

    if (!s1 || !s2) {
        free(s1);
        free(s2);
        return 0;
    }

    memset(s1->data, 0, mb_strlen(str1, encoding) + 1);
    memset(s2->data, 0, mb_strlen(str2, encoding) + 1);

    strncpy(s1->data, str1, mb_strlen(str1, encoding));
    strncpy(s2->data, str2, mb_strlen(str2, encoding));

    for (size_t i = 0; s1->data[i]; i++) {
        s1->data[i] = tolower(s1->data[i]);
    }

    for (size_t j = 0; s2->data[j]; j++) {
        if (tolower(s2->data[j]) != s1->data[i]) {
            free(s1->data);
            free(s2->data);
            return 0;
        }
        i++;
    }

    free(s1->data);
    free(s2->data);
    free(s1);
    free(s2);

    return 1;
}

