#include <random> // For std::mt19937 and std::uniform_int_distribution
#include <vector> // For std::vector

void percolation_step(std::vector<int>* sites, double probability, int time_step) {
    std::random_device rd; // Seed generator: will be used once
    std::mt19937 gen(rd()); // Mersenne Twister pseudo-random number engine
    std::uniform_int_distribution<> dis(0, sites->size() - 1); // Uniform int distribution

    int selected_site = dis(gen); // Select a random site
    int site = (*sites)[selected_site]; // Get the site value

    if (site == -1 || time_step % (int)(1 / probability) != 0) {
        // Percolation rule: site is not open
        continue;
    }

    // Percolation rule: site is open
    for (size_t i = 0; i < sites->size(); ++i) {
        if (i == selected_site) continue;

        int neighbor = (*sites)[i];
        if (neighbor == site) {
            (*sites)[i] = site; // Update neighbor site
        }
    }
}
```

