#include <ogr.h>
#include <string.h>
#include <cstdio>

OGRLcontext *g_OGRLContext = nullptr;

OGStrings OGR_FormatGeometry(OGGeometryH hGeometry, const char *format) {
  OGStringList *pList = nullptr;
  OGError *psError = nullptr;
  OGStrings result;

  if (!OGRL_Init()) {
    OG_FatalError("Failed to initialize OGR library.");
  }

  g_OGRLContext = OGR_GetContext();
  pList = OG_TNewList(1, sizeof(OGString), 0);

  if (!pList) {
    OG_FatalError("Failed to allocate memory for OGStringList.");
  }

  psError = OGR_GetLastError();
  if (psError) {
    OG_FreeError(psError);
  }

  if (OG_G_GetLastError() != OGRERR_NONE) {
    OG_FatalError("Failed to initialize OGR context.");
  }

  result = OG_TNewStringList(1, 0);

  if (!result) {
    OG_Free(pList);
    OG_FatalError("Failed to allocate memory for OGStrings.");
  }

  if (OGG_FPrintf(g_OGRLContext, pList, format, hGeometry) < 0) {
    OG_Free(result);
    OG_Free(pList);
    OG_FatalError("Failed to format geometry.");
  }

  OG_Free(pList);
  return result;
}

OGStrings FormatGeometry(OGGeometryH hGeometry, const char *format) {
  OGStrings result;

  if (!hGeometry) {
    result = OGR_FormatGeometry(nullptr, format);
    result->paOS[0] = "Invalid geometry.";
    return result;
  }

  result = OGR_FormatGeometry(hGeometry, format);
  return result;
}

OGStrings FormatGeometry(const OGGeometry *geometry, const char *format) {
  OGGeometryH hGeometry = OGR_GCreateGeometryFromWkb(geometry->wkb, geometry->wkbSize, 0, nullptr, nullptr);
  OGStrings result;

  if (!hGeometry) {
    result = OGR_FormatGeometry(nullptr, format);
    result->paOS[0] = "Failed to create geometry handle.";
    OG_GReleaseGeometry(hGeometry);
    return result;
  }

  result = FormatGeometry(hGeometry, format);
  OG_GReleaseGeometry(hGeometry);
  return result;
}
