#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <string.h>

#define MAX_CMD_LEN 1024

static int
run_command_in_background(const char *cmd) {
    pid_t child_pid;
    int status;

    if (!cmd || strlen(cmd) > MAX_CMD_LEN) {
        return 1; // Invalid command
    }

    if ((child_pid = fork()) < 0) {
        perror("fork failed");
        return 1;
    }

    if (child_pid == 0) {
        setsid(); // Create a new session and orphaned process group
        if (execvp(cmd, (char *const *) &cmd, NULL) < 0) {
            perror("execvp failed");
            exit(1);
        }
    }

    if (waitpid(child_pid, &status, WNOHANG) <= 0) {
        perror("waitpid failed");
        return 1;
    }

    if (WIFEXITED(status)) {
        return WEXITSTATUS(status) == 0; // Command executed successfully
    }

    return 0; // Command execution failed
}
