#include <type_traits>
#include <utility>

template <typename Container, typename Function, typename Enable = void>
struct ForeachIterator {
  Container& container;
  Function function;
  bool continue_next = true;

  ForeachIterator(Container& c, Function f) : container(c), function(f) {}

  void operator()(std::pair<typename Container::iterator, typename Container::iterator> range) {
    for (auto it = range.first; it != range.second && continue_next; ++it) {
      if (!this->container.empty()) {
        this->function(*it);
      } else {
        break;
      }
    }
  }

  void break_loop() {
    this->continue_next = false;
  }

  void continue_next_iteration() {
    this->continue_next = true;
  }
};

template <typename Container, typename Function>
ForeachIterator<Container, Function> foreach(Container& container, Function function) {
  return ForeachIterator<Container, Function>(container, function);
}
