int read_buffered_audio_frames(uint32_t* buffer, size_t buffer_size, int nb_frames, double sample_rate, int& audio_delay) {
    size_t frames_read = 0;
    int current_frame_size = 0;

    audio_delay = 0; // reset audio delay

    while (frames_read < nb_frames && buffer_size > 0) {
        if (avio_feof((AVIOContext*)nullptr)) { // check if end of file is reached
