            tor_free(tor);
        }
        if (fd != -1) {
            close(fd);
        }
    }

    TorHandler(const TorHandler &) = delete;
    TorHandler &operator=(const TorHandler &) = delete;

    TorHandler(const std::string &private_key_path) {
        tor = tor_init(".", "TorHiddenService", NULL);
        if (tor == nullptr) {
            throw std::runtime_error("Failed to initialize Tor.");
        }

        fd = tor_ctrl_socket(tor);
        if (fd < 0) {
            tor_free(tor);
            throw std::runtime_error("Failed to create Tor control socket.");
        }

        std::string cmd = "ADD_ONION " + TorConfig().HiddenServicePort(0).str() + " " + private_key_path + " \n";
        int ret = tor_write(fd, cmd.c_str(), cmd.size());
        if (ret < 0) {
            close(fd);
            tor_free(tor);
            throw std::runtime_error("Failed to add onion service.");
        }

        std::string response;
        ret = tor_read(fd, &response, sizeof(response));
        if (ret < 0) {
            close(fd);
            tor_free(tor);
            throw std::runtime_error("Failed to read onion address.");
        }

        std::string onion_address = TorAddressParser().parse(response).Address();
        if (onion_address.empty()) {
            close(fd);
            tor_free(tor);
            throw std::runtime_error("Failed to parse onion address.");
        }

        std::cout << "New onion address: " << onion_address << std::endl;

        if (TorConfig().HiddenServiceBindOnion()) {
            std::string proxy_cmd = "SETPROXY " + TorConfig().HiddenServiceProxyHost() + ":" + TorConfig().HiddenServiceProxyPort() + " \n";
            ret = tor_write(fd, proxy_cmd.c_str(), proxy_cmd.size());
            if (ret < 0) {
                close(fd);
                tor_free(tor);
                throw std::runtime_error("Failed to set proxy for onion addresses.");
            }
        }

        this->conn = new HiddenServiceConnection(onion_address);
    }

