#include <iostream>
#include <fstream>
#include <vector>
#include <stdexcept>

const int BUF_SIZE = 1024;

void linearRegression(const std::vector<float>& x, const std::vector<float>& y, float& m, float& b) {
    int n = x.size();
    float sum_x = 0, sum_y = 0, sum_xy = 0, sum_xx = 0;

    for (int i = 0; i < n; ++i) {
        sum_x += x[i];
        sum_y += y[i];
        sum_xy += x[i] * y[i];
        sum_xx += x[i] * x[i];
    }

    m = sum_xy / sum_xx;
    b = (sum_y - m * sum_x) / n;
}

int main() {
    std::string filename;
    std::ifstream inputFile;
    std::vector<float> x, y;

    std::cout << "Enter the file name: ";
    std::cin >> filename;

    inputFile.open(filename.c_str());

    if (!inputFile.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 1;
    }

    std::string line;
    int count = 0;

    while (std::getline(inputFile, line)) {
        std::istringstream ss(line);
        float x_val, y_val;

        if (!(ss >> x_val >> y_val)) {
            std::cerr << "Invalid data point: " << line << std::endl;
            inputFile.clear();
            inputFile.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            break;
        }

        x.push_back(x_val);
        y.push_back(y_val);
        count++;
    }

    if (count == 0) {
        std::cerr << "No valid data points found in the file." << std::endl;
        inputFile.close();
        return 1;
    }

    inputFile.close();

    float m, b;
    linearRegression(x, y, m, b);

    std::cout << "Number of data points: " << count << std::endl;
    std::cout << "Linear Regression Results:" << std::endl;
    std::cout << "m = " << m << std::endl;
    std::cout << "b = " << b << std::endl;

    return 0;
}
