// Test allocator class
class TestAllocator {
public:
    size_t* m_allocations;
    size_t m_current_allocation;

    TestAllocator(size_t num_allocations) : m_allocations(new size_t[num_allocations]) { m_current_allocation = 0; }

    void* operator new(size_t size) {
        m_allocations[m_current_allocation] = size;
        m_current_allocation++;
        return malloc(size);
    }

    void operator delete(void* ptr) { free(ptr); }

    ~TestAllocator() { delete[] m_allocations; }
};

// Function to initialize test allocator and print memory information
void print_allocated_memory(int verbosity) {
    TestAllocator allocator(10); // Allocate 10 memory blocks

    std::vector<std::string> strings;

    for (size_t i = 0; i < 5; i++) {
        size_t length = 1 + rand() % 10; // Generate random length between 1 and 10
