void json_double_to_string(json_object *json_obj, char *printbuf, size_t printbuf_len) {
    json_value *value;
    double num;
    int len;

    value = json_obj_get(json_obj, "value");

    if (value->type != JSON_TYPE_DOUBLE) {
        snprintf(printbuf, printbuf_len, "Invalid JSON object. Expected a double value.");
        return;
    }

    num = value->u.d;

    // Handle special cases
    if (isnan(num)) {
        snprintf(printbuf, printbuf_len, "NaN");
        return;
    }

    if (isinf(num, 0.0)) {
        if (num > 0.0) {
            snprintf(printbuf, printbuf_len, "%sInfinity", num < 0.0 ? "Negative " : "");
        } else {
            snprintf(printbuf, printbuf_len, "-Infinity");
        }
        return;
    }

    len = snprintf(printbuf, printbuf_len, "%.15Lf", num);

    if (len < 0) {
        snprintf(printbuf, printbuf_len, "Error formatting double value.");
        return;
    }

    if (len >= printbuf_len) {
        snprintf(printbuf, printbuf_len, "Buffer too small to format double value.");
        return;
    }

    // Trim trailing zeroes and decimal point
    while (len > 0 && (printbuf[len - 1] == '0' || printbuf[len - 1] == '.')) {
        printbuf[len - 1] = '\0';
        len--;
    }
}
