#include <string.h>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <stdexcept>

class AnsiString {
private:
    size_t length;
    char* data;

public:
    AnsiString() : length(0), data(nullptr) {}

    AnsiString(const std::u16string& unicode) {
        length = wcslen(unicode.c_str()) * 2 + 1;
        data = new char[length];
        wcstombs(data, unicode.c_str(), length);
    }

    ~AnsiString() {
        delete[] data;
    }

    AnsiString(const AnsiString& other) : length(other.length), data(new char[length]) {
        std::memcpy(data, other.data, length);
    }

    AnsiString& operator=(const AnsiString& other) {
        if (this != &other) {
            delete[] data;
            length = other.length;
            data = new char[length];
            std::memcpy(data, other.data, length);
        }
        return *this;
    }

    AnsiString operator+(const AnsiString& other) const {
        size_t new_length = length + other.length;
        char* new_data = new char[new_length + 1];
        std::memcpy(new_data, data, length);
        std::memcpy(new_data + length, other.data, other.length);
        new_data[new_length] = '\0';
        AnsiString result(new_data);
        delete[] new_data;
        return result;
    }

    bool operator==(const AnsiString& other) const {
        return (length == other.length && std::memcmp(data, other.data, length) == 0);
    }

    size_t size() const {
        return length;
    }

    char operator[](size_t index) const {
        if (index >= length) {
            throw std::out_of_range("Index out of range");
        }
        return data[index];
    }
};
