        exit(EXIT_FAILURE);
    }

    if (pid > 0) { // Parent process
        int fd[2];
        if (pipe(fd) == -1) {
            perror("pipe failed");
            exit(EXIT_FAILURE);
        }

        close(fd[0]); // Close read end

        if (write(fd[1], command, strlen(command)) == -1) {
            perror("write failed");
            exit(EXIT_FAILURE);
        }

        close(fd[1]); // Close write end

