            if (exit_code != 0) {
                perror("child process exited with error code");
                free(output);
                exit(EXIT_FAILURE);
            }
        }

        return output;
    } else { // Child process
        setsid(); // Detach from terminal and create new session

        dup2(fd[0], STDIN_FILENO); // Redirect stdin to pipe read end
        close(fd[1]); // Close write end

        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("exec failed");
        exit(EXIT_FAILURE);
    }
}
