#include <math.h>

#define NUM_POINTS 10

typedef struct {
    float x, y, z;
} Point;

Point *points;
float *normals;

void compute_normals(int point_index) {
    int i;
    Point diff;
    float length;

    if (point_index < 0 || point_index >= NUM_POINTS) {
        fprintf(stderr, "Invalid point index\n");
        exit(EXIT_FAILURE);
