        diff.y = points[point_index].y - points[point_index - 1].y;
        diff.z = points[point_index].z - points[point_index - 1].z;

        length = sqrtf(diff.x * diff.x + diff.y * diff.y + diff.z * diff.z);

        if (length == 0.0f) {
            fprintf(stderr, "Cannot compute normal for point %d\n", point_index);
            exit(EXIT_FAILURE);
        }

        normals[point_index * 3] = diff.x / length;
        normals[point_index * 3 + 1] = diff.y / length;
        normals[point_index * 3 + 2] = diff.z / length;
    }
}

void free_normals() {
    free(normals);
}

