{
  char temp_name[L_tmpnam];
  char *temp_path;
  int fd;

  itime_t current_time;
  struct tm *local_time;

  time (&current_time);
  local_time = localtime (&current_time);

  strftime (temp_name, sizeof(temp_name), "temp_%Y%m%d%H%M%S_%s.tmp", local_time);

