#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <limits.h>

#define TRIE_SIZE 256

typedef struct trie_node {
    int count;
    struct trie_node *children[TRIE_SIZE];
} trie_node;

void init_trie(trie_node *trie) {
    memset(trie, 0, sizeof(trie_node));
}

trie_node *create_node() {
    trie_node *node = malloc(sizeof(trie_node));
    init_trie(node);
    return node;
}

void insert_char(trie_node *root, char c) {
    int index = c;
    if (!root->children[index]) {
        root->children[index] = create_node();
    }
    if (root->children[index]->count > 0) {
        root->children[index]->count++;
    }
    if (isalpha(c) || isdigit(c) || c == '_') {
        insert_char(root->children[index], c);
    }
}

void traverse_trie(const char *str, int *counts, trie_node *root, int depth) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        int index = str[i];
        if (root->children[index]) {
            if (depth + 1 < len) {
                traverse_trie(str + i + 1, counts, root->children[index], depth + 1);
            } else {
                counts[index] += root->children[index]->count;
            }
        }
    }
}

int *count_chars(const char *str, int *len) {
    int *counts = calloc(TRIE_SIZE, sizeof(int));
    if (!counts) {
        perror("Calloc failed");
        exit(EXIT_FAILURE);
    }

    trie_node root;
    init_trie(&root);
    insert_char(&root, '\0');
    for (size_t i = 0; i < strlen(str); i++) {
        insert_char(&root, str[i]);
    }

    int depth = 0;
    traverse_trie(str, counts, &root, depth);

    *len = TRIE_SIZE;
    return counts;
}
