int remove_file(const char *path) {
    char normalized_path[1024];
    ssize_t normalized_path_len;
    int dir_fd;

    memset(normalized_path, 0, sizeof(normalized_path));

    // Normalize the path and ensure it does not contain traversal sequences or symbolic links
    normalized_path_len = realpath(path, normalized_path);
    if (normalized_path_len == -1) {
