    // Remove the file using unlinkat with the directory file descriptor
    if (unlinkat(dir_fd, basename(normalized_path), 0) == -1) {
        perror_msg_and_die("Error removing file: %s", basename(normalized_path));
        close(dir_fd);
        return -1;
