typedef struct {
    int value;
    bool unique;
} entry_t;

int reduce_list(int *input, int num_entries, int *output, int *num_unique) {
    if (num_entries <= 0) {
        *num_unique = 0;
        return 0;
    }

    entry_t *entries = calloc(num_entries, sizeof(entry_t));
    if (entries == NULL) {
        perror("calloc failed");
        return -1;
    }

    int unique_index = 0;
    for (int i = 0; i < num_entries; ++i) {
        bool found = false;
        for (int j = 0; j < unique_index; ++j) {
            if (entries[j].value == input[i]) {
                found = true;
                break;
            }
        }

        if (!found) {
            entries[unique_index].value = input[i];
            entries[unique_index].unique = true;
            unique_index++;
        }
    }

    *num_unique = unique_index;

    // Allocate memory for the output array
    *output = malloc(unique_index * sizeof(int));
    if (*output == NULL) {
        perror("malloc failed");
        free(entries);
        return -1;
    }

    // Copy unique entries to the output array
    for (int i = 0; i < unique_index; ++i) {
        (*output)[i] = entries[i].value;
    }

    free(entries);

    // Sort the output array
    qsort(*output, unique_index, sizeof(int), int_compare);

    return unique_index;
}

int int_compare(const void *a, const void *b) {
    return (*(int *)a) - (*(int *)b);
}
