#include <windows.h>

#define MAX_FILENAME_LENGTH 256

bool is_valid_filename(const char *filename) {
    bool valid = true;
    // Check for invalid characters and length
    for (size_t i = 0; i < strlen(filename); i++) {
        char c = filename[i];
        if ((c >= 0 && c <= 31) || (c == ':' || c == '*' || c == '?' || c == '.' || c == '/')) {
            valid = false;
            break;
        }
    }
    if (strlen(filename) >= MAX_FILENAME_LENGTH) {
        valid = false;
    }
    return valid;
}

char *get_new_filename(const char *old_filename) {
    char new_filename[MAX_FILENAME_LENGTH];
    char input[MAX_FILENAME_LENGTH];
    int result;

    ZeroMemory(new_filename, MAX_FILENAME_LENGTH);
    ZeroMemory(input, MAX_FILENAME_LENGTH);

    // Ask user for new filename
    result = MessageBox(0, "Enter a new filename:", "Rename File", MB_INPUTBOX | MB_DEFBUTTON2);
    if (result != IDOK) {
        return NULL;
    }

    // Get user input and validate it
    strncpy(input, InputBox(NULL, "New Filename", ""), MAX_FILENAME_LENGTH);
    if (!is_valid_filename(input)) {
        MessageBox(0, "Invalid filename. Please try again.", "Error", MB_OK);
        return get_new_filename(old_filename);
    }

    // Construct new filename
    strncpy(new_filename, input, MAX_FILENAME_LENGTH);
    strcat(new_filename, ".txt"); // Assuming the file is a .txt file

    return strdup(new_filename);
}

int rename_file(const char *old_filename) {
    char *new_filename = get_new_filename(old_filename);
    int result;

    if (!new_filename) {
        return -1;
    }

    result = MoveFileA(old_filename, new_filename);

    free(new_filename);

    if (result != 0) {
        return 1;
    } else {
        int error = GetLastError();
        if (error == ERROR_FILE_EXISTS) {
            MessageBox(0, "A file with that name already exists. Please try again.", "Error", MB_OK);
            return rename_file(old_filename);
        } else {
            MessageBox(0, "Failed to rename file.", "Error", MB_OK);
            return -1;
        }
    }
}
