public:
    struct Entry {
        size_t row;
        size_t col;
        T value;
    };

    SparseMatrix(size_t rows, size_t cols) : data_(std::vector<Entry>()) {
        data_.resize(rows * cols + 2);
        data_[0].row = data_[0].col = 0;
        data_[0].value = 0;
    }

