#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define WORDS_MAX 10000
#define TOPICS_MAX 10
#define WORD_BITS 32

typedef struct {
    int64_t word;
    int64_t freq;
} word_freq_t;

typedef struct {
    int64_t topic;
    int64_t prob;
} topic_prob_t;

void topic_modeling(const word_freq_t *wp, const int64_t *dp, int64_t *probs, int64_t *sumdp, int64_t *ztot, int num_words, int num_topics) {
    topic_prob_t *probs_matrix = NULL;
    int64_t *row_pointers = NULL;

    // Check for potential integer overflow before performing memory allocation
    if (num_words > INT32_MAX || num_topics > INT32_MAX) {
        fprintf(stderr, "Input dimensions are too large.\n");
        exit(EXIT_FAILURE);
    }

    size_t probs_size = num_words * sizeof(topic_prob_t);
    size_t row_pointers_size = (num_topics + 1) * sizeof(int64_t);

    // Allocate memory for output matrices
    probs_matrix = (topic_prob_t *) calloc(num_words, sizeof(topic_prob_t));
    if (!probs_matrix) {
        perror("Calloc failed for probs_matrix\n");
        exit(EXIT_FAILURE);
    }

    row_pointers = (int64_t *) calloc(num_topics + 1, sizeof(int64_t));
    if (!row_pointers) {
        perror("Calloc failed for row_pointers\n");
        free(probs_matrix);
        exit(EXIT_FAILURE);
    }

    // Initialize output matrices
    memset(probs_matrix, 0, probs_size);
    memset(row_pointers, 0, row_pointers_size);

    // Calculate topic probabilities for each word
    for (int i = 0; i < num_words; ++i) {
        int64_t sum = 0;
        for (int j = 0; j < num_topics; ++j) {
            sum += dp[i * num_topics + j];
            probs_matrix[i].topic = j;
            probs_matrix[i].prob = sum;
        }
        sumdp[i] = sum;
    }

    // Calculate total number of words in each topic
    for (int j = 0; j < num_topics; ++j) {
        ztot[j] = 0;
        for (int i = 0; i < num_words; ++i) {
            if (probs_matrix[i].topic == j) {
                ztot[j] += probs_matrix[i].prob;
            }
        }
    }

    // Set row pointers
    for (int i = 0; i < num_topics; ++i) {
        row_pointers[i] = (int64_t) ((int64_t) probs + i * num_words);
    }
    row_pointers[num_topics] = (int64_t) ((int64_t) probs + num_words * num_topics);

    // Free allocated memory
    free(row_pointers);
}
