#include <cstdint> // for int64_t, size_t
#include <cmath> // for roundf

// Assuming GDImage is a provided library type with getPixelInterpolated function
using GDImage = some_type; // replace with actual type definition

void blitAdditiveWithAntiAliasing(GDImage& dstImage, int dstX, int dstY, const GDImage& srcImage, int srcX, int srcY, const float* alphaValues, int width, int height) {
    int64_t dstOffset = static_cast<int64_t>(dstX) + static_cast<int64_t>(dstY) * static_cast<int64_t>(dstImage.getWidth());
    int64_t srcOffset = static_cast<int64_t>(srcX) + static_cast<int64_t>(srcY) * static_cast<int64_t>(srcImage.getWidth());

    // Validate input parameters
    if ((dstX < 0) || (dstY < 0) || (dstX >= static_cast<int>(dstImage.getWidth())) || (dstY >= static_cast<int>(dstImage.getHeight()))
        || (srcX < 0) || (srcY < 0) || (srcX >= static_cast<int>(srcImage.getWidth())) || (srcY >= static_cast<int>(srcImage.getHeight()))
        || (width <= 0) || (height <= 0) || (alphaValues == nullptr)) {
        return;
    }

    // Perform the blitting with anti-aliasing
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            float alpha = alphaValues[y * width + x];
            if (alpha <= 0.0f) {
                continue;
            }

            int64_t dstPixelOffset = dstOffset + static_cast<int64_t>(x) + static_cast<int64_t>(y) * static_cast<int64_t>(dstImage.getWidth());
            int64_t srcPixelOffset = srcOffset + static_cast<int64_t>(x) + static_cast<int64_t>(y) * static_cast<int64_t>(srcImage.getWidth());

            uint8_t* dstPixel = static_cast<uint8_t*>(dstImage.getPixels()) + static_cast<size_t>(dstPixelOffset);
            const uint8_t* srcPixel = static_cast<const uint8_t*>(srcImage.getPixels()) + static_cast<size_t>(srcPixelOffset);

            // Perform additive blitting
            for (int channel = 0; channel < dstImage.getNumChannels(); ++channel) {
                uint8_t dstValue = dstPixel[channel];
                uint8_t srcValue = srcPixel[channel];
                dstPixel[channel] = std::min(std::max(dstValue + srcValue * alpha, 0u), 255u);
            }

            dstX += roundf(alpha * (srcImage.getWidth() / 2.0f));
            dstY += roundf(alpha * (srcImage.getHeight() / 2.0f));
        }
    }
