using namespace std;

struct DisjointSet {
    int parent, rank;

    DisjointSet(int id) : parent(id), rank(1) {}
};

class DisjointSetUnion {
private:
    vector<DisjointSet> sets;

public:
    DisjointSetUnion(size_t n) {
        sets.resize(n);
        for (int i = 0; i < n; ++i) {
            sets[i] = DisjointSet(i);
        }
    }

    int findSet(int x) {
        if (sets[x].parent != x) {
            sets[x].parent = findSet(sets[x].parent);
        }
        return sets[x].parent;
    }

    void unionSets(int x, int y) {
        int rootX = findSet(x);
        int rootY = findSet(y);

        if (rootX != rootY) {
            if (sets[rootX].rank < sets[rootY].rank) {
                sets[rootX].parent = rootY;
            } else if (sets[rootX].rank > sets[rootY].rank) {
                sets[rootY].parent = rootX;
                sets[rootX].rank++;
            } else {
                sets[rootX].parent = rootY;
                sets[rootY].rank++;
            }
        }
    }
};

