#include "LinearSolverInterface.h" // Assuming you have a defined interface for the linear solver

using namespace std;
using namespace std::chrono;

void safe_divide(double& numerator, double denominator) {
    if (denominator == 0) {
        numerator = 0.00001; // Use a small value instead of zero to avoid division by zero
    } else {
        numerator /= denominator;
    }
}

void scale_matrix(double** matrix, int size, double scale) {
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            matrix[i][j] *= scale;
        }
    }
}

void linear_solve(double** matrix, int size, const vector<double>& b, LinearSolverInterface& solver) {
    if (size <= 0) {
        throw invalid_argument("Matrix size must be positive.");
    }

    // Measure time taken for scaling the matrix
    auto start = high_resolution_clock::now();
    scale_matrix(matrix, size, 1.5); // Assuming scaling factor is 1.5 in this example
    auto end = high_resolution_clock::now();
    auto duration = duration_cast<microseconds>(end - start).count();
    cout << "Scaling matrix took " << duration << " microseconds." << endl;

    // Validate input vectors have the correct size
    if (b.size() != size) {
        throw invalid_argument("Vector size must match matrix size.");
    }

    // Call the linear solver with the scaled matrix and vector
    solver.solve(matrix, size, b.data());
}
