}
}
else
{
if (n_page_mask != 0)
{
m_sparse_page_occupancy[occupancy_vec_index].raw &= ~(1 << occupancy_item_index);

--m_n_pages_with_memory_backing;
}
}
}

anvil_assert(m_n_pages_with_memory_backing <= m_n_total_pages);
result = true;
end:
return result;
}

