#include <algorithm>
#include <map>
#include <vector>

using namespace std;

void get_sorted_output_counts(const map<string, int>& input_stats, const vector<int>& input_counts, vector<pair<string, int>>& output_counts) {
    vector<pair<string, int>> counts;

    transform(input_stats.begin(), input_stats.end(), back_inserter(counts), [](const auto& pair) { return make_pair(pair.first, pair.second); });

    sort(counts.begin(), counts.end(), [](const auto& a, const auto& b) { return a.second > b.second; });

    output_counts.assign(counts.begin(), counts.end());

