        _maxValue = maxValue;
    }

    private byte[] GenerateSecureBytes(int length)
    {
        using (var rng = RNGCryptoServiceProvider.Create())
        {
            var output = new byte[length];
            rng.GenerateBytes(output, 0, length);
            return output;
        }
    }

    private float GenerateSecureRandomFloat()
    {
        var bytes = GenerateSecureBytes(4);
        var buffer = new BinaryReader(new MemoryStream(bytes));
        return BitConverter.Int32BitsToSingle(buffer.ReadInt32(0));
    }

    private int GenerateSecureRandomInt()
    {
        return BitConverter.ToInt32(GenerateSecureBytes(4), 0) % (_maxValue - _minValue + 1) + _minValue;
    }

    public float GenerateRandomFloatInRange(float minValue, float maxValue)
    {
        _minValue = (int)Math.Floor(minValue);
        _maxValue = (int)Math.Ceiling(maxValue);
        return GenerateSecureRandomFloat() * (maxValue - minValue) / (float)Int32.MaxValue + minValue;
    }

    public int GenerateRandomIntInRange(int minValue, int maxValue, bool isExclusive = false)
    {
        _minValue = minValue;
        _maxValue = maxValue;

        if (isExclusive)
            _maxValue--;

        return GenerateSecureRandomInt() % (_maxValue - _minValue + 1) + _minValue;
    }

    public override string ToString()
    {
        return $"SecureRandomNumberGenerator: MinValue={_minValue}, MaxValue={_maxValue}";
    }
}
