                    Reader.ReadToNextSibling();
                }

                while (Reader.IsStartElement())
                {
                    string parameterName = Reader.Name;
                    if (Reader.IsEmptyElement)
                    {
                        Reader.Read();
                        continue;
                    }

                    string parameterValue = string.Empty;
                    using (XmlReader subReader = Reader.ReadSubtree())
                    {
                        if (subReader.IsText)
                        {
                            parameterValue = subReader.Value;
                        }
                        else
                        {
                            Reader.ReadToEnd();
                            throw new FormatException("Invalid parameter format.");
                        }
                    }

                    parameters.Add(new Parameter { Name = parameterName, Value = parameterValue });

                    Reader.ReadToNextSibling();
                }
            }
            else
            {
                throw new XmlException("Invalid XML format.");
            }
        }

        return parameters;
    }
}
