```csharp using System; using System.Collections.Generic; using System.Linq; using System.Security.Cryptography;

public static bool IsListEqual<T>(List<T> originalList, List<T> sortedList, Func<T, T, bool> sorter)
{
    if (originalList == null || sortedList == null || originalList.Count != sortedList.Count)
        return false;

    for (int i = 0; i < originalList.Count; i++)
    {
        if (!sorter(originalList[i], sortedList[i]))
            return false;
    }

    return true;
}

public static List<int> GenerateRandomList(int minSize, int maxSize, RandomNumberGenerator random)
{
    int size = random.Next(minSize, maxSize + 1);
    List<int> list = new List<int>(size);

    for (int i = 0; i < size; i++)
        list.Add(random.Next(int.MinValue, int.MaxValue));

    return list;
}

public static void Shuffle<T>(List<T> list, RandomNumberGenerator random)
{
    int n = list.Count;
    while (n > 1)
    {
        int k = random.Next(n--);
        T temp = list[n];
        list[n] = list[k];
        list[k] = temp;
    }
}

public static void Sort<T>(List<T> list, Func<T, T, bool> sorter)
{
    if (list == null || list.Count <= 1)
        return;

    for (int i = 0; i < list.Count - 1; i++)
    {
        for (int j = i + 1; j < list.Count; j++)
        {
            if (!sorter(list[i], list[j]))
                (list[i], list[j]) = (list[j], list[i]);
        }
    }
}

public static void Main()
{
    RandomNumberGenerator rng = new RNGCryptoServiceProvider();
    List<int> originalList = GenerateRandomList(5, 10, rng);
    List<int> shuffledList = new List<int>(originalList);
    List<int> sortedList = new List<int>(originalList);

    Shuffle(shuffledList, rng);
    Sort(sortedList, (x, y) => x < y);

    if (IsListEqual(originalList, sortedList, (x, y) => x.Equals(y)))
        Console.WriteLine("Test passed!");
    else
        Console.WriteLine("Test failed!");
}
