```csharp using System; using System.Linq; using System.Security.Cryptography;

public static T[,] CreateAndPopulateRandomMatrix<T>(int rows, int columns, int minValue, int maxValue) where T : new()
{
    if (rows <= 0 || columns <= 0)
        throw new ArgumentException("Number of rows and columns must be positive.");

    T[,] matrix = new T[rows, columns];

    if (!typeof(T).IsValueType || typeof(T).IsPrimitive)
        throw new ArgumentException("Element type must be a value type or a primitive type.");

    using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
    {
        byte[] bytes = new byte[rows * columns * sizeof(T)];
        rng.GetBytes(bytes);

        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                int index = i * columns + j;
                T value = BitConverter.IsLittleEndian
                    ? (T)BitConverter.ToObject(bytes, index * sizeof(T))
                    : (T)BitConverter.ToStruct(bytes, index * sizeof(T), false) as T;

                matrix[i, j] = value;
                if (value.GetType() == typeof(T?) && (value == null))
                    continue;

                matrix[i, j] = Convert.ToT(
                    Convert.ToInt64(BitConverter.ToInt64(bytes, index * sizeof(T))) %
                    (long)(maxValue - minValue + 1) + minValue);
            }
        }
    }

    return matrix;
}
