public static string GetXmlDocumentationValue(HttpParameterDescriptor parameter)
{
    if (parameter == null)
    {
        throw new ArgumentNullException(nameof(parameter));
    }

    string xmlDocumentation = string.Empty;

    try
    {
        using (XmlDocument document = new XmlDocument())
        {
            document.Load("Documentation.xml"); // Assuming the XML file is located at "Documentation.xml"

            XPathNavigator navigator = document.CreateNavigator();
            XPathExpression expression = navigator.Compile("/doc:members/doc:member[doc:name='" + parameter.Name + "']/doc:summary/text()");

