```csharp using System;
using System.IO;
using System.Linq;
using System.Security.Permissions;
using System.Text.RegularExpressions;

public static string AddWebsiteToDirectoryAndStart(string directoryPath, string siteName)
{
    // Validate directory path
    if (!Directory.Exists(directoryPath))
    {
        throw new ArgumentException("Invalid directory path.");
    }

    // Validate site name
    string allowedChars = @"^[a-zA-Z0-9._-]+$";
    if (!Regex.IsMatch(siteName, allowedChars))
    {
        throw new ArgumentException("Invalid site name. Site name can only contain alphanumeric characters, underscores, hyphens, and dots.");
    }

    // Check for existence of web.config file
    string webConfigPath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(webConfigPath))
    {
        return null;
    }

    // Create site directory
    string siteDirectoryPath = Path.Combine(directoryPath, siteName);
    Directory.CreateDirectory(siteDirectoryPath);

    // Grant necessary permissions to the site directory
    DirectorySecurity directorySecurity = Directory.GetAccessControl(siteDirectoryPath);
    directorySecurity.AddAccessRule(new FileSystemAccessRule("Everyone", FileSystemRights.ReadAndExecute | FileSystemRights.ReadData | FileSystemRights.WriteData | FileSystemRights.CreateFiles | FileSystemRights.AppendData | FileSystemRights.TakeOwnership | FileSystemRights.ChangePermissions));
    Directory.SetAccessControl(siteDirectoryPath, directorySecurity);

    // Start website using Process class
    ProcessStartInfo processInfo = new ProcessStartInfo();
    processInfo.FileName = "IISExpress.exe";
    processInfo.Arguments = "/site " + siteName + " /path " + directoryPath;
    processInfo.UseShellExecute = false;
    processInfo.RedirectStandardOutput = true;

    using (Process process = new Process())
    {
        process.StartInfo = processInfo;
        process.Start();

        string output = process.StandardOutput.ReadToEnd();

        if (!string.IsNullOrEmpty(output) && output.Contains("IIS Express is listening on"))
        {
            return siteName;
        }
        else
        {
            process.ExitCode = -1;
            process.Dispose();
            throw new Exception("Failed to start website: " + siteName);
        }
    }
}
