```csharp
using System;
using System.Text;
using System.Security.Cryptography;

public static string DecryptTripleDES(string base64EncryptedMessage, byte[] key, byte[] iv)
{
    byte[] decryptedData;

    try
    {
        // Decode Base64-encoded data
        byte[] inputData = Convert.FromBase64String(base64EncryptedMessage);

        // Create a Triple DES algorithm instance
        using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
        {
            // Set the key and IV
            tripleDES.Key = key;
            tripleDES.IV = iv;

            // Create a decrypter to perform the decryption
            ICryptoTransform decryptor = tripleDES.CreateDecryptor();

            // Create the streams for input and output
            using (MemoryStream inputStream = new MemoryStream(inputData))
            using (MemoryStream outputStream = new MemoryStream())
            {
                // Decrypt the data
                using (CryptoStream decryptorStream = new CryptoStream(outputStream, decryptor, CryptoStreamMode.Write))
                {
                    inputStream.CopyTo(decryptorStream);
                }

                // Get the decrypted data
                decryptedData = outputStream.ToArray();
            }
        }

        // Return the decrypted message as a string
        return Encoding.UTF8.GetString(decryptedData);
    }
    catch (Exception ex)
    {
        // Properly handle exceptions
        Console.WriteLine("An error occurred during decryption: {0}", ex.Message);
        return string.Empty;
    }
}
