using System.Data.Cassandra;

public class CassandraBatchInsertFunction
{
    public static void InsertData(Session session, Dictionary<string, byte[]> outgoingPayload, string keyspace, string table, byte[] data)
    {
        if (outgoingPayload == null)
        {
            throw new ArgumentNullException(nameof(outgoingPayload));
        }

        if (data == null)
        {
            throw new ArgumentNullException(nameof(data));
        }

        using (var batch = new BatchStatement())
        {
            batch.Add(new InsertIntoStatement(keyspace, table)
                .Value("data", data));

            foreach (var entry in outgoingPayload)
            {
                string key = entry.Key;
                byte[] value = entry.Value;

                if (value == null)
                {
                    throw new ArgumentNullException(nameof(value), $"Value for key '{key}' is null.");
                }

                batch.Add(new SetStatement(keyspace, table, key)
                    .Value(key, value));
            }

            IEnumerable<ResultMessage> results;
            try
            {
                results = session.Execute(batch);
            }
            catch (Exception ex)
            {
                throw new Exception("Failed to execute batch statement.", ex);
            }

            if (results == null || results.Count() == 0)
            {
                throw new Exception("No results returned from the database.");
            }

            using (var queryResponse = results[0].GetResponse())
            {
                if (queryResponse == null)
                {
                    throw new Exception("Response from the database is null.");
                }

                using (var resultSet = queryResponse.GetResultSet())
                {
                    if (resultSet == null)
                    {
                        throw new Exception("Result set from the database is null.");
                    }

                    if (resultSet.RowCount != outgoingPayload.Count)
                    {
                        throw new Exception($"Unexpected number of rows returned ({resultSet.RowCount}). Expected {outgoingPayload.Count}.");
                    }

                    for (int i = 0; i < resultSet.RowCount; i++)
                    {
                        var row = resultSet.GetRow(i);
                        string key = row.GetName(0);
                        byte[] value = row.GetByteArray(0);

                        if (value == null)
                        {
                            throw new Exception($"Value for key '{key}' is null.");
                        }

                        if (outgoingPayload[key].Length != value.Length)
                        {
                            throw new Exception($"Unexpected length for value of key '{key}'. Expected {outgoingPayload[key].Length}, got {value.Length}.");
                        }

                        if (!ByteArrayCompare(outgoingPayload[key], value))
                        {
                            throw new Exception($"Unexpected value for key '{key}'. Expected {Encoding.UTF8.GetString(outgoingPayload[key])}, got {Encoding.UTF8.GetString(value)}.");
                        }
                    }
                }
            }
        }
    }

    private static bool ByteArrayCompare(byte[] a, byte[] b)
    {
        if (a == null || b == null)
        {
            return false;
        }

        if (a.Length != b.Length)
        {
            return false;
        }

        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] != b[i])
            {
                return false;
            }
        }

        return true;
    }
}
