using System.IO;
using System.Threading;

public static void StartProcessWithMonitor(ProcessStartInfo processInfo, string trackingFolder, int timeout)
{
    if (!Directory.Exists(trackingFolder))
    {
        throw new InvalidOperationException("Tracking folder does not exist.");
    }

    string trackingFile = Path.Combine(trackingFolder, $"{processInfo.FileName}_{Process.GetCurrentProcess().Id}.pid");

    using (var process = new Process())
    {
        process.StartInfo = processInfo;
        process.Start();

        if (process.ExitCode != 0)
        {
            File.Delete(trackingFile);
            throw new InvalidOperationException("Failed to start process.");
        }

        using (var sentinelProcess = new Process())
        {
            sentinelProcess.StartInfo.FileName = "Monitor.exe";
            sentinelProcess.StartInfo.Arguments = $"\"{trackingFolder}\\{Path.GetFileNameWithoutExtension(trackingFile)}\" {timeout}";
            sentinelProcess.StartInfo.UseShellExecute = false;
            sentinelProcess.StartInfo.RedirectStandardOutput = false;
            sentinelProcess.StartInfo.CreateNoWindow = true;
            sentinelProcess.Start();

            process.Exited += (sender, args) =>
            {
                File.Delete(trackingFile);
                sentinelProcess.ExitCode = process.ExitCode;
                sentinelProcess.Exit();
            };

            if (!File.Exists(trackingFile))
            {
                throw new InvalidOperationException("Failed to write process ID to tracking file.");
            }

            using (var cancellationTokenSource = new CancellationTokenSource())
            {
                CancellationToken token = cancellationTokenSource.Token;

                var waitHandle = new ManualResetEvent(false);
                var timer = new Timer(o => waitHandle.Set(), null, TimeSpan.Zero, TimeSpan.FromMilliseconds(timeout));

                sentinelProcess.Exited += (sender, args) =>
                {
                    if (waitHandle.WaitOne(TimeSpan.Zero))
                    {
                        cancellationTokenSource.Cancel();
                    }
                    else
                    {
                        File.Delete(trackingFile);
                        sentinelProcess.ExitCode = 1;
                        sentinelProcess.Exit();
                    }
                };

                timer.Elapsed += (sender, args) =>
                {
                    cancellationTokenSource.Cancel();
                    waitHandle.Set();
                };

                timer.Start();

                cancellationTokenSource.WaitHandle.WaitOne();

                timer.Dispose();
            }
        }
    }
}

