using System.Xml;

public class Device { /* Device class definition */ }

public class Font
{
    public float Size { get; set; }
    public float Width { get; set; }
    public float Height { get; set; }

    public Font(float size, float width, float height)
    {
        Size = size;
        Width = width;
        Height = height;
    }
}

public static Font CreateFontFromXml(Device device, string fontName)
{
    using (var assembly = Assembly.GetExecutingAssembly())
    using (var stream = assembly.GetManifestResourceStream(string.Format("Fonts.{0}.xml", fontName)))
    {
        if (stream == null)
        {
            throw new FileNotFoundException($"Font XML file '{fontName}.xml' not found.");
        }

        using (var xmlDocument = new XmlDocument())
        {
            xmlDocument.Load(stream);

            if (xmlDocument.DocumentElement == null)
            {
                throw new XmlException("Invalid XML format.");
            }

            var sizeElement = xmlDocument.DocumentElement.SelectSingleNode("//size");
            if (sizeElement == null)
            {
                throw new XmlException("Missing 'size' element in XML.");
            }

            float size = float.Parse(sizeElement.InnerText);

            var widthElement = xmlDocument.DocumentElement.SelectSingleNode("//width");
            if (widthElement == null)
            {
                throw new XmlException("Missing 'width' element in XML.");
            }

            float width = float.Parse(widthElement.InnerText);

            var heightElement = xmlDocument.DocumentElement.SelectSingleNode("//height");
            if (heightElement == null)
            {
                throw new XmlException("Missing 'height' element in XML.");
            }

            float height = float.Parse(heightElement.InnerText);

            return new Font(size, width, height);
        }
    }
}
```

