public static string DecryptDes(string encryptedMessage, string key)
{
    if (string.IsNullOrEmpty(encryptedMessage) || string.IsNullOrEmpty(key))
    {
        throw new ArgumentNullException();
    }

    byte[] encryptedData;
    try
    {
        encryptedData = Convert.FromBase64String(encryptedMessage);
    }
    catch (FormatException)
    {
        throw new ArgumentException("Invalid encrypted message format.");
    }

    using (MemoryStream msEncrypt = new MemoryStream())
    using (MemoryStream msDecrypt = new MemoryStream())
    using (ICryptoTransform desEncryptor = DES.Create())
    using (ICryptoTransform desDecryptor = DES.Create())
    {
        msEncrypt.Write(encryptedData, 0, encryptedData.Length);
        msEncrypt.Position = 0;

        desEncryptor.TransformBlock(msEncrypt.ToArray(), 0, msEncrypt.Length, null, 0);

        msDecrypt.SetLength(msEncrypt.Length);
        desDecryptor.Key = ASCIIEncoding.ASCII.GetBytes(key);

        byte[] decryptedData = new byte[msEncrypt.Length];
        int decryptedBytes = 0;

        while (decryptedBytes < msEncrypt.Length)
        {
            int decryptedCount = desDecryptor.TransformBlock(msDecrypt.GetBuffer(), decryptedBytes, msEncrypt.Length - decryptedBytes, decryptedData, 0);
            decryptedBytes += decryptedCount;
        }

        msDecrypt.Position = 0;
        return Encoding.ASCII.GetString(msDecrypt.ToArray(), 0, (int)msDecrypt.Length);
    }
}
