```csharp using System;
using System.Xml.XPath;
using System.IO;

public void AddSearcherToConfig(string configPath, string searcherId, string searcherType)
{
    if (!File.Exists(configPath))
    {
        throw new FileNotFoundException("Configuration file does not exist.");
    }

    XDocument configDoc = XDocument.Load(configPath);

    XElement searchersElement = configDoc.Root.Element("searchers") ?? configDoc.Root.Add(new XElement("searchers"));

    bool searcherExists = searchersElement.Elements("searcher").Any(s => (string)s.Attribute("id") == searcherId);

    if (searcherExists)
    {
        throw new ArgumentException("A searcher with the same ID already exists.");
    }

    XElement newSearcher = new XElement("searcher",
        new XAttribute("id", searcherId),
        new XElement("type", searcherType)
    );

    searchersElement.Add(newSearcher);

    configDoc.Save(configPath);
}
