    XPathNavigator navigator = source.CreateNavigator();
    XPathExpression expr = navigator.Compile(xpathExpression);
    string transformationResult = (string)expr.Evaluate(navigator);

    logger.Debug("transformation resulted in '{0}'", transformationResult);

    return transformationResult;
}
