public class Tank
{
    public bool IsSink;
    public int X;
    public int Y;
    public int OutputId;
    public bool IsConnected;

    public Tank(int x, int y, bool isSink)
    {
        X = x;
        Y = y;
        IsSink = isSink;
        IsConnected = false;
    }
}

public void ConnectTanks(Tank[,] grid)
{
    Random random = new Random();

    // Find all non-sink tanks
    List<Tank> tanks = grid.Cast<Tank>()
        .Where(tank => !tank.IsSink)
        .ToList();

    // Ensure every tank (except sinks) has an output
    while (tanks.Count(tank => !tank.IsConnected) > 1)
    {
        // Randomly select two tanks to connect
        Tank tank1 = tanks[random.Next(tanks.Count)];
        Tank tank2 = tanks[random.Next(tanks.Count)];

        // Connect the tanks and update their states
        if (CanConnect(grid, tank1, tank2))
        {
            tank1.OutputId = tank2.Y * grid.GetLength(0) + tank2.X;
            tank2.OutputId = tank1.Y * grid.GetLength(0) + tank1.X;
            tank1.IsConnected = true;
            tank2.IsConnected = true;
        }
    }

    // The last non-connected tank is the output of the grid
    Tank outputTank = tanks.Last(tank => !tank.IsConnected);

    // Update the state of the output tank
    outputTank.IsConnected = true;
}

private bool CanConnect(Tank[,] grid, Tank tank1, Tank tank2)
{
    // Check if the tanks are neighbors
    if (Math.Abs(tank1.X - tank2.X) == 1 && Math.Abs(tank1.Y - tank2.Y) == 1)
    {
        // Check if the output tank is not already connected to another tank
        if (!grid[tank2.Y, tank2.X].IsConnected)
        {
            return true;
        }
    }

    return false;
}
