import org.hibernate.HibernateException;
import org.hibernate.Session;
import org.hibernate.SessionFactory;
import org.hibernate.query.Query;

public class DatabaseInteraction {
    private SessionFactory sessionFactory;

    public DatabaseInteraction(SessionFactory sessionFactory) {
        this.sessionFactory = sessionFactory;
    }

    public void createFilter(Session session, String filterName, String filterExpression) {
        try {
            session.beginTransaction();
            session.createFilter("YourEntityName", filterExpression).setCacheable(true).setFilterName(filterName);
            session.getTransaction().commit();
        } catch (HibernateException e) {
            if (session.getTransaction().isActive()) {
                session.getTransaction().rollback();
            }
            throw new RuntimeException("Error creating filter", e);
        }
    }

    public Query getNamedQuery(Session session, String queryName) {
        return session.getNamedQuery(queryName);
    }

    public void createSQLQuery(Session session, String sqlQuery, Class<?> resultClass) {
        Query query = session.createSQLQuery(sqlQuery).addEntity(resultClass);
        query.setResultTransformer(Criteria.ALIAS_TO_ENTITY_MAP);
    }

    public void clearSession(Session session) {
        session.clear();
    }

    public <T> T getObjectByID(Class<T> clazz, Serializable id, Session session) {
        try {
            return (T) session.get(clazz, id);
        } catch (HibernateException e) {
            if (session.getTransaction().isActive()) {
                session.getTransaction().rollback();
            }
            throw new RuntimeException("Error retrieving object", e);
        }
    }
}
