public static string GetStartupFilePath(Project project)
{
    string startupFile = null;

    if (project.StartupFile != null)
    {
        startupFile = project.StartupFile;
    }
    else
    {
        Random random = new Random();
        int portNumber = random.Next(1200, 60501); // Inclusive range

        using (TcpListener listener = new TcpListener(IPAddress.Any, portNumber))
        {
            listener.Start();
            if (listener.Server.IsBound)
            {
                string basePath = Environment.GetFolderPath(Environment.SpecialFolder.Projects);
                string startupFileName = $"{project.Name}.exe";
                string startupFileTempPath = Path.Combine(basePath, $"{project.Name}_{portNumber}.tmp.{startupFileName}");

                File.WriteAllBytes(startupFileTempPath, new byte[0]);
                listener.Stop();

                // Check if the generated file is accessible and can be executed
                if (File.Exists(startupFileTempPath) && File.CanRead(startupFileTempPath) && File.CanExecute(startupFileTempPath))
                {
                    startupFile = startupFileTempPath;
                }
                else
                {
