public string DecryptStringWithDES(string input, byte[] key) {
    if (string.IsNullOrEmpty(input) || key == null) {
        throw new ArgumentException("Input string or key cannot be null or empty.");
    }

    using (var aesAlg = Aes.Create()) {
        aesAlg.Key = key;

        byte[] encryptedData;
        try {
            encryptedData = Convert.FromBase64String(input);
        } catch (FormatException) {
            throw new ArgumentException("Input string is not base64 encoded or is not a valid input.");
        }

