```csharp using System; using System.Xml;

public static string GetFirstElementTrimmedValue(XPathNavigator navigator, string tagName)
{
    XPathNodeIterator iterator = navigator.Select(tagName);
    if (iterator == null || iterator.MoveNext() == false)
        return null;

    XmlNode node = iterator.Current;
    if (node == null)
        return null;

    string value = node.Value.Trim();
    return value;
}
