public class CubeSpawner
{
    private const int MaxCubes = 100;
    private static int _cubeCount;
    private static GameObject _cubePrefab;
    private static float _minSpawnDistance = 2f;
    private static float _maxSpawnDistance = 5f;

    static CubeSpawner()
    {
        _cubePrefab = Resources.Load<GameObject>("Cube");
    }

    public static void SpawnCube()
    {
        if (_cubePrefab == null)
        {
            Debug.LogError("Cube prefab not found.");
            return;
        }

        Vector3 spawnPosition;
        do
        {
            spawnPosition = new Vector3(
                RandomNumberGenerator.GetInt32(0, (int)Mathf.Pow(10, 3)) * 0.1f,
                RandomNumberGenerator.GetInt32(0, (int)Mathf.Pow(10, 3)) * 0.1f,
                RandomNumberGenerator.GetInt32(0, (int)Mathf.Pow(10, 3)) * 0.1f);
        } while (Vector3.Distance(spawnPosition, transform.position) < _minSpawnDistance ||
                 Vector3.Distance(spawnPosition, transform.position) > _maxSpawnDistance);

        GameObject newCube = Instantiate(_cubePrefab, spawnPosition, Quaternion.identity);
        _cubeCount++;

        if (_cubeCount >= MaxCubes)
        {
            _cubeCount = 0;
        }
    }

    static class RandomNumberGenerator
    {
        private static readonly RandomNumberGenerator _rng = new RNGCryptoServiceProvider();

        public static int GetInt32(int minValue, int maxValue)
        {
            byte[] bytes = new byte[4];
            _rng.GetBytes(bytes);
            return BitConverter.ToInt32(bytes, 0) % (maxValue - minValue + 1) + minValue;
        }
    }
}
```

