public class PurchaseOrderController : Controller
{
    private readonly StoreContext _context;

    public PurchaseOrderController(StoreContext context)
    {
        _context = context;
    }

    [HttpPost]
    public IActionResult CreatePurchaseOrder([Bind("StoreId,WalletId,TotalAmount")] CreatePurchaseOrderViewModel model)
    {
        if (model.StoreId == default || model.WalletId == null)
        {
            ModelState.AddModelError("InvalidInput", "StoreId and WalletId are required.");
            return BadRequest(ModelState);
        }

        var store = _context.Stores.FirstOrDefault(s => s.Id == model.StoreId);
        if (store == null)
        {
            ModelState.AddModelError("InvalidStore", "Store does not exist.");
            return BadRequest(ModelState);
        }

        _context.PurchaseOrders.Add(new PurchaseOrder
        {
            StoreId = model.StoreId,
            WalletId = model.WalletId,
            TotalAmount = model.TotalAmount,
            CreatedAt = DateTime.UtcNow
        });
        _context.SaveChanges();

        return View("PurchaseOrderCreated", new PurchaseOrderDetailsViewModel
        {
            PurchaseOrder = _context.PurchaseOrders.OrderByDescending(p => p.CreatedAt).Last()
        });
    }
}

