```csharp using System;
using System.Xml.XPath;
using System.IO;
using System.Linq;

public static void UpdateXmlConfigFile(string configPath, string newSectionName, XElement existingSection, XElement newSectionContent)
{
    if (!File.Exists(configPath))
    {
        throw new FileNotFoundException("The configuration file does not exist.");
    }

    XDocument configDoc = XDocument.Load(configPath);
    XElement root = configDoc.Root;

    // Validate the existence of the existing section
    XElement existingSectionXpath = XPathSelectElement(root, "/Configuration/Section[@Name='" + existingSection.Name + "']");
    if (existingSectionXpath == null)
    {
        throw new ArgumentException("The specified existing section does not exist in the configuration file.");
    }

    // Add the new section after the existing section
    XElement newSectionParent = existingSectionXpath.Parent;
    newSectionParent.AddAfterSelf(newSectionContent);

    configDoc.Save(configPath);
}

private static XElement XPathSelectElement(XElement root, string xpath)
{
    return (from el in root.DescendantsAndSelf()
            where el.Name.LocalName == XName.Get("element", "http://www.w3.org/2005/Atom").LocalName &&
                  el.Attribute("Name") != null && el.Attribute("Name").Value == xpath
            select el).FirstOrDefault();
}
```

