public class DatabaseWrapper
{
    private readonly string _connectionString;
    private SqlConnection _connection;

    public DatabaseWrapper(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task OpenAsync()
    {
        if (_connection != null && _connection.State == System.Data.ConnectionState.Open) return;

        _connection = new SqlConnection(_connectionString);
        await _connection.OpenAsync();
    }

    public async Task<byte[]> ExecuteNonQueryAsync(Guid id, byte[] command, SqlTransaction transaction = null)
    {
        using var commandObject = new SqlCommand(new Text(Encoding.UTF8.GetString(command)), _connection, transaction ?? _connection.BeginTransaction());
