    {
        using var commandObject = new SqlCommand(new Text(Encoding.UTF8.GetString(command)), _connection, transaction ?? _connection.BeginTransaction());
        commandObject.CommandType = CommandType.Text;
        return await commandObject.ExecuteScalarAsync();
    }

    public async Task<byte[]> ExecuteQueryAsync(Guid id, byte[] command, SqlTransaction transaction = null)
    {
        using var commandObject = new SqlCommand(new Text(Encoding.UTF8.GetString(command)), _connection, transaction ?? _connection.BeginTransaction());
        commandObject.CommandType = CommandType.Text;
        using var reader = await commandObject.ExecuteReaderAsync();
        using var ms = new MemoryStream();
        await reader.ReadToEndAsync(ms);
        ms.Position = 0;
        return ms.ToArray();
    }

    public async Task CommitTransactionAsync()
    {
        await _connection.CommitTransactionAsync();
        _connection.Dispose();
        _connection = null;
    }

    public void Dispose()
    {
        if (_connection != null) _connection.Dispose();
    }
}
