public static List<List<object>> GetDataFromDatabase(string serverName, string databaseName, string tableName)
{
    List<List<object>> data = new List<List<object>>();

    try
    {
        using (SqlConnection connection = new SqlConnection("Server=" + serverName + ";Database=" + databaseName + ";Trusted_Connection=True;"))
        {
            connection.Open();

            using (SqlCommand command = new SqlCommand($"SELECT * FROM {tableName}", connection))
            {
                using (SqlDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        List<object> rowData = new List<object>();
                        for (int i = 0; i < reader.FieldCount; i++)
