```csharp using System;
using System.Xml;

public static List<KeyValuePair<string, string>> LoadConfiguration(string filePath)
{
    if (!File.Exists(filePath))
    {
        throw new FileNotFoundException("Configuration file not found.", filePath);
    }

    List<KeyValuePair<string, string>> configuration = new List<KeyValuePair<string, string>>();

    using (XmlDocument document = new XmlDocument())
    {
        document.Load(filePath);

        if (document.DocumentElement == null)
        {
            throw new InvalidOperationException("Configuration file does not contain a valid root element.");
        }

        XmlNodeList nodes = document.DocumentElement.ChildNodes;

        for (int i = 0; i < nodes.Count; i++)
        {
            if (nodes[i].NodeType != NodeType.Element)
            {
                continue;
            }

            configuration.Add(new KeyValuePair<string, string>(nodes[i].Name, nodes[i].Attributes["value"]?.Value));
        }
    }

    return configuration;
}
