public string UpdatePassword(int userId, string newPassword)
{
    string errorMessage = string.Empty;

    try
    {
        using (SqlConnection connection = new SqlConnection("YourConnectionString"))
        {
            connection.Open();

            byte[] salt = new byte[16];
            RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider();
            rng.GetBytes(salt);

            byte[] hashedPassword;
            using (SHA256 sha256 = SHA256.Create())
            {
                byte[] passwordBytes = Encoding.UTF8.GetBytes(newPassword);
                byte[] saltedPassword = new byte[passwordBytes.Length + salt.Length];

                Buffer.BlockCopy(passwordBytes, 0, saltedPassword, 0, passwordBytes.Length);
                Buffer.BlockCopy(salt, 0, saltedPassword, passwordBytes.Length, salt.Length);

                hashedPassword = sha256.ComputeHash(saltedPassword);
            }

            using (SqlCommand command = new SqlCommand("UPDATE users SET password_hash = @password_hash WHERE user_id = @user_id", connection))
            {
                command.Parameters.AddWithValue("@password_hash", Convert.ToBase64String(hashedPassword));
                command.Parameters.AddWithValue("@user_id", userId);
                command.ExecuteNonQuery();
            }

            errorMessage = "Password updated successfully.";
        }
    }
    catch (SqlException ex)
    {
        errorMessage = $"Error updating password: {ex.Message}";
    }
    catch (Exception ex)
    {
