```java
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public int addVillain(String name, double evilnessFactor, Connection connection, PreparedStatement transaction) throws SQLException {
    try {
        // Start the transaction if it's not already started
        if (transaction == null || !transaction.isStarted()) {
            transaction.setAutoCommit(false);
        }

        PreparedStatement ps = connection.prepareStatement("INSERT INTO Villains(name, evilness_factor) values(?,?);", PreparedStatement.RETURN_GENERATED_KEYS);
        ps.setString(1, name);
        ps.setDouble(2, evilnessFactor);
        ps.executeUpdate();

        int lastInsertedId = 0;
        if (ps.getGeneratedKeys() != null && ps.getGeneratedKeys().next()) {
            lastInsertedId = ps.getInt(1);
        }

        System.out.println("Successfully added villain with ID: " + lastInsertedId);
        ps.close();

        // Commit the transaction
        transaction.commit();

        return lastInsertedId;
    } catch (SQLException e) {
        if (transaction != null) {
            try {
                transaction.rollback();
            } catch (SQLException ex) {
                ex.printStackTrace();
            }
        }
        throw e;
    }
}
```

