using System.Diagnostics;

public static int RunProcessWithTimeout(string executablePath, string[] arguments, int timeoutMilliseconds)
{
    ProcessStartInfo processInfo = new ProcessStartInfo
    {
        FileName = executablePath,
        Arguments = string.Join(" ", arguments),
        UseShellExecute = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        CreateNoWindow = true
    };

    using (Process process = new Process())
    {
        process.StartInfo = processInfo;
        process.Start();

        if (process.ExitCode != 0)
        {
            return process.ExitCode;
        }

        using (StreamReader outputReader = process.StandardOutput.BaseStream.AsAsyncReader())
        using (StreamReader errorReader = process.StandardError.BaseStream.AsAsyncReader())
        {
            string output = await outputReader.ReadToEndAsync();
            string error = await errorReader.ReadToEndAsync();

            Console.WriteLine($"Output: {output}");
            Console.WriteLine($"Error: {error}");
        }

        if (timeoutMilliseconds > 0)
        {
            using (Timer timer = new Timer(timeoutMilliseconds))
            {
                timer.Elapsed += (sender, args) =>
                {
                    process.Kill();
                };

                timer.Start();

                process.WaitForExit();

                timer.Dispose();
            }
        }
        else
        {
            process.WaitForExit();
        }
    }

    return process.ExitCode;
}
