public class RichTextBoxEx : RichTextBox
{
    private bool _isCtrlKeyDown;

    protected override void OnKeyDown(KeyEventArgs e)
    {
        base.OnKeyDown(e);

        if (e.KeyCode == Keys.ControlKey && (e.Modifiers & Keys.KeyCode.Any) == Keys.Control)
        {
            _isCtrlKeyDown = true;
        }

        if (e.KeyCode == Keys.A && _isCtrlKeyDown)
        {
            this.SelectAll();
            _isCtrlKeyDown = false;
        }

        if (e.KeyCode == Keys.L && _isCtrlKeyDown)
        {
            if (this.SelectionFormat.Link != Link.None)
            {
                Process.Start(this.SelectionText);
                e.Handled = true;
            }

            _isCtrlKeyDown = false;
        }
    }

    protected override void OnTextChanged(EventArgs e)
    {
        base.OnTextChanged(e);

        this.SelectionFormat = new RichTextBoxSelectionFormat();
    }

    protected override void OnMouseClick(MouseEventArgs e)
    {
        base.OnMouseClick(e);

        if (e.Button == MouseButtons.Right)
        {
            if (this.SelectionFormat.Link != Link.None)
            {
                ContextMenuStrip contextMenu = new ContextMenuStrip();
                ToolStripItem openItem = new ToolStripMenuItem("Open URL", null, (sender, args) => Process.Start(this.SelectionText));
                contextMenu.Items.Add(openItem);
                contextMenu.Show(this, e.Location);
            }
        }
    }

    protected override void OnMouseUp(MouseEventArgs e)
    {
        base.OnMouseUp(e);

        if (e.Button == MouseButtons.Right)
        {
            contextMenu.Dispose();
        }
    }

    private void OnUrlChange()
    {
        if (this.SelectionFormat.Link != Link.None)
        {
            this.SelectionFormat = new RichTextBoxSelectionFormat();
        }
    }

    private class RichTextBoxSelectionFormat : RichTextBox.SelectionFormat
    {
        public Link Link { get; set; }
    }
}

