```csharp using System;
using System.Xml.XPath;

public static XPathNavigator GetFirstElementByName(XPathDocument document, string elementName)
{
    if (document == null)
    {
        throw new ArgumentNullException(nameof(document), "XML document is null.");
    }

    XPathNavigator navigator = document.CreateNavigator();
    XPathExpression expression = XPathExpression.Compile(elementName);

    XPathNodeIterator iterator = navigator.Select(expression, "/");

    if (iterator.MoveNext())
    {
        return iterator;
    }
    else if (iterator.HasMoreNodes)
    {
        throw new XPathException("Multiple elements with the given name found.");
    }
    else
    {
        throw new XPathException("Element not found.");
    }
}
