```csharp using System;
using System.Diagnostics;
using System.IO;

public static void RunProcessAsRealUser(string userName, string password, string filePath)
{
    try
    {
        using (var processStartInfo = new ProcessStartInfo())
        {
            processStartInfo.FileName = "cmd.exe";
            processStartInfo.Arguments = $"/c runas /user:{userName} "{filePath}"";
            processStartInfo.UseShellExecute = false;
            processStartInfo.RedirectStandardOutput = true;
            processStartInfo.RedirectStandardError = true;

            using (var process = new Process())
            {
                process.StartInfo = processStartInfo;
                process.Start();

                string output = string.Empty;
                string error = string.Empty;

                using (var outputStream = process.StandardOutput.BaseStream)
                using (var errorStream = process.StandardError.BaseStream)
                {
                    using (var outputReader = new StreamReader(outputStream))
                    using (var errorReader = new StreamReader(errorStream))
                    {
                        output = outputReader.ReadToEnd();
                        error = errorReader.ReadToEnd();
                    }
                }

                process.WaitForExit();

                if (!string.IsNullOrEmpty(error))
                {
                    Console.Error.WriteLine($"Error running process: {error}");
                    throw new Exception($"Error running process: {error}");
                }

                Console.WriteLine($"Process exited with code: {process.ExitCode}");
                Console.WriteLine($"Output: {output}");
            }
        }
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"Error starting process: {ex.Message}");
    }
}
