std::string get_last_inserted_id(const std::string& table_name, const void* db_connection) {
    // Create a prepared statement with a parameter for the table name
    sqlite3_stmt* statement;
    int rc = sqlite3_prepare_v2(static_cast<sqlite3*>(db_connection),
                                "SELECT last_insert_rowid() FROM sqlite_master "
                                "WHERE type = 'table' AND name = ?;",
                                -1, &statement, nullptr);

    if (rc != SQLITE_OK) {
        // Handle error here
        sqlite3_finalize(statement);
        return {};
    }

    // Bind the table name to the statement
    rc = sqlite3_bind_text(statement, 1, table_name.c_str(), -1, SQLITE_TRANSIENT);

    if (rc != SQLITE_OK) {
        // Handle error here
        sqlite3_finalize(statement);
        return {};
    }

    // Execute the prepared statement
    rc = sqlite3_step(statement);

    if (rc != SQLITE_ROW) {
        // Handle error here
        sqlite3_finalize(statement);
        return {};
    }

    // Retrieve the last inserted ID from the statement
    int64_t last_inserted_id = sqlite3_column_int64(statement, 0);

    // Finalize the statement and return the last inserted ID as a std::string
    sqlite3_finalize(statement);
    return std::to_string(last_inserted_id);
}
