public class UserValidationConfiguration
{
    private readonly UserManager<IdentityUser> _userManager;
    private readonly IOptions<PasswordValidatorOptions> _passwordValidatorOptions;

    public UserValidationConfiguration(UserManager<IdentityUser> userManager, IOptions<PasswordValidatorOptions> passwordValidatorOptions)
    {
        _userManager = userManager;
        _passwordValidatorOptions = passwordValidatorOptions;
    }

    public async Task<IdentityError[]> ValidateUserAsync(string username, string password)
    {
        if (string.IsNullOrWhiteSpace(username))
        {
            return new IdentityError[] { new IdentityError { Code = "InvalidUsername", Description = "Invalid username." } };
        }

        if (string.IsNullOrWhiteSpace(password))
        {
            return new IdentityError[] { new IdentityError { Code = "InvalidPassword", Description = "Invalid password." } };
        }

        var user = await _userManager.FindByNameAsync(username);

        if (user != null)
        {
            return new IdentityError[] { new IdentityError { Code = "UsernameAlreadyExists", Description = "Username already exists." } };
        }

        var validationResult = await _userManager.PasswordValidator.ValidateAsync(new IdentityUser { UserName = username }, password);

        if (!validationResult.Succeeded)
        {
            return validationResult.Errors;
        }

        return new IdentityError[0];
    }

    public void ConfigurePasswordValidation()
    {
        var passwordValidator = _passwordValidatorOptions.Value;
        passwordValidator.RequireDigit = true;
        passwordValidator.RequireLowercase = true;
        passwordValidator.RequireUppercase = true;
        passwordValidator.RequireNonAlphanumeric = true;
        passwordValidator.RequireMinimumLength = 8;
    }
}
