public static bool IsNullCiphersSupported()
{
    const int CRYPT_NULL_SESSION = 0;
    const int CRYPT_SUCCESS = 0;

    [DllImport("crypt32.dll", CharSet = CharSet.Auto)]
    static extern int CryptAcquireContext(
        IntPtr hLocalContext,
        string lpstrName,
        IntPtr hProv,
        int dwFlags,
        int dwClrContext,
        Int32 dwPropParam,
        out IntPtr phContext
    );

    [DllImport("crypt32.dll", CharSet = CharSet.Auto)]
    static extern int CryptReleaseContext(
        IntPtr hProv,
        IntPtr hContext,
        bool fCloseHandle
    );

    IntPtr hContext = IntPtr.Zero;

    try
    {
        if (CryptAcquireContext(IntPtr.Zero, null, IntPtr.Zero, 0, 0, 0, out hContext) == CRYPT_SUCCESS)
        {
            int result = CryptSetSessionProperty(hContext, CRYPT_SESSION_PROPERTY_ENCRYPTION_MODE, new IntPtr(CRYPT_NULL_SESSION));
            if (result == CRYPT_SUCCESS)
            {
                return true;
            }
            else
            {
                throw new Exception("Failed to set null cipher encryption mode.");
            }
        }
        else
        {
            throw new Exception("Failed to acquire cryptographic context.");
        }
    }
    finally
    {
        if (hContext != IntPtr.Zero)
        {
            CryptReleaseContext(IntPtr.Zero, hContext, true);
        }
    }

    throw new NotSupportedException("Null ciphers are not supported on this operating system.");
}
