```csharp using System;
using System.IO;
using System.Diagnostics;

public static void CopySafeFiles(string sourceDir, string targetDir, string[] includeExtensions, string[] excludeExtensions) {
    DirectoryInfo sourceDirInfo = new DirectoryInfo(sourceDir);

    if (!sourceDirInfo.Exists) {
        throw new DirectoryNotFoundException($"Source directory '{sourceDir}' does not exist.");
    }

    if (!Directory.Exists(targetDir)) {
        Directory.CreateDirectory(targetDir);
    }

    FileInfo[] files = sourceDirInfo.GetFiles();

    foreach (FileInfo file in files) {
        string fileName = file.Name;
        string extension = Path.GetExtension(fileName);

        bool include = false;
        bool exclude = false;

        foreach (string ext in includeExtensions) {
            if (extension.Equals(ext, StringComparison.OrdinalIgnoreCase)) {
                include = true;
                break;
            }
        }

        foreach (string ext in excludeExtensions) {
            if (extension.Equals(ext, StringComparison.OrdinalIgnoreCase)) {
                exclude = true;
                break;
            }
        }

        if (!include && !exclude) continue;

        string targetPath = Path.Combine(targetDir, fileName);
        File.Copy(file.FullName, targetPath, File.Exists(targetPath) ? FileOptions.ReplaceExisting : FileOptions.None);
    }

    DirectoryInfo targetDirInfo = new DirectoryInfo(targetDir);

    FileInfo[] subDirs = targetDirInfo.GetDirectories();

    foreach (FileInfo subDir in subDirs) {
        string subDirName = subDir.Name;
        string subDirPath = Path.Combine(targetDir, subDirName);
        CopySafeFiles(sourceDir, subDirPath, includeExtensions, excludeExtensions);
        subDir.Delete(true);
    }
}

public static void CheckPath(string path) {
    if (string.IsNullOrEmpty(path) || path.Contains("..") || path.Contains("/.") || path.StartsWith("./")) {
        throw new ArgumentException("Invalid path.", nameof(path));
    }
}

public static void Main() {
    string sourceDir = @"C:\source";
    string targetDir = @"C:\target";
    string[] includeExtensions = { ".txt", ".jpg" };
    string[] excludeExtensions = { ".exe", ".bat" };

    try {
        CopySafeFiles(sourceDir, targetDir, includeExtensions, excludeExtensions);
        Console.WriteLine("Copy completed successfully.");
    } catch (Exception ex) {
        Console.WriteLine($"Error: {ex.Message}");
    }
}
```

