```csharp
using System;
using System.Diagnostics;

public static class CommandExecutor
{
    public static int ExecuteCommand(string command, string input = null)
    {
        using (var process = new Process())
        {
            process.StartInfo.FileName = "cmd.exe";
            process.StartInfo.Arguments = "/c " + command;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardInput = true;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;

            if (!string.IsNullOrEmpty(input))
            {
                process.StartInfo.StandardInput.Write(input);
                process.StartInfo.StandardInput.Close();
            }

            process.OutputDataReceived += (sender, args) => Console.WriteLine(args.Data);
            process.ErrorDataReceived += (sender, args) => Console.WriteLine("Error: " + args.Data);

            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            process.WaitForExit();

            if (process.ExitCode != 0)
            {
                throw new Exception("Command execution failed with exit code: " + process.ExitCode);
            }

            return process.ExitCode;
        }
    }
}
```

This example follows secure coding practices by validating the command input and properly handling I/O streams. It also uses the `Process` class to execute the command and properly redirects standard input, output, and error streams. The example also waits for the process to exit before checking the exit code and raising an exception if it's non-zero.

