    public RemoteServiceClient(string remoteServiceUrl, string retryCount, int retryDelay)
    {
        _remoteServiceUrl = remoteServiceUrl;
        _retryCount = retryCount;
        _retryDelay = retryDelay;
    }

    public async Task<bool> ExecuteExternalProcessAndCallRemoteMethodAsync(string filePath)
    {
        if (!IsSafeDirectory(filePath))
        {
            throw new ArgumentException("Invalid file path.");
        }

        ProcessStartInfo processInfo = new ProcessStartInfo
        {
            FileName = filePath,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };

        using (Process process = Process.Start(processInfo))
        {
            string output = await ReadProcessOutputAsync(process);
            string error = await ReadProcessErrorAsync(process);

            if (!string.IsNullOrEmpty(error))
            {
                Console.Error.WriteLine($"Error while executing external process: {error}");
            }

            Console.WriteLine($"Output from external process: {output}");
        }

        bool result = await CallRemoteMethodAsync();

        if (!result)
        {
            for (int i = 0; i < int.Parse(_retryCount); i++)
            {
                try
                {
                    result = await CallRemoteMethodAsync();
                    break;
                }
                catch (Exception ex)
                {
                    if (i < int.Parse(_retryCount) - 1)
                    {
                        await Task.Delay(_retryDelay);
                    }
                }
            }
        }

        return result;
    }

    private bool IsSafeDirectory(string filePath)
    {
        Uri uri = new Uri(filePath);
        string safeDirectory = uri.GetDirectoryName();

        return safeDirectory != null && new DirectoryInfo(safeDirectory).Exists;
    }

    private async Task<string> ReadProcessOutputAsync(Process process)
    {
        using (StreamReader reader = new StreamReader(process.StandardOutput))
        {
            return await reader.ReadToEndAsync();
        }
    }

    private async Task<string> ReadProcessErrorAsync(Process process)
    {
        using (StreamReader reader = new StreamReader(process.StandardError))
        {
            return await reader.ReadToEndAsync();
        }
    }

    private async Task<bool> CallRemoteMethodAsync()
    {
        using (HttpClient client = new HttpClient())
        {
            HttpResponseMessage response = await client.GetAsync(_remoteServiceUrl);

            if (response.IsSuccessStatusCode)
            {
                string content = await response.Content.ReadAsStringAsync();
                bool result = bool.Parse(content);
                return result;
            }
            else
            {
                throw new Exception($"Error calling remote method: {response.ReasonPhrase}");
            }
        }
    }
}

public static void Main()
{
    string filePath = @"C:\path\to\executable.exe";
    string remoteServiceUrl = "http://remote-service.com/api/method";
    string retryCount = "3";
    int retryDelay = 1000;

    RemoteServiceClient client = new RemoteServiceClient(remoteServiceUrl, retryCount, retryDelay);

    try
    {
        await client.ExecuteExternalProcessAndCallRemoteMethodAsync(filePath);
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"Error: {ex.Message}");
    }
}
