public static string DecryptDES(string hexEncryptedMessage)
{
    if (!IsValidHexadecimal(hexEncryptedMessage))
    {
        throw new ArgumentException("Invalid hexadecimal representation of DES-encrypted message.");
    }

    byte[] encryptedData;
    try
