    using (var des = DES.Create())
    using (var msEncrypt = new MemoryStream())
    using (var bwEncrypt = new BinaryWriter(msEncrypt))
    {
        bwEncrypt.Write(Encoding.ASCII.GetBytes(KEY), 0, KEY.Length);
        des.IV = msEncrypt.ToArray();
        var encryptedBytes = des.CreateEncryptor().TransformFinalBlock(encryptedData, 0, encryptedData.Length);
        msEncrypt.Write(encryptedBytes, 0, encryptedBytes.Length);
        msEncrypt.Position = 0;

        using (var msDecrypt = new MemoryStream())
        using (var bwDecrypt = new BinaryWriter(msDecrypt))
        {
            bwDecrypt.Write(Encoding.ASCII.GetBytes(KEY), 0, KEY.Length);
            using (var csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(), CryptoStreamMode.Write))
            {
                csDecrypt.Write(msEncrypt.ToArray(), 0, msEncrypt.ToArray().Length);
                csDecrypt.FlushFinalBlock();
            }

            return Encoding.ASCII.GetString(msDecrypt.ToArray());
        }
    }
