private static bool IsValidHexadecimal(string hex)
{
    if (string.IsNullOrEmpty(hex))
        return false;

    for (int i = 0; i < hex.Length; i++)
    {
        if (!Hexadecimal.TryParse(hex[i].ToString(), out _))
            return false;
    }

    return true;
}

private static byte[] HexStringToByteArray(string hex)
{
    int NumberChars;
    byte[] bytes = new byte[hex.Length / 2];

    NumberChars = Convert.FromBase64String(Convert.ToBase64String(Encoding.ASCII.GetBytes(hex), 0, hex.Length), out byte[] _).Length;

    if (NumberChars > bytes.Length)
        throw new ArgumentException("Invalid hexadecimal representation of DES-encrypted message.");

    for (int i = 0; i < NumberChars; i++)
    {
        bytes[i] = Convert.ToByte(hex.Substring(2 * i, 2), 16);
    }

    return bytes;
}

