import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public static String getMD5Hash(byte[] data) {
    try {
        SecretKeySpec secretKey = new SecretKeySpec("MD5".getBytes(), "HmacMD5");
