using System.Diagnostics;
using System.IO;

public static void OpenProjectOrSolutionInVisualStudio(string projectFilePath) {
    if (!File.Exists(projectFilePath)) {
        throw new FileNotFoundException("Project or solution file not found at the given path.", projectFilePath);
    }

    string extension = Path.GetExtension(projectFilePath).ToLowerInvariant();

    if (extension == ".sln") {
        Process.Start("devenv.exe", $"\"{projectFilePath}\" /resetuserdata");
    } else if (extension == ".csproj" || extension == ".vbproj") {
        Process.Start("devenv.exe", $"\"{projectFilePath}\" /open");
    } else {
        throw new ArgumentException("Invalid project or solution file extension.", nameof(projectFilePath));
    }
}
