```csharp using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public static class SerializationHelper
{
    public static void Serialize<T>(T obj, string filePath)
    {
        using (FileStream fileStream = new FileStream(filePath, FileMode.Create))
        {
            BinaryFormatter binaryFormatter = new BinaryFormatter();
            binaryFormatter.Serialize(fileStream, obj);
        }

        // Validate file size and type after serialization
        FileInfo fileInfo = new FileInfo(filePath);
        if (fileInfo.Length > int.MaxValue)
        {
            throw new InvalidOperationException("File size too large for serialization.");
        }

        using (FileStream fileStream = new FileStream(filePath, FileMode.Open))
        {
            byte[] fileBytes = new byte[Convert.ToInt32(fileInfo.Length)];
            fileStream.Read(fileBytes, 0, Convert.ToInt32(fileInfo.Length));
            Type fileType = typeof(T);
            Type deserializedType = Type.GetType(fileBytes[0].ToString() + ":" + fileType.AssemblyQualifiedName.Substring(fileType.AssemblyQualifiedName.LastIndexOf(",", StringComparison.Ordinal) + 1));

            if (deserializedType != fileType)
            {
                throw new InvalidOperationException("Deserialized type does not match expected type.");
            }

            BinaryFormatter deserializer = new BinaryFormatter();
            object deserializedObject = deserializer.Deserialize(new MemoryStream(fileBytes));

            if (deserializedObject is not T)
            {
                throw new InvalidCastException("Deserialized object cannot be cast to expected type.");
            }
        }
    }

    public static T Deserialize<T>(string filePath)
    {
        T deserializedObject = default;

        try
        {
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open))
            {
                BinaryFormatter binaryFormatter = new BinaryFormatter();
                deserializedObject = (T)binaryFormatter.Deserialize(fileStream);
            }
        }
        catch (SerializationException)
        {
            throw new InvalidOperationException("Failed to deserialize object from file.");
        }

        // Validate file size and type after deserialization
        FileInfo fileInfo = new FileInfo(filePath);
        if (fileInfo.Length > int.MaxValue)
        {
            throw new InvalidOperationException("File size too large for deserialization.");
        }

        return deserializedObject;
    }
}
