```csharp
using System;
using System.Diagnostics;
using System.Security.Cryptography;

public static string GetAuthorizationCodeFromConsole(string uri)
{
    // Validate the input URI
    if (string.IsNullOrEmpty(uri))
    {
        throw new ArgumentException("URI cannot be null or empty.");
    }

    // Start the process to open the URI
    Process process = new Process();
    process.StartInfo.FileName = "cmd.exe";
    process.StartInfo.Arguments = $"/c start {uri}";
    process.StartInfo.UseShellExecute = false;
    process.StartInfo.RedirectStandardOutput = true;
    process.Start();

    // Read the authorization code from the console
    string authorizationCode = string.Empty;
    ConsoleKeyInfo keyInfo;
    do
    {
        keyInfo = Console.ReadKey(true);
        if (keyInfo.KeyChar == ConsoleKey.Enter)
        {
            // Remove any leading or trailing newline characters
            authorizationCode = Console.ReadLine().Trim();
            break;
        }
    } while (true);

    // Close the process
    process.WaitForExit();

    // Validate the authorization code
    if (string.IsNullOrEmpty(authorizationCode))
    {
        throw new Exception("Authorization code not provided.");
    }

    // Use a secure method to hash the authorization code for added security
    byte[] hash = SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(authorizationCode));

    // Return the hashed authorization code
    return Convert.ToBase64String(hash);
}
