public static string EncryptStringSymmetric(string inputData, byte[] key)
{
    if (string.IsNullOrEmpty(inputData) || key == null)
    {
        throw new ArgumentNullException();
    }

    using (MD5 md5 = MD5.Create())
    {
        byte[] keyDerived = md5.ComputeHash(key);
        byte[] iv = new byte[16]; // 16 bytes IV for AES

        using (Aes aes = Aes.Create())
