                    using (StreamWriter sw = new StreamWriter(cs))
                    {
                        sw.Write(inputData);
                    }

                    byte[] encryptedData = ms.ToArray();
                    return Convert.ToBase64String(encryptedData);
                }
            }
        }
    }
