using System.IO;
using System.Xml.XPath;
using System.Xml.XDocument;

public int UpdateConfigurationFile(string configPath, string xpathExpressionToRemove)
{
    if (string.IsNullOrEmpty(configPath) || string.IsNullOrEmpty(xpathExpressionToRemove))
    {
        throw new ArgumentException("Both configPath and xpathExpressionToRemove must be provided.");
    }

    int elementsRemoved = 0;

    using (XDocument document = XDocument.Load(configPath))
    {
        XPathDocument xPathDocument = new XPathDocument(document.CreateReader());
        XPathNavigator navigator = xPathDocument.CreateNavigator();

        XPathExpression xPathExpression = XPathExpression.Compile(xpathExpressionToRemove);

        while (navigator.MoveNext())
        {
            if (navigator.NodeType == XPathNodeType.Element && navigator.Name == xpathExpression.CompiledValue.LocalName)
            {
                navigator.RemoveCurrentNode();
                elementsRemoved++;
            }
        }

        document.Save(configPath);
    }

    return elementsRemoved;
}
