```csharp using System;
using System.Xml.XPath;
using System.IO;
using System.Xml.Linq;

public static void AddIndexProviderSection(string configFilePath, string existingSectionXPath, XDocument newIndexProvider)
{
    if (!File.Exists(configFilePath))
    {
        throw new FileNotFoundException("The configuration file does not exist."); //$NON-NLS-1$
    }

    XDocument configDocument = XDocument.Load(configFilePath);
    XElement rootElement = configDocument.Root;

    // Ensure the existing section exists before adding a new one
    XElement existingSection = rootElement.XPathSelectElements(existingSectionXPath).FirstOrDefault();
    if (existingSection == null)
    {
        throw new ArgumentException("The specified existing section does not exist in the configuration file."); //$NON-NLS-1$
    }

    // Add the new index provider section after the existing one
    existingSection.AddAfterSelf(newIndexProvider.Root);

    configDocument.Save(configFilePath);
}
