    if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(existingXPath) || string.IsNullOrEmpty(insertAfterXPath))
    {
        throw new ArgumentNullException();
    }

    XDocument doc;
    try
    {
        doc = XDocument.Load(filePath);
    }
    catch (FileNotFoundException)
    {
        throw new FileNotFoundException("The specified XML file does not exist.");
    }
    catch (XmlException ex)
    {
        throw new XmlException("Error loading XML file.", ex);
    }

    XElement existingElement = null;
    XElement elementToInsertAfter = null;

    try
    {
        existingElement = doc.XPathSelectElement(existingXPath);
        if (existingElement == null)
        {
            throw new XPathException("The specified existing element was not found.");
        }

        elementToInsertAfter = doc.XPathSelectElement(insertAfterXPath);
        if (elementToInsertAfter == null)
        {
            throw new XPathException("The specified element to insert after was not found.");
        }
    }
    catch (XPathException ex)
    {
        throw new XPathException("Error selecting elements using XPath.", ex);
    }

    int index = doc.Root.Elements().IndexOf(existingElement);
    if (index < 0)
    {
        throw new ApplicationException("Internal error: Existing element not found in document.");
    }

    doc.Root.Elements().RemoveAt(index + 1); // Remove the element after the existing one
    doc.Root.Elements().AddAfterSelf(newElement); // Add the new element after the existing one

    return doc.ToString();
}
