public string GetParameterDocumentation(XPathDocument xmlDocument, string methodName, string parameterName) {
  XPathNavigator navigator = xmlDocument.CreateNavigator();

  XPathExpression methodExpression = navigator.Compile("/methods/method[@name=$methodName]");
  XPathNodeIterator methodIterator = methodExpression.Evaluate(navigator, "{$methodName:" + methodName + "}");

  if (methodIterator.MoveNext()) {
