using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public static T ReadLastObjectFromFile<T>(string filePath)
{
    using (FileStream file = File.Open(filePath, FileMode.Open, FileAccess.Read))
    {
        BinaryFormatter binaryFormatter = new BinaryFormatter();
        object deserializedObject = null;

        while (file.Position < file.Length)
        {
            deserializedObject = binaryFormatter.Deserialize(file);
            if (deserializedObject is T && file.Position == file.Length - 1)
            {
                return (T)deserializedObject;
            }
        }

        file.Seek(0, SeekOrigin.Begin); // Reset file position to the start
        throw new FileLoadException("File contains no valid objects of type T.");
    }
}
