```csharp using System;
using System.Xml.Linq;

public List<Setting> LoadAndUpdateSettings(string filePath)
{
    if (!File.Exists(filePath))
    {
        throw new FileNotFoundException("Configuration file not found.", filePath);
    }

    XDocument configDoc = XDocument.Load(filePath);

    List<Setting> settings = new List<Setting>();

    XElement root = configDoc.Root;

    foreach (XElement settingElement in root.Elements("Setting"))
    {
        string name = settingElement.Attribute("Name").Value;
        string value = settingElement.Value;

        Setting newSetting = new Setting { Name = name, Value = value };
        settings.Add(newSetting);
    }

    return settings;
}
