public static byte[] TestEncryptionDecryptionECBZeroPadding(SymmetricAlgorithm algorithm, byte[] key, byte[] plaintext)
{
    if (algorithm == null || key == null || plaintext == null)
    {
        throw new ArgumentNullException();
    }

    if (algorithm.KeySize != key.Length * 8)
    {
        throw new ArgumentException("Invalid key size.");
    }

    int effectiveKeySize = algorithm.KeySize;
    int blockSize = algorithm.BlockSize;

    if (effectiveKeySize % blockSize != 0)
    {
        throw new ArgumentException("Invalid effective key size.");
    }

