    {
        encrypted = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
        byte[] iv = encryptor.IV;
    }

    int encryptedLength = encrypted.Length;

    if (encryptedLength % blockSize != 0)
    {
        throw new ArgumentException("Encrypted message is not a multiple of the block size.");
    }

    byte[] decrypted;
    using (ICryptoTransform decryptor = algorithm.CreateDecryptor(key, iv))
