const { v4: uuidv4 } = require('uuid');
const crypto = require('crypto');

function addRandomVerticesAndEdges(graph, numVertices, numEdges) {
  if (numVertices < 0 || numEdges < 0) {
    throw new Error('Invalid number of vertices or edges');
  }

  const vertices = [];
  const properties = [];

  for (let i = 0; i < numVertices; i++) {
    const id = uuidv4();
    const propertiesLength = Math.floor(Math.random() * 10) + 5;
    properties.push(generateRandomProperties(propertiesLength));
    vertices.push({ id, properties });
  }

  if (numEdges > 0) {
    const edges = [];

    for (let i = 0; i < numEdges; i++) {
      const vertex1Index = Math.floor(Math.random() * numVertices);
      const vertex2Index = (vertex1Index + Math.floor(Math.random() * 2)) % numVertices;

      const id = uuidv4();
      const propertiesLength = Math.floor(Math.random() * 5) + 3;
      const properties1 = generateRandomProperties(propertiesLength);
      const properties2 = generateRandomProperties(propertiesLength);

      edges.push({
        id,
        from: vertices[vertex1Index].id,
        to: vertices[vertex2Index].id,
        properties1,
        properties2
      });
    }

    graph.addVertices(vertices);
    graph.addEdges(edges);
  } else {
    graph.addVertices(vertices);
  }
}

function generateRandomProperties(length) {
  const properties = {};

  for (let i = 0; i < length; i++) {
    const key = `property${i}`;
    const value = crypto.randomBytes(Math.floor(Math.random() * 10) + 5).toString('hex');
    properties[key] = value;
  }

  return properties;
}
