public enum ValidType { INT, FLOAT, BOOL; }

public static <T> T getRandomValue(Class<T> type, ValidType validType, int limit) {
    Random random = new Random();
    T value;

    switch (validType) {
        case INT:
            int randomInt = random.nextInt(limit);
            value = (T) Integer.valueOf(randomInt);
            break;
        case FLOAT:
