import java.math.BigDecimal;
import java.security.SecureRandom;
import java.util.Random;

public class SecureRandomGenerator {

    private static final SecureRandom SECURE_RANDOM = new SecureRandom();
    private static final Random RANDOM = new Random();

    public static <T> T generateRandomValue(Class<T> type) {
        if (type == Byte.TYPE) {
            return (T) (byte) SECURE_RANDOM.nextInt(Byte.MAX_VALUE + 1);
        } else if (type == Short.TYPE) {
            return (T) (short) SECURE_RANDOM.nextInt(Short.MAX_VALUE + 1);
        } else if (type == Integer.TYPE) {
            return (T) SECURE_RANDOM.nextInt();
        } else if (type == Long.TYPE) {
            return (T) SECURE_RANDOM.nextLong();
        } else if (type == Float.TYPE) {
            return (T) SECURE_RANDOM.nextFloat();
        } else if (type == Double.TYPE) {
            return (T) SECURE_RANDOM.nextDouble();
        } else if (type == Character.TYPE) {
            char randomChar = (char) SECURE_RANDOM.nextInt(Character.MAX_VALUE + 1);
            return (T) randomChar;
        } else if (type == String.class) {
            int length = SECURE_RANDOM.nextInt(10) + 5; // Generate a random string of length between 5 and 14
            char[] chars = new char[length];
            for (int i = 0; i < length; i++) {
                chars[i] = (char) (SECURE_RANDOM.nextInt(Character.MAX_VALUE + 1) & 0xFF);
            }
            return (T) new String(chars);
        } else if (type == BigDecimal.class) {
            BigDecimal randomDecimal = new BigDecimal(SECURE_RANDOM.nextLong());
            return (T) randomDecimal;
        } else {
            throw new UnsupportedOperationException("Unsupported type: " + type.getName());
        }
    }
}
