import org.apache.lucene.document.Document;
import org.apache.lucene.document.NumericDocValuesField;
import org.apache.lucene.queryparser.ClassicQueryParser;
import org.hamcrest.MatcherAssert;
import org.hamcrest.Matchers;

public void compareNumericFields(String indexName, String docId1, String docId2, String fieldName) {
    try (IndexReader reader = IndexReader.open(FSDirectory.open(new File(indexName)), true)) {
        Document doc1 = reader.document(new Text(docId1));
        Document doc2 = reader.document(new Text(docId2));

        // Validate document existence
        if (doc1 == null || doc2 == null) {
            throw new IllegalArgumentException("Invalid document IDs: " + docId1 + ", " + docId2);
        }

        // Load and validate numeric fields
        NumericDocValuesField numField1 = doc1.getNumericField(fieldName);
        NumericDocValuesField numField2 = doc2.getNumericField(fieldName);

        if (numField1 == null || numField2 == null) {
            throw new IllegalArgumentException("Field '" + fieldName + "' not found in documents.");
        }

        int numValues1 = numField1.numValues();
        int numValues2 = numField2.numValues();

        if (numValues1 != numValues2) {
            throw new AssertionError("Number of values in field '" + fieldName + "' is different between documents.");
        }

        // Compare values
        ClassicQueryParser parser = new ClassicQueryParser(new StandardAnalyzer(), fieldName, true);
        TopDocs topDocs1 = search(parser.parse(new Query()), reader, 1);
        TopDocs topDocs2 = search(parser.parse(new Query()), reader, 1);

        MatcherAssert.assertThat(topDocs1.scoreDocs[0].doc, Matchers.equalTo(doc1.docID()));
        MatcherAssert.assertThat(topDocs2.scoreDocs[0].doc, Matchers.equalTo(doc2.docID()));

        NumericDocValuesField valueField1 = (NumericDocValuesField) doc1.getField(fieldName);
        NumericDocValuesField valueField2 = (NumericDocValuesField) doc2.getField(fieldName);

        for (int i = 0; i < numValues1; i++) {
            double value1 = valueField1.doubleValue(i);
            double value2 = valueField2.doubleValue(i);

            MatcherAssert.assertThat(value1, Matchers.closeTo(value2, 0.001));
        }
    } catch (IOException e) {
        throw new RuntimeException("Error loading documents or index: " + e.getMessage(), e);
    }
}
