import java.util.List;
import java.util.Random;

public void shufflePairs(List<Pair> pairs, double percentage) {
    Random random = new Random();
    int indexToMove = 0;
    int pairsProcessed = 0;

    while (pairsProcessed < percentage * pairs.size()) {
        int lastIndex = pairs.size() - 1;
        if (indexToMove == lastIndex) {
            System.out.println("Last pair processed: " + pairs.get(indexToMove));
            break;
        }

        int randomIndex = random.nextInt(indexToMove, lastIndex + 1);
        Pair tempPair = pairs.get(indexToMove);
