            }
            seekResult = fstEnum.seekExact(term);
            pos = -1;
          } else if (random.nextBoolean()) {
            if (LuceneTestCase.VERBOSE) {
              System.out.println("  do non-exist seekFloor term=" + inputToString(inputMode, term));
            }
            seekResult = fstEnum.seekFloor(term);
