import java.net.InetSocketAddress;

public String getRemoteIPAddress(SocketSessionEx session) {
    InetSocketAddress remoteAddress = (InetSocketAddress) session.getRemoteAddress();
    byte[] addressBytes;

    if (remoteAddress != null) {
        addressBytes = remoteAddress.getAddress().getAddress();
    } else {
        throw new IllegalArgumentException("Session does not have a remote address.");
    }

    String ipAddress;
    try {
        ipAddress = InetAddress.getByAddress(addressBytes).getHostAddress();
    } catch (UnknownHostException e) {
        throw new RuntimeException("Failed to get IP address from bytes.", e);
    }

    return ipAddress;
}
