            data = new byte[Math.min(length, 1024)];
            random.nextBytes(data);

            fileOutputStream = new FileOutputStream(filePath.toFile());
            fileOutputStream.write(data);

            while (length > data.length) {
                data = new byte[Math.min(length - data.length, 1024)];
                random.nextBytes(data);
                fileOutputStream.write(data);
                length -= data.length;
            }

            if (length > 0) {
                data = new byte[length];
                random.nextBytes(data);
                fileOutputStream.write(data);
            }

            fileOutputStream.close();
        } else {
            byte randomByte = (byte) random.nextInt(0xFF);
            randomAccessFile.writeByte(randomByte);
        }

    } finally {
        if (fileOutputStream != null) {
            fileOutputStream.close();
        }

        if (randomAccessFile != null) {
            randomAccessFile.close();
        }
    }

    return new RandomAccessFile(filePath.toFile(), "r");
