import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.Mac;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.Arrays;

public class AesEncryption {
    private static final int AES_BLOCK_SIZE = 16;

    public static byte[] generateAesKey(String password, byte[] salt) {
        try {
            KeyGenerator keyGenerator = KeyGenerator.getInstance("AES");
            keyGenerator.init(128);
            SecretKey originalKey = keyGenerator.generateKey();

            byte[] keyBytes = originalKey.getEncoded();

            PBKDF2WithHmacSHA1(password, salt, keyBytes, 10000);

            return keyBytes;
        } catch (Exception e) {
            throw new RuntimeException("Error generating AES key", e);
        }
    }

    private static void PBKDF2WithHmacSHA1(String password, byte[] salt, byte[] key, int iterations) {
        try {
            Mac sha1Hmac = Mac.getInstance("HmacSHA1");
            sha1Hmac.init(new SecretKeySpec(password.getBytes(), "HmacSHA1"));

            byte[] derivedKey = new byte[key.length];
            SecureRandom random = new SecureRandom();

            for (int i = 0; i < iterations; i++) {
                sha1Hmac.update(salt);
                sha1Hmac.doFinal(key, 0, key.length, derivedKey, 0);
            }

            byte[] finalKey = new byte[key.length];
            System.arraycopy(derivedKey, 0, finalKey, 0, key.length);

            Arrays.fill(derivedKey, 0, key.length, (byte) 0);
            random.nextBytes(derivedKey);

            byte[] iv = new byte[AES_BLOCK_SIZE];
            random.nextBytes(iv);

            Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
            SecretKeySpec keySpec = new SecretKeySpec(finalKey, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(iv);

            cipher.init(keySpec, ivSpec);

            byte[] encryptedData = new byte[key.length];
            cipher.doFinal(key, 0, key.length, encryptedData, 0);

            Arrays.fill(iv, 0, iv.length, (byte) 0);

            cipher.init(keySpec, ivSpec);
            byte[] decryptedData = new byte[key.length];
            cipher.doFinal(encryptedData, 0, encryptedData.length, decryptedData, 0);

            Arrays.compare(key, decryptedData);

            if (Arrays.equals(key, decryptedData)) {
                // Key and decrypted data match, key derivation successful
            } else {
                throw new RuntimeException("Error deriving AES key");
            }
        } catch (Exception e) {
            throw new RuntimeException("Error deriving AES key", e);
        }
    }

    public static byte[] encryptData(String password, byte[] salt, byte[] data) {
        byte[] key = generateAesKey(password, salt);
