import java.util.ArrayList;
import java.util.AtomicInteger;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class GraphVertex {
    int id;
    boolean visited;

    GraphVertex(int id) {
        this.id = id;
        this.visited = false;
    }
}

class Graph {
    int numVertices;
    List<List<GraphVertex>> adjacencyList;

    Graph(int numVertices) {
        this.numVertices = numVertices;
        this.adjacencyList = new ArrayList<>();
        for (int i = 0; i < numVertices; i++) {
            adjacencyList.add(new ArrayList<>());
        }
    }

    void addEdge(int src, int dest) {
        adjacencyList.get(src).add(adjacencyList.get(dest));
        adjacencyList.get(dest).add(adjacencyList.get(src));
    }
}

class GraphTraversalThread implements Runnable {
    private final Graph graph;
    private final int startVertex;
    private static final AtomicInteger numCompletedThreads = new AtomicInteger(0);
    private static final AtomicInteger numVisitedVertices = new AtomicInteger(0);
    private static final AtomicInteger numEdges = new AtomicInteger(0);

    GraphTraversalThread(Graph graph, int startVertex) {
        this.graph = graph;
        this.startVertex = startVertex;
    }

    @Override
    public void run() {
        GraphVertex start = graph.adjacencyList.get(startVertex).get(0);
        dfs(start);

        synchronized (this) {
            numCompletedThreads.incrementAndGet();
        }
    }

    private void dfs(GraphVertex current) {
        current.visited = true;
        numVisitedVertices.incrementAndGet();

        for (GraphVertex neighbor : graph.adjacencyList.get(current.id)) {
            if (!neighbor.visited) {
                dfs(neighbor);
                numEdges.addAndGet(1);
            }
        }
    }
}

public class ConcurrentGraphTraversal {
    public static void main(String[] args) throws InterruptedException {
        int numVertices = 5;
        Graph graph = new Graph(numVertices);
        graph.addEdge(0, 1);
        graph.addEdge(0, 4);
        graph.addEdge(1, 3);
        graph.addEdge(1, 4);
        graph.addEdge(2, 1);
        graph.addEdge(3, 2);
        graph.addEdge(3, 4);

        ExecutorService executor = Executors.newFixedThreadPool(numVertices);
        List<GraphTraversalThread> threads = new ArrayList<>();

        for (int i = 0; i < numVertices; i++) {
            GraphTraversalThread thread = new GraphTraversalThread(graph, i);
            threads.add(thread);
            executor.execute(thread);
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        System.out.println("Number of vertices: " + graph.numVertices);
        System.out.println("Number of edges: " + numEdges);
        System.out.println("Number of completed threads: " + numCompletedThreads);
    }
}
