import java.io.*;

public class ProcessRunner {

    public static ProcessReturnInfo runCommand(String cmd) {
        Process process;
        ProcessBuilder pb;
        InputStream errorStream;
        InputStream inputStream;
        BufferedReader errorReader;
        BufferedReader outputReader;
        ProcessReturnInfo processReturnInfo = new ProcessReturnInfo();

        try {
            pb = new ProcessBuilder(cmd);
            process = pb.start();

            errorStream = process.getErrorStream();
            errorReader = new BufferedReader(new InputStreamReader(errorStream));
            processReturnInfo.setError(errorReader.lines().collect(Collectors.joining("\n")));

            inputStream = process.getInputStream();
            outputReader = new BufferedReader(new InputStreamReader(inputStream));
            processReturnInfo.setOutput(outputReader.lines().collect(Collectors.joining("\n")));

            process.waitFor();
            processReturnInfo.setExitCode(process.exitValue());

        } catch (IOException | InterruptedException e) {
            processReturnInfo.setError("Error occurred while running command: " + e.getMessage());
            processReturnInfo.setExitCode(-1);
        }

        return processReturnInfo;
    }

    static class ProcessReturnInfo {
        private int exitCode;
        private String error;
        private String output;

        public int getExitCode() {
