import org.json.JSONArray;
import org.json.JSONObject;

public class JsonGenerator {

    private static final JSONObject EMPTY_JSON_OBJECT = new JSONObject();
    private static final JSONArray EMPTY_JSON_ARRAY = new JSONArray();

    public static String toJson(Object object) {
        if (object == null) {
            return "null";
        }

        Class<?> clazz = object.getClass();
        if (clazz.isPrimitive) {
            return convertPrimitiveToJson(object);
        } else if (clazz.isArray()) {
            return toJsonArray(object);
        } else if (clazz.isInstance(JSONObject.class)) {
            return toJsonObject((JSONObject) object);
        } else {
            throw new UnsupportedOperationException("Unsupported object type: " + clazz.getName());
        }
    }

    private static String convertPrimitiveToJson(Object primitive) {
        if (primitive instanceof String) {
            return "\"" + ((String) primitive) + "\"";
        } else if (primitive instanceof Number) {
            Number number = (Number) primitive;
            if (number instanceof Byte) {
                return "\"" + number.byteValue() + "\"";
            } else if (number instanceof Short) {
                return "\"" + number.shortValue() + "\"";
            } else if (number instanceof Integer) {
                return number.intValue() + "";
            } else if (number instanceof Long) {
                return number.longValue() + "";
            } else if (number instanceof Float) {
                return "\"" + number.floatValue() + "\"";
            } else if (number instanceof Double) {
                return "\"" + number.doubleValue() + "\"";
            }
        } else if (primitive instanceof Boolean) {
            return ((Boolean) primitive) ? "true" : "false";
        }
        throw new RuntimeException("Unsupported primitive type: " + primitive.getClass().getName());
    }

    private static String toJsonArray(Object array) {
        JSONArray jsonArray = new JSONArray();
        for (Object element : (Object[]) array) {
            jsonArray.put(toJson(element));
        }
        return jsonArray.toString();
    }

    private static String toJsonObject(JSONObject jsonObject) {
        JSONObject jsonResult = new JSONObject();
        for (Map.Entry<String, Object> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();
            jsonResult.put(key, toJson(value));
        }
        return jsonResult.toString();
    }
}
