import org.xml.sax.SAXException;
import org.xml.sax.helpers.DefaultHandler;
import javax.xml.XMLConstants;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import java.io.File;
import java.io.IOException;

public class SAXParserWithValidation {

    public static void main(String[] args) {
        File xmlFile = new File("input.xml");

        try {
            SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
            Schema schema = schemaFactory.newSchema(new File("schema.xsd"));

            DefaultHandler handler = new DefaultHandler() {
                @Override
                public void warning(SAXParseException exception) throws SAXException {
                    System.err.println("SAX Warning: " + exception.getMessage());
                }

                @Override
                public void error(SAXParseException exception) throws SAXException {
                    System.err.println("SAX Error: " + exception.getMessage());
                    exception.printStackTrace();
                }

                @Override
                public void fatalError(SAXParseException exception) throws SAXException {
                    System.err.println("SAX Fatal Error: " + exception.getMessage());
                    System.exit(1);
                }
            };

            SAXParserFactory parserFactory = SAXParserFactory.newInstance();
            parserFactory.setSchema(schema);
            SAXParser parser = parserFactory.newSAXParser();
            parser.parse(new StreamSource(new FileInputStream(xmlFile)), handler);

        } catch (SAXException | IOException e) {
            System.err.println("Error during parsing: " + e.getMessage());
            e.printStackTrace();
            System.exit(1);
        }
    }
}
