import java.util.DisjointSet; // Standard library Union-Find implementation
import java.util.Stopwatch; // Standard library high-resolution timer

public static int countDisjointPairs(int[] arr) {
    DisjointSet<Integer> disjointSet = new DisjointSet<>();
    int n = arr.length;
    int pairs = 0;
    Stopwatch timer = Stopwatch.createStarted();

    for (int i = 0; i < n; i++) {
        int root = disjointSet.findSet(arr[i]);
        if (i > 0 && root == disjointSet.findSet(arr[i - 1])) {
            continue; // Skip if pair is not disjoint
        }
        disjointSet.union(arr[i], arr[i] + 1); // Union with next element to mark pair as disjoint
        pairs++;
        long timeTaken = timer.elapsedNanos();
        System.out.printf("Pair (%d, %d) is disjoint and took %d ns to check.\n", arr[i], arr[i + 1], timeTaken);
    }

    timer.stop();
    System.out.printf("Total time taken to check all pairs: %d µs\n", timer.elapsedNanos() / 1000);
    return pairs;
}
