import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.InvalidKeyException;
import java.security.DigestException;

public static String getSHA1Hash(String url) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] messageDigest;

        if (url == null || url.isEmpty()) {
            throw new IllegalArgumentException("URL cannot be null or empty");
        }

        byte[] urlBytes = url.getBytes("UTF-8");
        messageDigest = md.digest(urlBytes);
        StringBuffer hexString = new StringBuffer();

        for (int i = 0; i < messageDigest.length; i++) {
            String hex = Integer.toHexString(0xff & messageDigest[i]);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    } catch (NoSuchAlgorithmException | UnsupportedEncodingException | InvalidKeyException | DigestException e) {
        throw new RuntimeException(e);
    }
}
