public class ConnectionHandler {
    private static final int PORT = 80;
    private static final String SERVER_ADDRESS = "localhost";

    private Socket socket;
    private SelectionKey selectionKey;
    private Selector selector;

    public void establishConnection() {
        try {
            socket = new Socket();
            socket.connect(new InetSocketAddress(SERVER_ADDRESS, PORT));

            selector = Selector.open();
            socket.setKeepAlive(true);
            socket.setTcpNoDelay(true);

            selectionKey = socket.register(selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);

            Executors.newSingleThreadExecutor().submit(() -> {
                try {
                    handleConnection();
                } catch (IOException e) {
                    System.err.println("Error handling connection: " + e.getMessage());
                } finally {
                    closeConnection();
                }
            });

            System.out.println("Connection established to " + SERVER_ADDRESS + ":" + PORT);
        } catch (IOException e) {
            System.err.println("Error establishing connection: " + e.getMessage());
        }
    }

    private void handleConnection() throws IOException {
        while (true) {
            selector.select();

            if (selectionKey.isReadable()) {
                handleRead();
            }

            if (selectionKey.isWritable()) {
