import java.security.SecureRandom;
import java.time.Instant;

public String generateTraceIdentifier() {
    SecureRandom random = new SecureRandom();
    byte[] randomBytes = new byte[16];
    random.nextBytes(randomBytes);
    String randomNumber = bytesToHex(randomBytes);

    Instant now = Instant.now();
    String timestamp = String.format("%016x", Long.toUnsignedLong(now.getEpochSecond()));

    return timestamp + randomNumber;
}

private String bytesToHex(byte[] bytes) {
    StringBuilder result = new StringBuilder();
    for (byte byteChar : bytes) {
        String hex = Integer.toHexString(0xff & (int) byteChar);
        if (hex.length() == 1) {
            result.append('0');
        }
        result.append(hex);
    }
    return result.toString();
}
