public class GeoPointChecker {

    public static void checkGeoPoints(Set<GeoPoint> set1, Set<GeoPoint> set2, double distanceTolerance) {
        Objects.requireNonNull(set1, "The first set of geo points cannot be null.");
        Objects.requireNonNull(set2, "The second set of geo points cannot be null.");
        Objects.requireNonNull(distanceTolerance, "The distance tolerance cannot be null.");

