        Iterator<GeoPoint> iterator2 = set2.iterator();

        SortedSet<GeoPoint> sortedSet1 = new TreeSet<>();
        SortedSet<GeoPoint> sortedSet2 = new TreeSet<>();

        while (iterator1.hasNext() && iterator2.hasNext()) {
            GeoPoint point1 = iterator1.next();
            GeoPoint point2 = iterator2.next();

            if (!point1.equals(point2)) {
                throw new IllegalArgumentException("The geo points in the first and second sets do not match.");
            }

            if (!areGeoPointsWithinDistance(point1, point2, distanceTolerance)) {
