        Collections.sort(sortedSet2);

        if (!sortedSet1.equals(sortedSet2)) {
            throw new IllegalArgumentException("The geo points in the first and second sets are not in the same order.");
        }
    }

    private static boolean areGeoPointsWithinDistance(GeoPoint point1, GeoPoint point2, double distanceTolerance) {
