import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public void savePulseToDatabase(Pulse pulse, int tableIndex) {
    Connection connection = null;
    PreparedStatement statement = null;

    try {
        connection = DatabaseConnection.getConnection();
        statement = connection.prepareStatement("INSERT INTO pulses(index, pulse_data) VALUES(?,?)");

        statement.setInt(1, tableIndex);
        Blob pulseDataBlob = connection.createBlob();
        pulseDataBlob.setBytes(1, pulse.getPulseData());
        statement.setBlob(2, pulseDataBlob);

        statement.executeUpdate();

    } catch (SQLException e) {
        System.err.println("Error saving pulse to database: " + e.getMessage());

    } finally {
        try {
            if (statement != null) statement.close();
            if (connection != null) connection.close();
        } catch (SQLException e) {
            System.err.println("Error closing database resources: " + e.getMessage());
        }
    }
}
