import java.util.Random;
import java.util.concurrent.ExecutorService;
import org.neo4j.graphdb.GraphDatabaseService;
import org.neo4j.graphdb.Node;
import org.neo4j.graphdb.RelationshipType;
import org.neo4j.graphdb.Transaction;

public class GraphDatabaseCreator {
    private final GraphDatabaseService db;
    private final ExecutorService executor;
    private final int iterationCount;

    public GraphDatabaseCreator(GraphDatabaseService db, ExecutorService executor, int iterationCount) {
        this.db = db;
        this.executor = executor;
        this.iterationCount = iterationCount;
    }

    public void createGraph() {
        new Thread(() -> {
            Random random = new Random();
            try (Transaction transaction = db.beginTx()) {
                for (int i = 0; i < iterationCount; i++) {
                    Node vertex1 = db.createNode();
                    Node vertex2 = db.createNode();

                    vertex1.setProperty("property1", random.nextInt(100));
                    vertex1.setProperty("property2", random.nextBoolean());

                    vertex2.setProperty("property1", random.nextInt(100));
                    vertex2.setProperty("property2", random.nextBoolean());

                    db.createRelationship(vertex1, RelationshipType.withName("RELATIONSHIP"), vertex2);

                    transaction.commit();
                }
            }
        }).start();

        executor.shutdown();
    }
}
