public class SensorDataGenerator {

    public List<SensorData> generateSensorData(List<LocationTime> locationTimes, List<Double> stdDeviations, double stepPerSecond) {
        List<SensorData> sensorDataList = new ArrayList<>();
        Random random = new Random();

        for (LocationTime locationTime : locationTimes) {
            double[] accelerometerReading = new double[3];
            for (int i = 0; i < 3; i++) {
                accelerometerReading[i] = random.nextGauss(0, stdDeviations.get(i));
            }
            sensorDataList.add(new SensorData(locationTime.getTime(), SensorType.ACC, acceleratorReading));
            if (locationTimes.size() > sensorDataList.size()) {
                double timeDifference = locationTimes.get(locationTimes.size() - 1).getTime() - locationTime.getTime();
                if (timeDifference < (1.0 / stepPerSecond)) {
                    throw new IllegalArgumentException("Location times are not evenly spaced, step per second value is too high.");
                }
            }
        }

        return sensorDataList;
    }

    public enum SensorType {
        ACC
    }

    public static class LocationTime {
        private final long time;

        public LocationTime(long time) {
            this.time = time;
        }

        public long getTime() {
            return time;
        }
    }

