import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import org.json.JSONObject;

public String getWeatherData(String location) {
    String apiKey = "YOUR_API_KEY";
    String url = "https://api.openweathermap.org/data/2.5/weather?q=" + location + "&appid=" + apiKey;

    OkHttpClient client = new OkHttpClient();
    Request request = new Request.Builder()
            .url(url)
            .build();

    try (Response response = client.newCall(request).execute()) {
        if (!response.isSuccessful()) {
            throw new RuntimeException("Failed : " + response.code());
        }

        String responseData = response.body().string();
        JSONObject jsonObject = new JSONObject(responseData);
        String weatherData = jsonObject.getJSONObject("main").getString("description");
        return weatherData;
    } catch (IOException | JSONException e) {
        e.printStackTrace();
        throw new RuntimeException("Error getting weather data: " + e.getMessage());
    }
}
