import java.net.*;

public class ProxyHttpRequest {
    private static final int PROXY_1_PORT = 8080;
    private static final int PROXY_2_PORT = 8081;
    private static final String PROXY_1_HOST = "proxy1.example.com";
    private static final String PROXY_2_HOST = "proxy2.example.com";
    private static final String TARGET_HOST = "target.example.com";

    public static void main(String[] args) {
        SocketAddress proxy1 = new InetSocketAddress(PROXY_1_HOST, PROXY_1_PORT);
        SocketAddress proxy2 = new InetSocketAddress(PROXY_2_HOST, PROXY_2_PORT);

        Proxy proxy = new Proxy(Proxy.Type.HTTP, proxy1);
        ProxySelector proxySelector = new ProxySelector() {
            @Override
            public List<Proxy> selectProxies(URI uri) {
                return Arrays.asList(proxy, proxy2);
            }
        };
        ProxySelector.setDefault(proxySelector);

        try (CloseableHttpClient httpClient = HttpClients.custom()
                .setDefaultProxy(proxy)
                .build()) {
            HttpGet request = new HttpGet(new URI("http://" + TARGET_HOST));
            try (CloseableHttpResponse response = httpClient.execute(request)) {
                int statusCode = response.getStatusLine().getStatusCode();
                if (statusCode >= 200 && statusCode < 300) {
                    System.out.println("Request to " + TARGET_HOST + " was successful.");
                } else {
                    System.out.println("Request to " + TARGET_HOST + " failed with status code " + statusCode);
                }
            }
        } catch (IOException e) {
            System.err.println("Error making HTTP request: " + e.getMessage());
        }
    }
}
