```java
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.CTRParamSpec;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Arrays;

public class AesEncryption {

    public static void main(String[] args) {
        String keyAlgorithm = "AES";
        int keySize = 128; // bytes
        String inputMessage = "This is a secret message to encrypt.";

        try {
            SecretKey key = KeyGenerator.getInstance(keyAlgorithm).generateKeySize(keySize);
            byte[] keyBytes = ((SecretKeySpec) key).getKey();

            Cipher cipher = Cipher.getInstance(keyAlgorithm);
            IvParameterSpec iv = new IvParameterSpec(new byte[cipher.getBlockSize()]);
            CTRParamSpec ctrSpec = new CTRParamSpec(iv);
            cipher.init(new SecretKeySpec(keyBytes, keyAlgorithm), ctrSpec);

            byte[] inputMessageBytes = inputMessage.getBytes(StandardCharsets.UTF_8);
            byte[] encryptedMessageBytes = new byte[cipher.getOutputSize(inputMessageBytes.length)];

            int encryptedMessageLength = cipher.doFinal(inputMessageBytes, 0, inputMessageBytes.length, encryptedMessageBytes, 0);

            System.out.println("Encrypted message in hexadecimal format: " + bytesToHex(encryptedMessageBytes, 0, encryptedMessageLength));

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String bytesToHex(byte[] bytes, int offset, int length) {
        StringBuilder result = new StringBuilder();
        for (int i = offset; i < offset + length; i++) {
            String hex = Integer.toHexString(0xff & bytes[i]);
            if (hex.length() == 1) {
                result.append('0');
            }
            result.append(hex);
        }
        return result.toString();
    }
}
