import java.io.*;
import sun.misc.Unsafe;

public class SerializedObject<T> {

    private static final Unsafe UNSAFE = getUnsafe();
    private static final int OBJECT_HEADER_SIZE = 4; // 4 bytes for object header

    public ByteArrayOutputStream serialize(T obj) throws IOException {
        if (obj == null) {
            throw new IllegalArgumentException("Input object cannot be null.");
        }

        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream);

        try {
            objectOutputStream.writeObject(obj);
        } catch (NotSerializableException e) {
            throw new RuntimeException("Input object is not serializable: " + e.getMessage());
        }

        objectOutputStream.close();
        return byteArrayOutputStream;
    }

    @SuppressWarnings("unchecked")
    public T deserialize(byte[] bytes) throws IOException, ClassNotFoundException {
        if (bytes == null || bytes.length < OBJECT_HEADER_SIZE) {
            throw new IllegalArgumentException("Input byte array is invalid.");
        }

        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(bytes);
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);

        try {
            return (T) objectInputStream.readObject();
        } catch (ClassCastException e) {
            throw new RuntimeException("Deserialized object is not of expected type: " + e.getMessage());
        } finally {
            objectInputStream.close();
        }
    }

    private static Unsafe getUnsafe() {
        try {
            return SunReflectAccess.getUnsafe();
        } catch (Exception e) {
            throw new RuntimeException("Failed to obtain Unsafe instance: " + e.getMessage());
        }
    }

    static final class SunReflectAccess {
        private static final Class<?> sunReflectClass;
        static {
            try {
                sunReflectClass = Class.forName("sun.misc.Unsafe");
            } catch (ClassNotFoundException e) {
                throw new Error("Failed to load sun.misc.Unsafe", e);
            }
        }

        private static Unsafe getUnsafe() {
            try {
                return (Unsafe) sunReflectClass.getDeclaredField("theUnsafe").get(null);
            } catch (IllegalAccessException | NoSuchFieldException e) {
                throw new Error("Failed to obtain Unsafe instance", e);
            }
        }
    }
}
