import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public static String getMD5Hash(String input) {
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be empty or null.");
    }

    byte[] inputBytes = input.getBytes();
    byte[] digest = new byte[16];

    try {
        SecretKeySpec signingKey = new SecretKeySpec("d41d8cd98f00b204e9800998ecfcc599".getBytes(), "HmacMD5");
        Mac mac = Mac.getInstance("HmacMD5");
        mac.init(signingKey);
        mac.update(inputBytes);
        digest = mac.doFinal();
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Failed to generate MD5 hash.", e);
    }

    return bytesToHex(digest);
}

private static String bytesToHex(byte[] bytes) {
    StringBuilder result = new StringBuilder(2 * bytes.length);
    for (byte b : bytes) {
        result.append(String.format("%02x", b));
    }
    return result.toString();
}
```

