import java.io.*;
import java.net.Socket;
import java.security.SecureRandom;

public class SecureObjectTransfer {
    private static final SecureRandom random = new SecureRandom();

    public static Object transferObject(Socket socket) throws IOException, ClassNotFoundException {
        ObjectInputStream input = null;
        ObjectOutputStream output = null;
        Object readObject = null;

        try {
            input = new ObjectInputStream(socket.getInputStream());
            readObject = input.readObject();

            String newName = "new_name";
            String newPassword = generateRandomPassword(16);

            if (readObject instanceof ModifiableObject) {
                ModifiableObject modifiableObject = (ModifiableObject) readObject;
                modifiableObject.setName(newName);
                modifiableObject.setPassword(newPassword);

                ObjectOutputStream secureOutput = new ObjectOutputStream(socket.getOutputStream());
                secureOutput.writeObject(modifiableObject);
                secureOutput.flush();
            }

            return readObject;
        } finally {
            if (input != null) {
                input.close();
            }
            if (output != null) {
                output.close();
            }
            socket.close();
        }
    }

    private static String generateRandomPassword(int length) {
        byte[] randomPassword = new byte[length];
        random.nextBytes(randomPassword);
        return new String(randomPassword);
    }

    interface ModifiableObject {
        void setName(String name);
        void setPassword(String password);
    }
}
