                byte[] message = "Hello, Server!".getBytes();
                int bytesWritten = 0;
                try {
                    while (bytesWritten < message.length) {
                        int numBytesWritten = socketChannel.write(ByteBuffer.wrap(message, bytesWritten, message.length - bytesWritten), null);
