public String getFileSHA1Hash(File file) {
    String hashValue = "";
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] fileData = new byte[(int) file.length()];
        int bytesRead = 0;
        FileInputStream fis = new FileInputStream(file);
        while (bytesRead < file.length()) {
            int numBytesRead = fis.read(fileData, bytesRead, file.length() - bytesRead);
            if (numBytesRead > 0) {
                bytesRead += numBytesRead;
            }
        }
        fis.close();
        md.update(fileData);
        byte[] digest = md.digest();
        hashValue = byteArrayToHexString(digest);
    } catch (FileNotFoundException e) {
        // Handle file not found exception
    } catch (IOException e) {
        // Handle I/O exception
    } catch (NoSuchAlgorithmException e) {
        // Handle no such algorithm exception
    }
    return hashValue;
}

private static String byteArrayToHexString(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for (byte b : bytes) {
        sb.append(String.format("%02x", b));
    }
    return sb.toString();
}
