                    logger.info("Connected to {}:{}", host, port);
                }

                @Override
                public void exceptionCaught(IoChannel ioChannel, Throwable cause) throws Exception {
                    logger.error("Error occurred: {}", cause.getMessage());
                    IoUtil.closeQuietly(ioChannel);
                }
            });

