            connector.setWriteTimeoutMillis(timeoutMillis);
            connector.setIdleTimeout(timeoutMillis);

            IoChannel ioChannel = connector.connect(host, port).sync().get();
            return new IoEventHandlerAdapter<>(ioChannel, filterAdapter);

