public InetSocketAddress getRemoteAddress(TcpIpConnection connection) {
    if (connection == null) {
        throw new NullPointerException("connection cannot be null");
    }

    Socket socket = connection.getSocket();
    if (socket == null) {
        throw new IllegalStateException("Socket not available");
    }

    SocketAddress remoteAddress = socket.getRemoteSocketAddress();
    if (remoteAddress instanceof InetSocketAddress) {
        return (InetSocketAddress) remoteAddress;
    } else {
        InetAddress inetAddress = InetAddress.getByAddress(remoteAddress.getAddress());
        return new InetSocketAddress(inetAddress, connection.getPort());
    }
}
