import java.text.MessageFormat;
import java.util.Locale;

public class ImageRotator {
    private static final String IMAGE_MAGICK_PATH = "/usr/bin/convert"; // Replace with the correct path to ImageMagick

    public static void main(String[] args) {
        if (args.length != 2) {
            System.err.println("Usage: java ImageRotator <image_path> <angle_degrees>");
            System.exit(1);
        }

        String imagePath = args[0];
        float angle = Float.parseFloat(args[1]);

        File inputFile = new File(imagePath);
        if (!inputFile.exists()) {
            System.err.println("Error: File not found: " + imagePath);
            System.exit(1);
        }

        Path tempFilePath = Files.createTempFile("rotated_", ".jpg");
        try {
            ProcessBuilder pb = new ProcessBuilder(IMAGE_MAGICK_PATH, "-rotate", String.valueOf((int) angle), imagePath, tempFilePath.toString());
            pb.redirectErrorStream(true);
            Process process = pb.start();
            int exitValue = process.waitFor().exitValue();
            if (exitValue != 0) {
                String errorMessage = readErrorStream(process);
                System.err.println("Error: Image processing failed. Error message: " + errorMessage);
                System.exit(exitValue);
            }

            File rotatedFile = new File(tempFilePath.toString());
            Desktop.open(rotatedFile);
        } catch (IOException | InterruptedException e) {
            String errorMessage = formatErrorMessage("Error: Image processing failed. Error details: {0}", e.getMessage());
            System.err.println(errorMessage);
            System.exit(1);
        } finally {
            Files.deleteIfExists(tempFilePath);
        }
    }

    private static String formatErrorMessage(String messageFormat, Object... args) {
        Locale locale = Locale.getDefault();
        MessageFormat messageFormatInstance = new MessageFormat(messageFormat, locale);
        return messageFormatInstance.format(args);
    }

    private static String readErrorStream(Process process) {
        return new String(process.getErrorStream().readAllBytes());
    }
}
