    public static List<String> getMacAddresses() {
        List<String> macAddresses = new ArrayList<>();
        try {
            List<NetworkInterface> networkInterfaces = ManagementFactory.getRuntimeMXBean().getOperatingSystemMXBean().getNetworkInterfaces();
