import org.apache.http.HttpEntity;
import org.apache.http.HttpHeaders;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.ContentType;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public class SecurePOSTRequest {

    public CloseableHttpResponse sendSecurePOSTRequest(String endpoint, String requestBody, String token, int maxRate, long delay, int limit) throws Exception {
        CloseableHttpClient httpClient = HttpClients.createDefault();
        HttpPost httpPost = new HttpPost(endpoint);

        // Set the request header with the token
        httpPost.setHeader(HttpHeaders.AUTHORIZATION, "Bearer " + token);

        // Set the request body and content type
        StringEntity entity = new StringEntity(requestBody);
        ContentType contentType = ContentType.APPLICATION_JSON;
        if (requestBody.startsWith("gzip ")) {
            contentType = ContentType.APPLICATION_GZIP;
            httpPost.setHeader(HttpHeaders.CONTENT_ENCODING, "gzip");
        }
        httpPost.setEntity(entity);
        httpPost.setHeader(HttpHeaders.CONTENT_TYPE, contentType.toString());

        // Set rate limiter if a maximum rate is specified
        if (maxRate > 0) {
            httpClient.getParams().setParameter("http.connection.timeout", delay);
            httpClient.getParams().setParameter("http.max-connections", limit);
        }

        // Execute the request and return the response
        CloseableHttpResponse response = httpClient.execute(httpPost);
        return response;
    }
}
