import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.channels.ServerSocketChannel;
import java.util.concurrent.Executors;

public class SecureServer {

    private static final int PORT = 8080;
    private static final String ADDRESS = "localhost";

    public static void main(String[] args) throws IOException {
        startServer();
    }

    public static void startServer() throws IOException {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        ServerSocket serverSocket = serverSocketChannel.socket();

        InetSocketAddress address = new InetSocketAddress(ADDRESS, PORT);
        serverSocket.bind(address, 10); // Set backlog to 10
        serverSocket.setReuseAddress(true);

        ExecutorService executor = Executors.newCachedThreadPool();
        serverSocket.setAcceptor((Socket socket) -> {
            try {
                Socket clientSocket = serverSocket.accept();
                executor.submit(() -> handleConnection(clientSocket));
            } catch (IOException e) {
                System.err.println("Error handling connection: " + e.getMessage());
            }
        });

        System.out.println("Server started on port " + PORT);

        try {
            serverSocket.listen(); // Wait until the ServerSocket is listening
        } catch (IOException e) {
            System.err.println("Error starting server: " + e.getMessage());
            throw new RuntimeException(e);
        }

        serverSocketChannel.close();
    }

    private static void handleConnection(Socket socket) {
        // Handle the connection here
        try {
            socket.close();
        } catch (IOException e) {
            System.err.println("Error closing connection: " + e.getMessage());
        }
    }
}
