import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static void generateMD5HashAndWriteToFile(String filePath) {
    MessageDigest md;
    try {
        md = MessageDigest.getInstance("MD5");
    } catch (NoSuchAlgorithmException e) {
        System.err.println("Error: MD5 algorithm not supported.");
        return;
    }

    byte[] fileData;
    try {
        File file = new File(filePath);
        byte[] buffer = new byte[1024];
        int bytesRead;
        FileInputStream fis = new FileInputStream(file);

        // Read the file
        while ((bytesRead = fis.read(buffer)) != -1) {
            md.update(buffer, 0, bytesRead);
        }
        fis.close();

        fileData = md.digest();
    } catch (IOException e) {
        System.err.println("Error: Unable to read file: " + filePath);
        return;
    }

    String hash = bytesToHex(fileData);

    // Write the hash to a new file with '.md5' extension
    String outputFileName = filePath + ".md5";
    try (FileOutputStream fos = new FileOutputStream(new File(outputFileName))) {
        fos.write(hash.getBytes());
    } catch (IOException e) {
        System.err.println("Error: Unable to write hash to file: " + outputFileName);
        return;
    }

    System.out.println("MD5 hash generation completed for file: " + filePath);
    System.out.println("MD5 hash: " + hash);
}

private static String bytesToHex(byte[] bytes) {
    StringBuilder result = new StringBuilder();
    for (byte b : bytes) {
        result.append(String.format("%02x", b));
    }
    return result.toString();
}
