import java.net.InetSocketAddress;
import java.net.Socket;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;

public class SecureSocketCommunication {

    private static final String HOST;
    private static final int PORT;
    private static final int BUFFER_SIZE;
    private static final int KEEPALIVE_INTERVAL;
    private static final int MAX_RETRIES;

    static {
        HOST = "example.com";
        PORT = 80;
        BUFFER_SIZE = 1024;
        KEEPALIVE_INTERVAL = 60;
        MAX_RETRIES = 5;
    }

    public static void sendMessage(String message) throws IOException {
        Socket socket = null;
        try {
            socket = new Socket();
            socket.connect(new InetSocketAddress(HOST, PORT), KEEPALIVE_INTERVAL);
            socket.setKeepAlive(true);
            socket.setSoTimeout(KEEPALIVE_INTERVAL);

            ByteBuffer buffer = ByteBuffer.allocate(BUFFER_SIZE);
            buffer.put(message.getBytes(StandardCharsets.UTF_8));
            buffer.flip();

            int bytesSent = 0;
            int retries = 0;
            while (bytesSent < buffer.limit()) {
                try {
                    int bytesToSend = Math.min(BUFFER_SIZE, BUFFER_SIZE - bytesSent);
                    socket.getOutputStream().write(buffer.array(), bytesSent, bytesToSend);
                    bytesSent += bytesToSend;
                    buffer.compact();
                } catch (IOException e) {
                    if (retries < MAX_RETRIES) {
                        try {
                            socket.close();
                            socket = new Socket();
                            socket.connect(new InetSocketAddress(HOST, PORT), KEEPALIVE_INTERVAL);
                            socket.setKeepAlive(true);
                            socket.setSoTimeout(KEEPALIVE_INTERVAL);
                        } catch (IOException ex) {
                            throw new IOException("Failed to connect to the server.", ex);
                        }
                        retries++;
                    } else {
                        throw new IOException("Failed to send message after multiple retries.");
                    }
                }
            }

            // Handle flush requests by re-sending the message buffer
            int numRetries = 0;
            while (numRetries < MAX_RETRIES) {
                try {
                    byte[] response = new byte[BUFFER_SIZE];
                    int bytesReceived = socket.getInputStream().read(response, 0, BUFFER_SIZE);
                    String responseMessage = new String(response, 0, bytesReceived, StandardCharsets.UTF_8);
                    if (responseMessage.startsWith("FLUSH")) {
                        sendMessage(message);
                    }
                    break;
                } catch (IOException e) {
                    numRetries++;
                }
            }

            socket.close();
        } finally {
            if (socket != null) {
                socket.close();
            }
        }
    }
}
