public class SecureSocketConnection {

    private static final int DEFAULT_TIMEOUT = 5000; // milliseconds

    public static Socket createSocketConnection(String host, int port, boolean useSSL) throws IOException {
        Socket socket;
        if (useSSL) {
            try {
                SSLContext sslContext = SSLContext.getInstance("TLSv1.2");
