import java.io.IOException;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.net.UnknownHostException;
import java.nio.channels.DatagramChannel;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;

public class DatagramConnector {
    private static final int DEFAULT_PORT = 1234;
    private static final int DEFAULT_THREAD_POOL_SIZE = 10;

    public DatagramConnector(String uri) throws IllegalArgumentException {
        String[] parts = uri.split(":");
        if (parts.length != 2 || parts[1] == null) {
            throw new IllegalArgumentException("Invalid URI format: " + uri);
        }

        int port;
        try {
            port = Integer.parseInt(parts[1]);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Invalid port number: " + parts[1]);
        }

        if (parts.length > 2 && "true".equalsIgnoreCase(parts[2])) {
            throw new IllegalArgumentException("Transfer exchange is not supported");
        }

        DatagramSocket socket = null;
        try {
            socket = new DatagramSocket(port);
            socket.setBroadcast(false);
            socket.setReuseAddress(true);
        } catch (IOException e) {
            closeQuietly(socket);
            throw new IllegalArgumentException("Failed to create socket: " + e.getMessage());
        }

        InetAddress address;
        try {
            address = InetAddress.getByName(parts[0]);
        } catch (UnknownHostException e) {
            closeQuietly(socket);
            throw new IllegalArgumentException("Failed to resolve address: " + e.getMessage());
        }

        DatagramChannel channel = null;
        try {
            channel = DatagramChannel.open();
            channel.configureBlocking(false);
            channel.socket().bind(new InetSocketAddress(address, port));
        } catch (IOException e) {
            closeQuietly(socket, channel);
            throw new IllegalArgumentException("Failed to create channel: " + e.getMessage());
        }

        ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(DEFAULT_THREAD_POOL_SIZE);

        this.socket = socket;
        this.channel = channel;
        this.address = address;
        this.port = port;
        this.executor = executor;
    }

    private void closeQuietly(Closeable... resources) {
        for (Closeable resource : resources) {
            if (resource != null) {
                try {
                    resource.close();
                } catch (IOException e) {
                    // Ignore
                }
            }
        }
    }

    private DatagramSocket socket;
    private DatagramChannel channel;
    private InetAddress address;
    private int port;
    private ThreadPoolExecutor executor;
}
