        String authType = "KRB5";
        String serviceName = "HTTP";
        byte[] serviceKeytab = Hex.decode(KerberosUtil.KRB5_HTTP_SERVICE_KEYTAB);
        socket.getOutputStream().write(authType.getBytes());
        socket.getOutputStream().write(Integer.BYTES, 1, 2); // Length of the authentication data
        socket.getOutputStream().write(serviceName.getBytes());
        socket.getOutputStream().write(Integer.BYTES, 0, 2); // Length of the ticket
        socket.getOutputStream().write(ticketBytes, 0, ticketBytes.length);

        // Connect to the remote server
        try {
            socket.connect(new InetSocketAddress(hostname, port));
        } catch (IOException e) {
            if (socket.isConnected()) {
                LOGGER.error("Failed to connect to remote server", e);
                socket.close();
            }
            throw e;
        }

        return socket;
    }

    private static boolean isValidLocalAddress(String hostname) {
        try {
            InetAddress.getByName(hostname);
            return true;
        } catch (UnknownHostException e) {
            return false;
        }
    }
