import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.lang.reflect.InvocationTargetException;
import java.util.Arrays;
import java.util.concurrent.TimeUnit;

public class SecureProcessExecutor {

    private static final String LOGGER = "SecureProcessExecutor";

    public static boolean executeCommand(String command, String[] args, String workingDirectory, Map<String, String> envVariables) {
        ProcessBuilder processBuilder = new ProcessBuilder(command, args);
        processBuilder.directory(new File(workingDirectory));

        if (envVariables != null) {
            processBuilder.environment().putAll(envVariables);
        }

        try {
            Process process = processBuilder.start();
            PrintStream errStream = new PrintStream(process.errorStream());
            PrintStream outStream = new PrintStream(process.outputStream());

            // Log execution details
            logExecutionDetails(command, args, workingDirectory, envVariables);

            // Monitor process status using a Watchdog thread
            Thread watchdogThread = new Thread(() -> {
                try {
                    process.waitFor(30, TimeUnit.SECONDS);
                    if (process.exitValue() != 0) {
                        logError("Command execution failed with exit code: " + process.exitValue());
                    }
                } catch (InterruptedException | IOException e) {
                    logError("Error monitoring command execution: " + e.getMessage());
                } finally {
                    process.destroy();
                }
            });
            watchdogThread.start();

            // Read process output and error streams
            BufferedReader input = new BufferedReader(new InputStreamReader(process.inputStream()));
            String line;
            while ((line = input.readLine()) != null) {
                outStream.println(line);
            }
            input.close();

            // Wait for the process to finish
            process.waitFor();

            // Log process exit status
            if (process.exitValue() == 0) {
                logInfo("Command execution successful.");
                return true;
            } else {
                logError("Command execution failed with exit code: " + process.exitValue());
                return false;
            }
        } catch (IOException | InstantiationException | IllegalAccessException | InvocationTargetException | NoSuchMethodException | SecurityException e) {
            logError("Error executing command: " + e.getMessage());
            return false;
        }
    }

    private static void logExecutionDetails(String command, String[] args, String workingDirectory, Map<String, String> envVariables) {
        logInfo("Executing command: " + command + " " + Arrays.toString(args));
        logInfo("Working directory: " + workingDirectory);
        logInfo("Environment variables: " + envVariables);
    }

    private static void logInfo(String message) {
        System.out.println(LOGGER + ": " + message);
    }

    private static void logError(String message) {
        System.err.println(LOGGER + ": " + message);
    }
}
