import java.io.IOException;
import java.nio.file.Files;
import java.security.KeyStore;
import java.security.KeyStoreException;
import java.security.NoSuchAlgorithmException;
import java.security.SignatureException;
import java.security.UnrecoverableKeyException;
import java.security.cert.CertificateException;
import javax.security.auth.x500.X500Principal;

public class FileSigner {

    private static final String JKS_FILE = "keystore.jks";
    private static final String JKS_PASSWORD = "password"; // Change this to your desired password

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java FileSigner <file_path>");
            return;
        }

        String filePath = args[0];
        File inputFile = new File(filePath);

        if (!inputFile.exists()) {
            System.err.println("File does not exist: " + filePath);
            return;
        }

        try {
            signFile(inputFile);
            System.out.println("File signed successfully.");
        } catch (Exception e) {
            System.err.println("Error signing file: " + e.getMessage());
        }
    }

    private static void signFile(File file) throws IOException, NoSuchAlgorithmException, CertificateException,
            UnrecoverableKeyException, KeyStoreException, SignatureException {
        KeyStore keyStore = KeyStore.getInstance("JKS");
        keyStore.load(Files.newInputStream(new File(JKS_FILE).toPath()), JKS_PASSWORD.toCharArray());

        X500Principal signerPrincipal = (X500Principal) keyStore.getCertificate("alias").getSubjectX500Principal();

        java.security.PrivateKey privateKey = (java.security.PrivateKey) keyStore.getKey("alias", JKS_PASSWORD.toCharArray());

        java.security.MessageDigest messageDigest = java.security.MessageDigest.getInstance("SHA256");
        byte[] fileBytes = Files.readAllBytes(file.toPath());
        messageDigest.update(fileBytes);
        byte[] fileDigest = messageDigest.digest();

        java.security.Signature signature = java.security.Signature.getInstance("SHA256withRSA");
        signature.initSign(privateKey);
        signature.update(fileDigest);

        byte[] signatureBytes = signature.sign();

        File signedFile = new File(file.getPath() + ".signed");
        Files.write(signedFile.toPath(), signatureBytes);

        System.out.println("File signed with the following signature:\n" + new String(signatureBytes, "UTF-8") + "\n");
    }
}
