import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.util.Random;

public class SerializationPerformance implements Serializable {
    private static final Log LOG = LogFactory.getLog(SerializationPerformance.class);
    private static final int NUM_SERIALIZATIONS = 500;
    private static final int BUFFER_SIZE = 1024;

    public static void main(String[] args) throws IOException {
        Random random = new Random();
        SerializationPerformance performance = new SerializationPerformance();
        long totalTime = 0;
        long totalSize = 0;

        for (int i = 0; i < NUM_SERIALIZATIONS; i++) {
            long startTime = System.currentTimeMillis();
            byte[] serializedData = serialize(performance);
            long endTime = System.currentTimeMillis();
            long size = serializedData.length;
            totalTime += (endTime - startTime);
            totalSize += size;
            if (i % 100 == 0) {
                LOG.info("Serialization " + (i + 1) + " of " + NUM_SERIALIZATIONS + " completed. Time taken: " + (endTime - startTime) + "ms, Size: " + size + " bytes.");
