        }

        double averageTimePerSerialization = (double) totalTime / NUM_SERIALIZATIONS;
        double averageSizePerSerialization = (double) totalSize / NUM_SERIALIZATIONS;

        LOG.info("Average time taken per serialization: " + averageTimePerSerialization + "ms.");
        LOG.info("Average size of serialized data per serialization: " + averageSizePerSerialization + " bytes.");
    }

