import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public static byte[] sha1Hash(String input) {
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input cannot be empty or null.");
    }

    try {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] inputBytes = input.getBytes();
        md.update(inputBytes);
        byte[] digest = md.digest();
        return digest;
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException("SHA-1 algorithm not supported.", e);
    }
}

public static String sha1HashToString(String input) {
    byte[] hash = sha1Hash(input);
    return bytesToHex(hash);
}

private static String bytesToHex(byte[] bytes) {
    StringBuilder result = new StringBuilder();
    for (byte b : bytes) {
        result.append(String.format("%02x", b));
    }
    return result.toString();
}
