import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.concurrent.TimeUnit;

public String executeCommand(String command, int timeoutMillis) {
    Process process;
    try {
        process = Runtime.getRuntime().exec(command.split(System.getProperty("path.separator")));
    } catch (Exception e) {
        throw new RuntimeException("Failed to execute command: " + command, e);
    }

    StringBuilder output = new StringBuilder();
    BufferedReader reader = null;

    try {
        reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        process.waitFor(timeoutMillis, TimeUnit.MILLISECONDS);
    } catch (Exception e) {
        if (reader != null) {
            try {
                reader.close();
            } catch (IOException ex) {
                // Log or handle the exception
            }
        }
        throw new RuntimeException("Command execution failed: " + command, e);
    } finally {
        try {
            reader.close();
        } catch (IOException e) {
            // Log or handle the exception
        }
    }

    return output.toString();
}
