import org.xml.sax.Attributes;
import org.xml.sax.SAXException;
import org.xml.sax.helpers.DefaultHandler;

import java.io.File;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class SafePrefixExtractor {
    public static void main(String[] args) {
        Map<String, Integer> prefixFrequencies = new HashMap<>();

        try {
            for (String filePath : args) {
                File file = new File(filePath);
                if (!file.exists() || !file.isFile()) {
                    System.err.println("Invalid file path: " + filePath);
                    continue;
                }

                XMLInputFactory inputFactory = XMLInputFactory.newInstance();
                inputFactory.setProperty("javax.xml.stream.isReplacingEntityReferences", "false");
                inputFactory.setProperty("javax.xml.stream.isValidating", "false");

                SAXParserFactory parserFactory = new SAXParserFactory();
                parserFactory.setNamespaceAware(true);
                parserFactory.setFeature("http://xml.org/sax/features/namespaces", true);

                SAXParser parser = parserFactory.newSAXParser();
                FrequencyHandler handler = new FrequencyHandler(prefixFrequencies);
                parser.parse(inputFactory.createXMLInput(file), handler);
            }

            for (Map.Entry<String, Integer> entry : prefixFrequencies.entrySet()) {
                System.out.println(entry.getKey() + ": " + entry.getValue());
            }
        } catch (SAXException | IOException e) {
            e.printStackTrace();
        }
    }

    static class FrequencyHandler extends DefaultHandler {
        private Map<String, Integer> prefixFrequencies;

        public FrequencyHandler(Map<String, Integer> prefixFrequencies) {
            this.prefixFrequencies = prefixFrequencies;
        }

        @Override
        public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
            String prefix = "";
            if (attributes != null) {
                for (int i = 0; i < attributes.getLength(); i++) {
                    String attrName = attributes.getLocalName(i);
                    if (attrName.startsWith("xmlns:")) {
                        prefix = attrName.substring(6);
                        break;
                    }
                }
            }
            if (!prefix.isEmpty()) {
                prefixFrequencies.put(prefix, prefixFrequencies.getOrDefault(prefix, 0) + 1);
            }
        }
    }
}
