public class SingletonInstanceManager {
    private static final String FILENAME = "singleton.file";
    private static volatile SingletonInstanceManager instance;
    private static final XStream xstream = new XStream();
    static {
        xstream.setMode(XStream.NO_AUTOSAVING);
        xstream.processAnnotations(SingletonInstance.class);
    }

    private SingletonInstance instance;

    private SingletonInstanceManager() {
