```java
import org.json.JSONObject;

import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class UserInputSender {

    private static final String SERVER_URL = "http://example.com/api";

    public static void sendUserInputToServer(HttpURLConnection client) throws IOException {
        Map<String, String> userInput = new HashMap<>();
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter key-value pairs (type \"done\" when finished):");
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            if (line.equalsIgnoreCase("done")) {
                break;
            }
            String[] parts = line.split("=");
            if (parts.length == 2) {
                userInput.put(parts[0], parts[1]);
            }
        }
        scanner.close();

        JSONObject jsonObject = new JSONObject(userInput);
        String jsonString = jsonObject.toString();

        client.setRequestMethod("POST");
        client.setRequestProperty("Content-Type", "application/json");
        client.setDoOutput(true);

        OutputStream os = client.getOutputStream();
        os.write(jsonString.getBytes());
        os.flush();
        os.close();

        int responseCode = client.getResponseCode();
        if (responseCode >= 400) {
            throw new IOException("Error: Server returned response code " + responseCode);
        }

        System.out.println("User input sent to server.");
    }
}
```

