```java
import java.math.BigInteger;
import java.security.KeyFactory;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.spec.PKCS8EncodedKeySpec;
import java.security.spec.X509EncodedKeySpec;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.spec.OAEPParameterSpec;
import javax.crypto.spec.SecretKeySpec;

public static String encryptRSA(String input, String publicKeyBase64) {
    try {
        // Decode the public key from Base64
        byte[] publicKeyBytes = decodeBase64(publicKeyBase64);
        X509EncodedKeySpec publicKeySpec = new X509EncodedKeySpec(publicKeyBytes);
        KeyFactory keyFactory = KeyFactory.getInstance("RSA");
        PublicKey publicKey = keyFactory.generatePublic(publicKeySpec);

        // Initialize the RSA cipher
        Cipher cipher = Cipher.getInstance("RSA/ECB/PKCS1Padding");
        cipher.init(Cipher.ENCRYPT_MODE, publicKey);

        // Encrypt the input string
        byte[] inputBytes = input.getBytes();
        byte[] encryptedBytes = cipher.doFinal(inputBytes);

        // Encode the encrypted bytes to Base64
        String encryptedBase64 = encodeBytesToBase64String(encryptedBytes);

        return encryptedBase64;
    } catch (Exception e) {
        throw new RuntimeException("Failed to encrypt string: " + e.getMessage(), e);
    }
}

private static byte[] decodeBase64(String base64Encoded) {
    byte[] decodedBytes = Base64.getDecoder().decode(base64Encoded);
    return decodedBytes;
}

private static byte[] encodeBytesToBase64String(byte[] bytes) {
    return Base64.getEncoder().encode(bytes);
}
