import java.io.*;

public class SecureSerialization {

    public static <T> T secureSerializeAndDeserialize(Object parent, Object objToSerialize) throws IOException, ClassNotFoundException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        ObjectOutputStream objOutputStream = new ObjectOutputStream(byteStream);

        try {
            objOutputStream.writeObject(objToSerialize);
            objOutputStream.flush();
            byteStream.reset();

            ObjectInputStream objInputStream = new ObjectInputStream(new ByteArrayInputStream(byteStream.toByteArray()));
            T deserializedObj = (T) objInputStream.readObject();
            return deserializedObj;
        } catch (IOException e) {
            if (objOutputStream != null) {
                objOutputStream.close();
            }
            throw e;
        } catch (ClassNotFoundException e) {
            if (objInputStream != null) {
                objInputStream.close();
            }
            throw e;
        } finally {
            if (objOutputStream != null) {
                objOutputStream.close();
            }
            if (objInputStream != null) {
                objInputStream.close();
            }
        }
    }
}
