import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Base64;

public class EncryptionUtil {

    private static final String ALGORITHM = "Blowfish";
    private static final int KEY_LENGTH = 8 * 8; // 64-bit key

    public static String encrypt(String plaintext, String key) {
        if (plaintext == null || plaintext.isEmpty()) {
            throw new IllegalArgumentException("Plaintext cannot be empty or null.");
        }
        if (key == null || key.isEmpty()) {
            throw new IllegalArgumentException("Key cannot be empty or null.");
        }

        SecretKey secretKey = generateKey(key);
        byte[] encryptedBytes = encryptData(plaintext.getBytes(StandardCharsets.UTF_8), secretKey, generateIV());

        return Base64.getEncoder().encodeToString(encryptedBytes);
    }

    private static SecretKey generateKey(String key) {
        try {
            KeyGenerator keyGen = KeyGenerator.getInstance(ALGORITHM);
            keyGen.init(KEY_LENGTH);
            SecretKey secretKey = keyGen.generateKey();
            if (secretKey instanceof SecretKeySpec) {
                byte[] keyBytes = ((SecretKeySpec) secretKey).getKey();
                if (Arrays.equals(keyBytes, key.getBytes(StandardCharsets.UTF_8))) {
                    return secretKey;
                }
            }
            throw new IllegalArgumentException("Key does not match the generated key.");
        } catch (NoSuchAlgorithmException | SecureRandom.ProviderNotFoundException e) {
            throw new RuntimeException("Error generating key.", e);
        }
    }

    private static byte[] encryptData(byte[] data, SecretKey secretKey, byte[] iv) {
        try {
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, secretKey, new IvParameterSpec(iv));
            byte[] encryptedData = cipher.doFinal(data);
            return encryptedData;
        } catch (Exception e) {
            throw new RuntimeException("Error encrypting data.", e);
        }
    }

    private static byte[] generateIV() {
        SecureRandom random = new SecureRandom();
        byte[] iv = new byte[8 * 8]; // 64-bit IV
        random.nextBytes(iv);
        return iv;
    }
}
