import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.Optional;
import java.util.concurrent.TimeUnit;

public int executeCommand(String[] commands, InputStream input, OutputStream output, Optional<Long> timeout) {
    ProcessBuilder processBuilder = new ProcessBuilder();
    Process process;
    try {
        processBuilder.command(commands);
        process = processBuilder.start();

        if (input != null) {
            InputStream errStream = process.getErrorStream();
            InputStreamReader errReader = new InputStreamReader(errStream);
            BufferedReader errBufferedReader = new BufferedReader(errReader);
            Thread errorThread = new Thread(() -> {
                try {
                    String line;
                    while ((line = errBufferedReader.readLine()) != null) {
                        System.out.println("Error: " + line);
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            });
            errorThread.start();
            process.errStream = new PrintStream(new BufferedOutputStream(output), true);
            process.inputStream = input;
        }

        if (timeout.isPresent()) {
            boolean exitVal = process.waitFor(timeout.get(), TimeUnit.MILLISECONDS);
            if (!exitVal) {
                process.destroyForcibly();
                throw new RuntimeException("Process did not finish within the given timeout.");
            }
        } else {
            process.waitFor();
        }

        return process.exitValue();
    } catch (IOException | InterruptedException e) {
        e.printStackTrace();
        throw new RuntimeException("An error occurred while executing the command.", e);
    }
}
