import javax.xml.XMLConstants;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathFactory;

public String evaluateXPathExpression(String responseValue) {
    if (responseValue == null) {
        throw new IllegalArgumentException();
    }

    try {
        // Validate the XML response
        SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
        Schema schema = schemaFactory.newSchema(new StreamSource(getClass().getResource("/xsd/response.xsd")));

        // Parse the XML response
        javax.xml.parsers.DocumentBuilderFactory factory = javax.xml.parsers.DocumentBuilderFactory.newInstance();
        factory.setSchema(schema);
        javax.xml.parsers.DocumentBuilder builder = factory.newDocumentBuilder();
        javax.xml.parsers.Document doc = builder.parse(new InputSource(new StringReader(responseValue)));

        // Evaluate the XPath expression
        XPathFactory xPathfactory = XPathFactory.newInstance();
        XPath xpath = xPathfactory.newXPath();
        xpath.setNamespaceContext(new MyNamespaceContext()); // Define namespaces if necessary
        Object result = xpath.compile("/response/success").evaluate(doc, XPathConstants.BOOLEAN);

        if (result == Boolean.TRUE) {
            return null;
        } else {
            String message = String.format("/response/failure/message[1]/text()", "");
            Object xpathResult = xpath.compile(message).evaluate(doc, XPathConstants.STRING);
            return xpathResult.toString();
        }
    } catch (Exception e) {
        throw new RuntimeException("Error evaluating XPath expression", e);
    }
}

class MyNamespaceContext extends org.apache.xpath.resolver.NamespaceContext {
    @Override
    public String getNamespaceURI(String prefix) {
        if (prefix.equals("xsi")) {
            return "http://www.w3.org/2001/XMLSchema-instance";
        }
        return super.getNamespaceURI(prefix);
    }
}
