public class KeyboardInputSimulator {

    private static final String XDOTOOL_EXEC = "xdg-open"; // Replace with the path to xdotool if not on a Debian-based system

    public static void simulateKeyboardInput(int[] keys) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder(XDOTOOL_EXEC, "--key-file=/tmp/key_file.txt");
        File tempFile = new File("/tmp/key_file.txt");

        try (PrintWriter writer = new PrintWriter(tempFile)) {
