public static void compileDeviceTreeOverlay(String objectFilePath, String overlayFilePath, Map<String, String> environmentVariables) throws IOException, InterruptedException {
    File objectFile = new File(objectFilePath);
    File overlayFile = new File(overlayFilePath);

    if (!objectFile.exists() || !overlayFile.exists()) {
        throw new IOException("Object file or overlay file does not exist.");
    }

    String compilerCommand = "dtc -I %s -O %s %s %s";
