    processBuilder.redirectErrorStream(true);
    Map<String, String> newEnvironmentVariables = new HashMap<>(environmentVariables);
    processBuilder.environment().putAll(newEnvironmentVariables);

    Process process = processBuilder.start();

    BufferedReader reader = new BufferedReader(new FileReader(new File("compilation.log")));
    String line;
    while ((line = reader.readLine()) != null) {
        if (line.contains("Error")) {
            String errorMessage = line;
            reader.close();
            process.destroy();
            throw new CompilationException("Compilation failed with error: " + errorMessage);
