import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Objects;
import java.util.ProcessBuilder;

public class QueryGenerator {

    private static final String TOOL_NAME = "queryGenerator";
    private static final String TEMPLATE_PATH = "/path/to/templates";

    public String generateQuery(String templateName, List<String> queryParams) {
        String templateFilePath = TEMPLATE_PATH + "/" + templateName;

        ProcessBuilder processBuilder = new ProcessBuilder(TOOL_NAME);
        processBuilder.redirectErrorStream(true);

        processBuilder.environment().put("TEMPLATE_PATH", TEMPLATE_PATH);
        processBuilder.environment().put("TEMPLATE_FILE", templateName);

        processBuilder.command().addAll(List.of("/usr/bin/env", "LC_ALL=C", TOOL_NAME));
        processBuilder.command().add(new File(TEMPLATE_PATH, templateName));
        processBuilder.command().addAll(queryParams);

        try {
            Process process = processBuilder.start();
            String queryOutput = readProcessOutput(process);
            process.waitFor();

            if (process.exitValue() != 0) {
                throw new RuntimeException("Query generation failed with exit code " + process.exitValue());
            }

            return queryOutput;
        } catch (InterruptedException | IOException e) {
            throw new RuntimeException("Error while generating query: " + e.getMessage(), e);
        }
    }

    private String readProcessOutput(Process process) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
            StringBuilder output = new StringBuilder();
            String line;

            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            return output.toString();
        }
    }
}
