import org.apache.commons.lang3.StringUtils;

public void printContextParameters(Map<String, Object> context) {
    if (context == null) {
        throw new IllegalArgumentException("Context cannot be null");
    }

    for (Map.Entry<String, Object> entry : context.entrySet()) {
        String parameterName = entry.getKey();
        Object parameterValue = entry.getValue();

        if (parameterName == null || StringUtils.isEmpty(parameterName)) {
            throw new IllegalArgumentException("Parameter name cannot be null or empty");
        }

        if (parameterValue == null) {
            System.out.println(parameterName + ": null");
            continue;
        }

        // Ensure safe handling of different data types
        if (parameterValue instanceof String) {
            System.out.println(parameterName + ": " + String.valueOf(parameterValue));
        } else if (parameterValue instanceof Number) {
            Number numberValue = (Number) parameterValue;
            System.out.println(parameterName + ": " + numberValue.toString());
        } else if (parameterValue instanceof Boolean) {
            Boolean booleanValue = (Boolean) parameterValue;
            System.out.println(parameterName + ": " + booleanValue.toString());
