import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Filter implements FilterInterface {
    private int frequency;
    private byte[] inputData;

    public MD5Filter(int frequency) {
        this.frequency = frequency;
    }

    @Override
    public byte[] filter(byte[] input) {
        inputData = input;
        byte[] md5Hash;

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(inputData);
            md5Hash = md.digest();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not supported", e);
        }

        if (calculateFrequency(md5Hash) <= frequency) {
            return md5Hash;
        } else {
            throw new FilterException("Input data frequency exceeds limit");
        }
    }

    private int calculateFrequency(byte[] md5Hash) {
        byte[] hashBytes = new byte[16];
        System.arraycopy(md5Hash, 0, hashBytes, 0, 16);
        BigInteger hashValue = new BigInteger(1, hashBytes);
        return hashValue.intValue();
    }
}
