public class FileOpener {

    private static final String WINDOWS_COMMAND = "cmd /c start ";
    private static final String MAC_COMMAND = "open ";
    private static final String LINUX_COMMAND = "xdg-open ";

    public static void openFileOrDirectory(String selection) {
        File fileOrDirectory = new File(selection);
        if (!fileOrDirectory.exists()) {
            System.out.println("Error: The specified file or directory does not exist.");
            return;
        }

        Path path;
        try {
            path = Paths.get(selection);
        } catch (IOException e) {
            System.out.println("Error: An issue occurred while processing the selection: " + e.getMessage());
            return;
        }

        String os = System.getProperty("os.name").toLowerCase();
        String command;
        if (os.contains("windows")) {
            command = WINDOWS_COMMAND + selection;
        } else if (os.contains("mac")) {
            command = MAC_COMMAND + selection;
        } else if (os.contains("linux")) {
            command = LINUX_COMMAND + selection;
        } else {
            System.out.println("Error: Unsupported operating system.");
            return;
        }

        ProcessBuilder pb;
        try {
            pb = new ProcessBuilder(command);
        } catch (IOException e) {
            System.out.println("Error: An issue occurred while building the process: " + e.getMessage());
            return;
        }

        Process process;
        try {
            process = pb.start();
        } catch (IOException e) {
            System.out.println("Error: An issue occurred while starting the process: " + e.getMessage());
            return;
        }

        int exitValue;
        try {
            exitValue = process.waitFor().exitValue();
        } catch (InterruptedException e) {
            System.out.println("Error: The process was interrupted: " + e.getMessage());
            return;
        }

        if (exitValue != 0) {
            System.out.println("Error: The system command execution failed with exit code: " + exitValue);
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java FileOpener <selection>");
            return;
        }

        openFileOrDirectory(args[0]);
    }
}
