import java.security.NoSuchAlgorithmException;

public static String getMd5Hash(String filePath) {
    try {
        File file = new File(filePath);
        MessageDigest md = MessageDigest.getInstance("MD5");

        byte[] fileData = new byte[(int) file.length()];
        byte[] hashValue = new byte[16]; // MD5 hash length is 128 bits or 16 bytes

        if (!file.exists() || !file.isFile()) {
            throw new IllegalArgumentException("Invalid file path: " + filePath);
        }

        // Read file content in chunks
        int bytesRead = 0;
        FileInputStream inputStream = new FileInputStream(file);
        while (bytesRead < file.length()) {
            int numBytesToRead = (int) Math.min(file.length() - bytesRead, 8192);
            byte[] buffer = new byte[numBytesToRead];
            int numBytesRead = inputStream.read(buffer);
            if (numBytesRead < 0) {
                throw new IOException("Error reading file: " + filePath);
            }
            md.update(buffer);
            bytesRead += numBytesRead;
        }
        inputStream.close();

        // Get the hash value
        hashValue = md.digest();

        // Convert the hash value to a hexadecimal string
        StringBuilder sb = new StringBuilder();
        for (byte b : hashValue) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    } catch (NoSuchAlgorithmException | IOException e) {
        throw new RuntimeException("Error computing MD5 hash: " + e.getMessage(), e);
    }
}
