import java.io.File;
import java.nio.file.Files;
import java.security.MessageDigest;

public String calculateMd5Hash(String filePath) {
    if (filePath == null || filePath.isEmpty()) {
        throw new IllegalArgumentException("File path cannot be empty or null.");
    }

    File file = new File(filePath);
    if (!file.exists() || !file.isFile()) {
        throw new FileNotFoundException("File not found or is not a regular file.");
    }

    byte[] fileContent;
    try {
        fileContent = Files.readAllBytes(file.toPath());
    } catch (Exception e) {
        throw new RuntimeException("Error reading file.", e);
    }

    MessageDigest md = MessageDigest.getInstance("MD5");
    byte[] hash = md.digest(fileContent);

    StringBuilder hexString = new StringBuilder(2 * hash.length);
    for (byte b : hash) {
        hexString.append(String.format("%02x", b));
    }

    return hexString.toString();
}
