import java.io.*;
import java.util.Arrays;

public static Process executeCommand(String command) throws IOException {
    if (command == null || command.isEmpty()) {
        throw new IllegalArgumentException("Command cannot be null or empty.");
    }

    String osName = System.getProperty("os.name").toLowerCase();
    boolean isWindows = osName.startsWith("windows");

    String[] cmdArray;
    if (isWindows && command.endsWith(".bat") || command.endsWith(".cmd")) {
        cmdArray = new String[]{"cmd.exe", "/c", command};
    } else {
        cmdArray = new String[]{null, command};
    }

    Process process = Runtime.getRuntime().exec(cmdArray);

    if (isWindows) {
        process.inputStream().close();
        process.errorStream().close();
    }

    InputStream inputStream = process.getInputStream();
    byte[] buffer = new byte[1024];
    int bytesRead;
    StringBuilder output = new StringBuilder();

    while ((bytesRead = inputStream.read(buffer)) > 0) {
        output.append(new String(Arrays.copyOfRange(buffer, 0, bytesRead)));
    }

    inputStream.close();

    int exitValue = process.exitValue();
    process.destroy();

    if (exitValue != 0) {
        throw new RuntimeException("Command execution failed with exit code: " + exitValue);
    }

    return new ProcessBuilder(command).inheritIO().start();
}
