import org.neo4j.graphdb.GraphDatabaseService;
import org.neo4j.graphdb.Node;
import org.neo4j.graphdb.RelationshipType;
import org.neo4j.graphdb.Transaction;
import org.neo4j.graphdb.factory.GraphDatabaseFactory;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class GraphDatabaseEdgeCreator {
    private static final String DATABASE_PATH = "path/to/your/neo4j/database";
    private GraphDatabaseService graphDatabase;

    public GraphDatabaseEdgeCreator() {
        GraphDatabaseFactory factory = new GraphDatabaseFactory(DATABASE_PATH);
        graphDatabase = factory.newEmbeddedDatabase();
    }

    public void createEdges(List<VertexBuilder> vertexBuilders) {
        try (Transaction transaction = graphDatabase.beginTx()) {
            Set<String> createdEdgeHashes = new HashSet<>();
            for (VertexBuilder vertexBuilder : vertexBuilders) {
                Node sourceNode = createOrGetNode(vertexBuilder.getId());
                Node targetNode = createOrGetNode(vertexBuilder.getTargetId());
                RelationshipType relationshipType = RelationshipType.withName(vertexBuilder.getRelationshipType());
                Node existingRelationship = getExistingRelationship(sourceNode, targetNode, relationshipType);
                if (existingRelationship == null) {
                    Node newRelationship = sourceNode.createRelationshipTo(targetNode, relationshipType);
                    String edgeHash = calculateEdgeHash(vertexBuilder.getId(), vertexBuilder.getTargetId(), relationshipType);
                    if (!createdEdgeHashes.add(edgeHash)) {
                        throw new IllegalStateException("Edge with hash: " + edgeHash + " already exists.");
                    }
                }
            }
            transaction.commit();
        }
    }

    private Node createOrGetNode(long id) {
        try (Transaction transaction = graphDatabase.beginTx()) {
            Node node = graphDatabase.findNodeByIdOrCreate(Long.toString(id), Labels.VERTEX);
            transaction.success();
            return node;
        }
    }

    private Node getExistingRelationship(Node sourceNode, Node targetNode, RelationshipType relationshipType) {
        return sourceNode.getRelationships(relationshipType, Direction.OUT).stream()
                .filter(relationship -> relationship.getStartNode().equals(sourceNode) && relationship.getEndNode().equals(targetNode))
                .findFirst()
                .orElse(null);
    }

    private String calculateEdgeHash(long sourceId, long targetId, RelationshipType relationshipType) {
        String edgeId = sourceId + "_" + targetId + "_" + relationshipType.name();
        return MessageDigest.getInstance("SHA-256").digest(edgeId.getBytes())[0] + "_" +
                new BigInteger(1, new ByteArrayInputStream(MessageDigest.getInstance("SHA-256").digest(edgeId.getBytes()))).toString(16).substring(0, 32);
    }

    public void shutdown() {
        graphDatabase.shutdown();
    }
}
