import org.apache.commons.codec.digest.DigestUtils;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.Objects;

public static String generateAndCheckMD5Hash(List<String> inputStrings, List<String> existingServerGroups) {
    String concatenatedStrings;
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hash;

        // Concatenate all input strings
        StringBuilder stringBuilder = new StringBuilder();
        for (String str : inputStrings) {
            stringBuilder.append(str);
        }
        concatenatedStrings = stringBuilder.toString();

        // Compute the MD5 hash of the concatenated strings
        md.update(concatenatedStrings.getBytes());
        hash = md.digest();

        // Convert the hash to a hexadecimal string
        String generatedMD5Hash = DigestUtils.byteToHex(hash);

        // Check if a server group with the generated MD5 hash already exists
        boolean serverGroupExists = false;
        for (String existingGroup : existingServerGroups) {
            if (Objects.equals(generatedMD5Hash, existingGroup)) {
                serverGroupExists = true;
                break;
            }
        }

        // If the server group does not exist, create a new one
        if (!serverGroupExists) {
            existingServerGroups.add(generatedMD5Hash);
            System.out.println("New server group created with MD5 hash: " + generatedMD5Hash);
        }

    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException("MD5 algorithm not supported", e);
    }

    return generatedMD5Hash;
}
