import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.encoding.Base64Encoder;
import java.security.SecureRandom;
import java.util.Arrays;

public class AESEncryptor {

    public static String encryptStringAES(String plainText, String secretKey) {
        if (plainText == null || secretKey == null) {
            throw new IllegalArgumentException("Plain text and secret key are required.");
        }

        try {
            KeyGenerator keyGen = KeyGenerator.getInstance("AES");
            keyGen.init(128);
