public class MergedInterval {

    public static String mergeIntervals(List<Interval> intervals) {
        LocalDateTime current = intervals.get(0).getStart();
        LocalDateTime end = current;

        for (Interval interval : intervals) {
            if (current.isAfter(interval.getEnd())) {
