public String readSystemBuildPropFile() {
    Process process;
    BufferedReader inputReader;
    String line;
    String propContent = "";

    try {
        File file = new File("/system/build.prop");
        if (file.exists() && file.isFile()) {
            FileInputStream fis = new FileInputStream(file);
