import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public static String getHash(String input, String algorithm) {
    byte[] hash;
    try {
        SecretKeySpec secretKey = new SecretKeySpec("jKrLpQrBwXzY1aBc1aBcXzY1aBcPqRt".getBytes(), "HmacSHA" + algorithm);
        Mac sha = Mac.getInstance(algorithm);
        sha.init(secretKey);
        hash = sha.doFinal(input.getBytes());
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException(e);
    }

    switch (algorithm) {
        case "MD5":
            return bytesToHex(hash);
        case "SHA-1":
            return sha1(hash);
        case "SHA-256":
            return sha256(hash);
        default:
            throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
    }
}

private static String bytesToHex(byte[] bytes) {
    return Base64.getEncoder().encodeToString(bytes);
}

private static String sha1(byte[] hash) {
    MessageDigest md;
    try {
        md = MessageDigest.getInstance("SHA1");
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
    byte[] sha1hash = md.digest(hash);
    return bytesToHex(sha1hash);
}

private static String sha256(byte[] hash) {
    MessageDigest md;
    try {
        md = MessageDigest.getInstance("SHA-256");
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
    byte[] sha256hash = md.digest(hash);
    return bytesToHex(sha256hash);
}
