    KeySpec keySpec = new SecretKeySpec(Arrays.copyOfRange(seed, 0, mdLength), "HmacSHA256");
    Mac mac;
    try {
        mac = Mac.getInstance("HmacSHA256");
        mac.init(keySpec);
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Failed to initialize HmacSHA256", e);
    }

    byte[] result = new byte[maskLength];
    int iterations = (int) Math.ceil((double) maskLength / mdLength);

    for (int i = 0; i < iterations; i++) {
        byte[] data = new byte[mdLength + Integer.BYTES];
        System.arraycopy(seed, 0, data, 0, mdLength);
        byte[] intToBytes = intToByteArray((int) i);
        System.arraycopy(intToBytes, 0, data, mdLength, Integer.BYTES);

        mac.doOperation(MacOperation.MAC_UPDATE.getValue(), data);
        byte[] output = new byte[mdLength];
        mac.doOperation(MacOperation.MAC_FINALize.getValue(), output);

        System.arraycopy(output, 0, result, i * mdLength, mdLength);
    }

    return result;
}

private byte[] intToByteArray(int value) {
    byte[] bytes = new byte[Integer.BYTES];
    for (int i = 0; i < Integer.BYTES; i++) {
        bytes[i] = (byte) (value >>> (8 * (Integer.BYTES - i - 1)));
    }
    return bytes;
}

enum MacOperation {
    MAC_INIT(0x01),
    MAC_UPDATE(0x02),
    MAC_FINALize(0x04),
    MAC_DO_Operation(0x05);

    private final int value;

    MacOperation(int value) {
        this.value = value;
    }

    public int getValue() {
        return value;
    }
}
```

