const fs = require('fs');

const LOADED_MODULES = new Map();

async function loadModule(filename, options) {
  if (LOADED_MODULES.has(filename)) {
    return LOADED_MODULES.get(filename);
  }

  const fileContent = fs.readFileSync(filename, 'utf-8');
  const module = { exports: {} };
  const script = new Function(`"use strict"; ${fileContent}`, module.exports);
  script();

  LOADED_MODULES.set(filename, module);
  return module;
}

function getExportedFunction(module, functionName) {
  return module.exports[functionName];
}

async function loadAndGetExportedFunction(filename, options) {
  const module = await loadModule(filename, options);
  const functionName = options.functionName;
  return getExportedFunction(module, functionName);
}

module.exports = {
  loadAndGetExportedFunction,
};
