```javascript
const fs = require('fs');
const path = require('path');
const stylus = require('stylus');

function generateCssFile(srcPath, destPath) {
  const files = fs.readdirSync(srcPath, { withFileTypes: true })
    .filter(fileInfo => fileInfo.isDirectory() === false)
    .map(fileInfo => path.join(srcPath, fileInfo.name));

  return new Promise((resolve, reject) => {
    const output = [];

    files.forEach(file => {
      const fileContent = fs.readFileSync(file, 'utf-8');
      const result = stylus(fileContent).render();

      if (result.err) {
        return reject(new Error(`Error processing file ${file}: ${result.err}`));
      }

      output.push(result.css);
    });

    const combinedCss = output.join('\n');

    fs.writeFile(destPath, combinedCss, err => {
      if (err) {
        return reject(new Error(`Error writing CSS file to ${destPath}: ${err}`));
      }

      resolve();
    });
  });
}

// Usage example:
generateCssFile('./path/to/stylus/files', './path/to/destination/css/file.css')
  .then(() => console.log('CSS file generated successfully'))
  .catch(err => console.error('Error generating CSS file:', err));
```

