function handleStaticFileRequest(request, response, filePath) {
  // Log request details for debugging and auditing purposes
  console.log(`[${new Date().toISOString()}] Received request for ${filePath}`);

  // Check if the request method is GET
  if (request.method !== 'GET') {
    response.writeHead(405, { 'Content-Type': 'text/plain' });
    response.end('Method Not Allowed');
    return;
  }

  // Check if the file exists and is within the safe directory
  fs.access(filePath, fs.constants.F_OK, (err) => {
    if (err) {
      // File not found, return 404 Not Found
      response.writeHead(404, { 'Content-Type': 'text/plain' });
      response.end('File Not Found');
      return;
    }

    // File exists, read its contents and send as response
    fs.readFile(filePath, (err, data) => {
      if (err) {
        // Error reading file, return 500 Internal Server Error
        response.writeHead(500, { 'Content-Type': 'text/plain' });
        response.end('Internal Server Error');
        return;
      }

      // Set appropriate headers for the file type
      const contentType = mime.lookup(path.extname(filePath));
      response.writeHead(200, { 'Content-Type': contentType });

      // Send file contents
      response.end(data);
    });
  });
