    uint8_t type;
    uint16_t len;
    uint8_t data[0];
} ofp_action_t;

bool parse_ofp_action(const uint8_t *buffer, size_t offset, size_t buffer_size, ofp_action_t **action) {
    size_t action_size;
    ofp_action_t *parsed_action;

    if (offset + OFP_ACTION_TYPE_LEN + OFP_ACTION_LEN_LEN > buffer_size) {
        *action = NULL;
        return false;
    }

    parsed_action = malloc(sizeof(ofp_action_t) + ntohs(buffer[offset + OFP_ACTION_LEN_LEN]) - (offset + OFP_ACTION_TYPE_LEN + OFP_ACTION_LEN_LEN));
    if (parsed_action == NULL) {
        *action = NULL;
        return false;
    }

    memcpy(parsed_action, buffer + offset, OFP_ACTION_TYPE_LEN + OFP_ACTION_LEN_LEN);
    offset += OFP_ACTION_TYPE_LEN + OFP_ACTION_LEN_LEN;

    parsed_action->len = ntohs(parsed_action->len);
    if (parsed_action->len < OFP_ACTION_DATA_MIN_LEN) {
        free(parsed_action);
        *action = NULL;
        return false;
    }

    if (offset + parsed_action->len > buffer_size) {
        free(parsed_action);
        *action = NULL;
        return false;
    }

    memcpy(parsed_action->data, buffer + offset, parsed_action->len);
    *action = parsed_action;

    action_size = sizeof(ofp_action_t) + parsed_action->len;
    return true;
}

