```javascript
const fs = require('fs-extra');
const less = require('less');
const path = require('path');

async function compileLessFiles(dirPath) {
  try {
    const results = {};
    const files = await fs.readdir(dirPath);

    for (const file of files) {
      const filePath = path.join(dirPath, file);
      const stats = await fs.stat(filePath);

      if (stats.isDirectory()) continue;

      const ext = path.extname(filePath).toLowerCase();
      if (ext !== '.less') continue;

      const outputPath = path.join(
        dirPath,
        path.basename(filePath, '.less') + '.css'
      );

      await new Promise((resolve, reject) => {
        less.renderFile(filePath, (err, css) => {
          if (err) {
            console.error(`Error compiling ${filePath}:`, err);
            return reject(err);
          }

          results[filePath] = css.css.toString();
          fs.writeFileSync(outputPath, css.css.toString());
          resolve();
        });
      });
    }

    return results;
  } catch (error) {
    console.error('Error during Less file compilation:', error);
    throw error;
  }
}
