function findAlertsInConfigFile(duration, searchString, configFileContent) {
  let matchCount = 0;
  let currentIndex = 0;

  // Validate input types
  if (typeof duration !== 'number' || typeof searchString !== 'string' || typeof configFileContent !== 'string') {
    throw new Error('Invalid input types');
  }

