async function processFile(filePath, action, data) {
  try {
    if (action === 'delete') {
      await fs.remove(filePath);
      console.log(`Deleted file: ${filePath}`);
    } else if (action === 'insert') {
      const content = fs.readFileSync(filePath, 'utf8');
      const newContent = lodash.replace(content, /placeholder/, data);
      await fs.writeFile(filePath, newContent, 'utf8');
      console.log(`Updated file: ${filePath}`);
    } else if (action === 'compileSass') {
      const result = await new Promise((resolve, reject) => {
        sass.render({ data: fs.readFileSync(filePath, 'utf8'), outFile: path.basename(filePath, '.sass') + '.css' }, (err, result) => {
          if (err) {
            reject(err);
          } else {
            resolve(result.css.toString());
          }
        });
      });
      await fs.writeFile(path.basename(filePath, '.sass') + '.css', result);
      console.log(`Compiled Sass to CSS: ${filePath}`);
    } else if (action === 'compileTypeScript') {
      const sourceFile = typescript.createSourceFile(path.basename(filePath), fs.readFileSync(filePath, 'utf8'), typescript.ScriptTarget.Latest);
      const compilerOptions = {
        target: typescript.ScriptTarget.ES2018,
        module: typescript.ModuleResolutionKind.Node14,
        outDir: './dist',
        sourceMap: true,
        declaration: true,
        strict: true,
        noEmit: true,
      };
      const program = typescript.createProgram([sourceFile], compilerOptions);
      const errors = typescript.getCompilationErrors(program);
      if (errors.length > 0) {
        console.log('TypeScript compilation errors:');
        errors.forEach((error) => console.log(error.messageText));
      } else {
        const outputFile = path.join('./dist', path.basename(filePath, '.ts') + '.js');
        typescript.saveOutputFile(outputFile, program.emit());
        console.log(`Compiled TypeScript to JavaScript: ${filePath}`);
      }
    } else if (action === 'concat') {
      const files = ['file1.txt', 'file2.txt'];
      const content = lodash.concat(fs.readFileSync(files[0], 'utf8').split('\n'), fs.readFileSync(files[1], 'utf8').split('\n'));
      await fs.writeFile('output.txt', content.join('\n'), 'utf8');
      console.log(`Concatenated files: ${files.join(', ')} > output.txt`);
    }
  } catch (error) {
    console.error('Error:', error.message);
  }
}

