const fs = require('fs-extra');
const path = require('path');
const glob = require('glob');
const _ = require('lodash');

class PackageFinder {
  constructor(rootDir) {
    this.rootDir = rootDir;
  }

  async findPackages() {
    let packages = [];
    const visit = this.visit.bind(this);
    await fs.readdir(this.rootDir).then(async (files) => {
      for (const file of files) {
        const fullPath = path.join(this.rootDir, file);
        const stat = await fs.stat(fullPath);
        if (stat.isDirectory()) {
          await fs.readdir(fullPath).then((subFiles) => visit(fullPath, subFiles));
        } else if (path.extname(fullPath) === '.rpm') {
          packages.push(path.basename(fullPath, '.rpm'));
        }
      }
    });
    return _.uniq(packages).sort();
  }

  visit(dir, files) {
    for (const file of files) {
      const fullPath = path.join(dir, file);
      fs.stat(fullPath).then((stat) => {
        if (stat.isDirectory()) {
          fs.readdir(fullPath).then((subFiles) => this.visit(fullPath, subFiles));
        } else if (path.extname(fullPath) === '.rpm') {
          this.packages.push(path.basename(fullPath, '.rpm'));
        }
      });
    }
  }
}

module.exports = PackageFinder;
