response:
```javascript
const handlebars = require('handlebars');

async function fetchSuggestions(input, upcInput) {
  const query = input.value.trim();
  const url = '/path/to/php-script.php?query=' + encodeURIComponent(query);

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    if (!response.ok) {
      throw new Error('Network response was not ok');
    }

    const data = await response.json();
    return data;
  } catch (error) {
    console.error('Error fetching suggestions:', error);
    return [];
  }
}

function renderSuggestions(suggestions, container) {
  const templateSource = document.getElementById('suggestions-template').innerHTML;
  const template = handlebars.compile(templateSource);
  const html = template({ suggestions });
  container.innerHTML = html;
}

function handleSelection(event, input, upcInput) {
  const id = event.target.dataset.productId;
  const upc = event.target.dataset.upc;

  input.value = event.target.innerText;
  upcInput.value = upc;
}

async function initAutocomplete(input, upcInput, container) {
  input.addEventListener('input', async () => {
    const suggestions = await fetchSuggestions(input, upcInput);
    renderSuggestions(suggestions, container);
  });

  container.addEventListener('click', (event) => {
    if (event.target.tagName === 'LI') {
      handleSelection(event, input, upcInput);
    }
  });
}

// Replace the following with the actual ID of your input element and template
const input = document.getElementById('search-input');
const upcInput = document.getElementById('upc-input');
const suggestionsContainer = document.getElementById('suggestions-container');

initAutocomplete(input, upcInput, suggestionsContainer);
```

