response:
```javascript
(() => {
  'use strict';
  const _ = require('underscore');
  const $ = require('jquery');

  function getTotalValue(dataset, options) {
    const fieldName = options.field;
    const startYear = parseInt(options.startYear, 10) || 2002; // Default to 2002 if not provided

    const filteredData = _.filter(dataset, (item) => {
      const itemYear = parseInt(_.get(item, 'year', 0), 10);
      return itemYear >= startYear;
    });

    const total = _.reduce(filteredData, (memo, item) => memo + _.result(item, fieldName), 0);

    $('#total-value').text(total);
    $('#output-year').text(startYear);

    return total;
  }

  $(() => {
    const dataset = JSON.parse($('#data').text());
    const options = { field: 'valueFieldName' }; // Replace 'valueFieldName' with the actual field name

    getTotalValue(dataset, options);
  });
})();
```

