Here's the secure JavaScript function to generate unique identifiers for given keys using a combination of a random postfix and a Symbol function, while maintaining a shared store of keys and their corresponding identifiers:

```javascript
const idStore = new Map();

function generateUniqueIdentifier(key) {
  if (!key) {
    throw new Error("Key must be provided.");
  }

  let identifier;

  do {
    identifier = Symbol(key) + '_' + Math.floor(Math.random() * 1e16).toString(36);
  } while (idStore.has(identifier));

  idStore.set(key, identifier);

  return identifier;
}
```

