const path = require('path');
const register = require('coffee-script/register');

function loadAndRegisterJobs(directory) {
  const jobsDirectory = path.resolve(__dirname, directory);
  const extensions = ['.js', '.coffee'];

  fs.readdirSync(jobsDirectory)
    .filter(file => extensions.includes(path.extname(file).toLowerCase()))
    .forEach(file => {
