function loadWaveformData(url, callback) {
  if (!url || typeof url !== 'string') {
    throw new Error('Invalid URL');
  }

  const xhr = new XMLHttpRequest();
  xhr.open('GET', url);
  xhr.responseType = 'json';

  xhr.onload = () => {
    if (xhr.status !== 200) {
      throw new Error('Failed to load data');
    }

    const waveformData = xhr.response;
    if (!Array.isArray(waveformData) || waveformData.length < 2) {
      throw new Error('Invalid waveform data');
    }

    const realParts = new Float32Array(waveformData[0].length);
    const imagParts = new Float32Array(waveformData[0].length);

    for (let i = 0; i < waveformData[0].length; i++) {
      realParts[i] = waveformData[0][i].real;
      imagParts[i] = waveformData[0][i].imag;
    }

    callback(realParts, imagParts);
  };

  xhr.onerror = () => {
    throw new Error('Failed to load data');
  };

  xhr.send();
}
