const fs = require('fs');

async function removeFile(filePath) {
  return new Promise((resolve, reject) => {
    fs.unlink(filePath, (err) => {
      if (err) {
        if (err.code === 'ENOENT') {
          // File does not exist, resolve with false
          resolve(false);
        } else {
          // Error occurred, reject with error
          reject(err);
        }
      } else {
        // File removed successfully, resolve with true
        resolve(true);
      }
    });
  });
}
```

