function generateUniqueIdentifier(characterSet, length, existingIdentifiers) {
  let identifier;
  do {
    identifier = '';
    for (let i = 0; i < length; i++) {
      identifier += characterSet[Math.floor(Math.random() * characterSet.length)];
    }
  } while (existingIdentifiers.includes(identifier));
  return identifier;
}
```

