```javascript
function handleEvent(event, element) {
  const namespaceRegex = /^(\w+):/; // Compile the regular expression once, outside the function
  let namespace;

  // Check if the event object is valid
  if (!event) {
    throw new Error("Invalid event object");
  }

  // Extract the namespace from the event name
  const match = namespaceRegex.exec(event.type);
  if (match) {
    namespace = match[1];
  }

  // Set the event object's namespace
  event.namespace = namespace;

  // Set up the handler argument list
  event.handlerArgs = [element];

  // Clean up the event object when it's no longer needed
  event.cleanup = () => {
    delete event.namespace;
    delete event.handlerArgs;
  };

  // Handle the event
  // ...
}
```

