function parseCSSSelector(selector) {
  const whitespaceRegex = /^\s+|\s+$/g;
  const escapeRegex = /\\([\\/bfnrt"'\\]|x[0-9a-fA-F][0-9a-fA-F]|u[0-9a-fA-F]{4}|[^\\])/g;
  const simpleSelectorRegex = /([^\s>+~,]*)([\s>+~,]*)?/g;
  const attributeTestRegex = /([^\s:]*)(:)([^\s"]*)?([\s"]*)?/g;

  // Remove leading and trailing whitespace
  selector = selector.trim();

  // Remove escaped characters
  selector = selector.replace(escapeRegex, (match, backslash, escape) => {
    switch (escape) {
      case 'w':
        return '\u0077';
      case 'b':
        return '\b';
      case 'f':
        return '\f';
      case 'n':
        return '\n';
      case 'r':
        return '\r';
      case 't':
        return '\t';
      case '\\':
        return '\\';
      case '':
        return '';
      default:
        return escape;
    }
  });

  const combinators = [];
  const selectors = [];
  let match;

  while ((match = simpleSelectorRegex.exec(selector)) !== null) {
    const [, simpleSelector, combinator] = match;
    selectors.push(simpleSelector.trim());

    if (combinator) {
      combinators.push(combinator);
    }
  }

  const result = {
    combinators,
    selectors,
  };

  let attributeTestMatch;
  while ((attributeTestMatch = attributeTestRegex.exec(selector)) !== null) {
    const [, attributeName, colon, attributeValue] = attributeTestMatch;
    result.attributeTests = result.attributeTests || [];
    result.attributeTests.push({
      attributeName: attributeName.trim(),
      attributeValue: attributeValue ? attributeValue.trim() : null,
    });
  }

  return result;
}
