```javascript
class ListManager {
  constructor(initialList = []) {
    this.list = initialList.slice().sort((a, b) => a - b);
  }

  addNumber(number) {
    const index = this.list.findIndex(value => value >= number);
    if (index >= 0) {
      throw new Error("Number already exists in the list.");
    }

    this.list.splice(index, 0, number);
  }

  removeNumber(number) {
    const index = this.list.findIndex(value => value === number);
    if (index < 0) {
      throw new Error("Number not found in the list.");
    }

    this.list.splice(index, 1);
  }

  sortList() {
    this.list.sort((a, b) => a - b);
  }

  getList() {
    return this.list.slice();
  }
}
