function jsonpRequest(url, method, payload, successCallback, errorCallback) {
  const callbackName = "jsonp_callback_" + new Date().getTime();
  window[callbackName] = function(data) {
    const xhr = new XMLHttpRequest();
    xhr.open("GET", url + "?" + method + "=" + encodeURIComponent(callbackName) + "&" + encodeURIComponent(JSON.stringify(payload)));
    xhr.onload = function() {
      if (xhr.status === 200) {
        successCallback(JSON.parse(xhr.responseText));
        document.body.removeChild(script);
      } else {
        errorCallback(new Error("JSONP request failed with status code " + xhr.status));
        document.body.removeChild(script);
      }
