```javascript
function loadHandlersAndHelpers(apiKey, failCount) {
  const handlersDir = "./handlers";
  const helpersDir = "./helpers";
  const fs = require("fs");
  const path = require("path");
  const { promisify } = require("util");
  const require = promisify(module.require);

  // Filter function to check if file is a JavaScript file
  const isJsFile = (filePath) => path.extname(filePath) === ".js";

  // Initialize handlers and helpers objects
  const handlers = {};
  const helpers = {};

  // Read directory and filter files
  return new Promise((resolve, reject) => {
    fs.readdir(handlersDir, (err, files) => {
      if (err) {
        reject(err);
      }

      const handlerFiles = files.filter((file) => isJsFile(path.join(handlersDir, file)));
      const helperFiles = files.filter((file) => file !== "index.js" && isJsFile(path.join(helpersDir, file)));

      // Load handlers
      Promise.all(
        handlerFiles.map((file) => {
          const filePath = path.join(handlersDir, file);
          return new Promise((resolve, reject) => {
            fs.readFile(filePath, "utf8", (err, data) => {
              if (err) {
                reject(err);
              }

              const handlerName = file.split("/")[1].split(".js")[0];
              handlers[handlerName] = require(data);
              resolve();
            });
          });
        })
      ).then(() => {
        // Load helpers
        Promise.all(
          helperFiles.map((file) => {
            const filePath = path.join(helpersDir, file);
            return new Promise((resolve, reject) => {
              fs.readFile(filePath, "utf8", (err, data) => {
                if (err) {
                  reject(err);
                }

                const helperName = file.split("/")[1].split(".js")[0];
                helpers[helperName] = new Function("apiKey", "failCount", data);
                resolve();
              });
            });
          })
        ).then(() => resolve());
      });
    });
  });

  return { handlers, helpers };
}
