const fs = require('fs');
const path = require('path');

function loadFiles(baseDir, callback) {
  const files = [];

  function processFile(filePath) {
    const fileExt = path.extname(filePath).toLowerCase();
    if (fileExt === '.js') {
      const fileModule = path.basename(filePath, '.js');
      fs.readFile(filePath, 'utf8', (err, data) => {
        if (err) {
          console.error(`Error reading file ${filePath}:`, err);
          return;
        }
        files.push(require(`${baseDir}/${fileModule}`));
        if (files.length === allFiles.length) {
          callback(files);
        }
      });
    } else {
      fs.stat(filePath, (err, stats) => {
        if (err) {
          if (err.code === 'ENOENT') {
            // File not found, continue processing other files
            return;
          }
          console.error(`Error reading directory ${baseDir}:`, err);
          return;
        }
        const dirContents = stats.children;
        allFiles.push(...dirContents.map(entry => path.join(baseDir, entry.name)));
        processFile(path.join(baseDir, entry.name));
      });
    }
  }

  const allFiles = fs.readdirSync(baseDir)
    .map(entry => path.join(baseDir, entry))
    .filter(entry => fs.lstatSync(entry).isDirectory())
    .map(entry => path.join(entry, '*'))
    .flat();

  processFile(baseDir);
}

