function updatePolicyConfiguration(policy, defaultValues) {
  // Validate input arguments
  if (typeof policy !== 'object' || typeof defaultValues !== 'object') {
    throw new Error('Invalid input arguments');
  }

  // Set default values for missing configuration attributes
  for (const key in defaultValues) {
    if (!policy.hasOwnProperty(key)) {
      policy[key] = defaultValues[key];
    }
  }

  // Parse resources and applyPolicies
  const resources = policy.resources || {};
  const parsedResources = {};
  for (const resourceKey in resources) {
    if (typeof resources[resourceKey] === 'string') {
      try {
        parsedResources[resourceKey] = JSON.parse(resources[resourceKey]);
      } catch (error) {
        throw new Error(`Invalid resource format for key "${resourceKey}"`);
      }
    } else {
      parsedResources[resourceKey] = resources[resourceKey];
    }
  }

  policy.resources = parsedResources;

  // Apply policies
  policy.applyPolicies = policy.applyPolicies || [];
  for (const policyIndex in policy.applyPolicies) {
    const policyRule = policy.applyPolicies[policyIndex];
    if (!policyRule.hasOwnProperty('command') || !policyRule.hasOwnProperty('rspfile') || !policyRule.hasOwnProperty('rspfile_content')) {
      throw new Error('Invalid policy rule format');
    }

    // Null check for parsed values
    const command = policyRule.command;
    const rspfile = policyRule.rspfile;
    const rspfileContent = policyRule.rspfile_content;
    if (command === null || rspfile === null || rspfileContent === null) {
      throw new Error('Missing required policy rule values');
    }
  }

  // Stringify resources and applyPolicies
  policy.resourcesString = JSON.stringify(policy.resources);
  policy.applyPoliciesString = JSON.stringify(policy.applyPolicies);

  return policy;
}
