function loadScriptSecurely(src, variableName) {
  // Generate a random number for use as an ID verification code
  const randomNumber = Math.floor(Math.random() * 1000000);

  // Construct the URL with a random number and variable name
  const scriptUrl = new URL(src);
  scriptUrl.searchParams.append('randomNumber', randomNumber.toString());
  scriptUrl.searchParams.append('variableName', variableName);

  // Create a new script element
