```javascript
async function reloadCommand(bot, oldCommandName) {
  try {
    const oldCommand = bot.commands.get(oldCommandName);

    if (!oldCommand) {
      console.error(`Command '${oldCommandName}' not found.`);
      return;
    }

    // Delete old command
    bot.commands.delete(oldCommandName);

    // Require and import new command module
    const newCommandModule = require(oldCommand.path);
    const NewCommand = newCommandModule.default || newCommandModule;

    // Create new command instance
    const newCommand = new NewCommand();

    // Set new command with aliases
    bot.commands.set(newCommand.name, newCommand);

    // Update command aliases
    for (const alias of newCommand.aliases) {
      bot.commands.set(alias, newCommand);
    }

    console.log(`Command '${oldCommandName}' reloaded as '${newCommand.name}'`);
  } catch (error) {
    console.error(`Error reloading command '${oldCommandName}':`, error);
  }
}
