const fs = require('fs');
const path = require('path');
const configPath = './config.toml'; // Ensure this is a trusted path

function listCacheTags(callback) {
  fs.readFileSync(configPath, 'utf8', (err, data) => {
    if (err) {
      console.error(`Error reading configuration file: ${err}`);
      return callback([]);
    }

    try {
      const config = toml.parse(data);
      const cacheTags = config.cacheTags || [];
      callback(cacheTags);
    } catch (error) {
      console.error(`Error parsing configuration file: ${error}`);
      return callback([]);
    }
  });
}

const util = require('util');
util.promisify(listCacheTags)((cacheTags) => {
  console.log('Cache tags:', cacheTags);
});
