function safeFunctionCreator(expression, args = []) {
  if (typeof expression !== 'string') {
    throw new Error('Expression must be a string');
  }

  try {
    const ast = Boom.parse(expression);
    if (ast.type !== 'ExpressionStatement') {
      throw new Error('Invalid expression format');
    }

    if (ast.expression.type === 'ArrowFunctionExpression') {
      const body = ast.expression.body;
      if (typeof body !== 'function') {
        throw new Error('Invalid arrow function body');
      }

      return new Function('...args', body.toString());
    } else if (ast.expression.type === 'CallExpression') {
      const callee = ast.expression.callee;
      if (callee.type !== 'Identifier') {
        throw new Error('Invalid function call expression');
      }

      const argsList = ast.expression.arguments;
      const argNames = argsList.map(arg => arg.name || 'arg');

      const body = argsList[argsList.length - 1].body;
      if (typeof body !== 'function') {
        throw new Error('Invalid function body');
      }

      return new Function(argNames, body.toString());
    } else {
      throw new Error('Invalid expression format');
    }
  } catch (parseError) {
    throw new Error(`Invalid expression: ${parseError.message}`);
  }
}
