import is from 'is-type-of'; // Import the 'is-type-of' package for type checking
import { PropTypes } from 'prop-types'; // Import the 'prop-types' package

type ValidationFunction = (prop: any, componentName: string) => void;

const propTypeCache: { [key: string]: Function } = {};

function createPropTypeChecker(validationFunction: ValidationFunction): Function {
  return (componentName: string, propType: any) => {
    const cachedPropTypeChecker = propTypeCache[componentName];

    if (cachedPropTypeChecker) {
      return cachedPropTypeChecker;
    }

    const newPropTypeChecker = (prop: any) => {
      if (!is(prop, propType)) {
        validationFunction(prop, componentName);
        throw new Error(`Invalid prop type for ${componentName}: expected ${propType.name}, received ${typeof prop}`);
      }
    };

    PropTypes.checkPropTypes(newPropTypeChecker, [propType], componentName);

    propTypeCache[componentName] = newPropTypeChecker;

    return newPropTypeChecker;
  };
}

export default createPropTypeChecker;
