let currentHash = window.location.hash;
const elements = document.querySelectorAll('a[id], #anchor');

function scrollToHash() {
  const newHash = window.location.hash;

  if (newHash === currentHash) return;

  currentHash = newHash;

  if (newHash === '') {
    window.scrollTo(0, 0);
  } else if (newHash.startsWith('#')) {
    const targetElement = elements.find(
      (element) => newHash === element.id || newHash === element.textContent.toLowerCase()
    );

    if (targetElement) {
      const targetPosition = targetElement.offsetTop;
      window.scrollTo({
        top: targetPosition,
        behavior: 'smooth'
      });
    }
  } else if (newHash === '#top') {
    window.scrollTo(0, 0);
  }
}

window.addEventListener('popstate', scrollToHash);
scrollToHash();
```

