function enableDragAndResize(elementId, minWidth, maxWidth) {
  const element = document.getElementById(elementId);
  let isDragging = false;
  let startX = 0;
  let startWidth = element.offsetWidth;

  function handleMouseDown(event) {
    if (event.button !== 0) return;

    isDragging = true;
    startX = event.clientX;
  }

  function handleMouseMove(event) {
    if (!isDragging) return;

    const newWidth = startWidth + (event.clientX - startX);
    element.style.width = Math.min(Math.max(newWidth, minWidth), maxWidth) + 'px';
  }

  function handleMouseUp() {
    isDragging = false;
  }

  function handleAlignmentButtonClick(event) {
    const alignButton = event.target;
    const newWidth = alignButton.dataset.value * parseInt(element.style.width.slice(0, -2));
    element.style.width = newWidth + 'px';
  }

  element.addEventListener('mousedown', handleMouseDown);
  document.addEventListener('mousemove', handleMouseMove);
  document.addEventListener('mouseup', handleMouseUp);

  const leftAlignButton = document.createElement('button');
  leftAlignButton.innerText = 'Left Align';
  leftAlignButton.dataset.value = 1;
  leftAlignButton.addEventListener('click', handleAlignmentButtonClick);

  const rightAlignButton = document.createElement('button');
  rightAlignButton.innerText = 'Right Align';
  rightAlignButton.dataset.value = 2;
  rightAlignButton.addEventListener('click', handleAlignmentButtonClick);

  element.parentNode.insertBefore(leftAlignButton, element.nextSibling);
  element.parentNode.insertBefore(rightAlignButton, element.nextSibling);
}
