let propCache = new Map();

function validateProps(componentName, props) {
  const knownProps = component.constructor.props; // Assuming component has a static props property
  const unknownProps = new Set();

  if (process.env.NODE_ENV === 'development') {
    props.forEach((prop, key) => {
      if (!knownProps.has(key)) {
        unknownProps.add(key);
      }
    });

    if (unknownProps.size > 0) {
      console.warn(`Unknown props passed to ${componentName}: ${[...unknownProps].join(', ')}`);
    }
  }

