function normalizeUrl(url) {
  // Create a new URL object to parse and manipulate the URL
  const parsedUrl = new URL(url);

  // Get the pathname of the URL
  let pathname = parsedUrl.pathname;

  // Split the pathname into segments using the pathname separator (/), and filter out empty and '.' segments
  const segments = pathname.split('/').filter(segment => segment !== '' && segment !== '.');

  // Join the remaining segments with the pathname separator to create the normalized pathname
  pathname = segments.length > 0 ? segments.join('/') : '/';

  // Set the new pathname on the URL object and return the normalized URL
  parsedUrl.pathname = pathname;
  return parsedUrl.toString();
}
