<?php

class User {
    private $pdo;

    public function __construct() {
        try {
            $this->pdo = new PDO("mysql:host=localhost;dbname=mydb", "username", "password");
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPT);
        } catch (PDOException $e) {
            die("Database connection failed: " . $e->getMessage());
        }
    }

    public function getUserDataByIP($ip) {
        try {
            $stmt = $this->pdo->prepare("SELECT * FROM users WHERE ip_address = :ip");
            $stmt->bindParam(':ip', $ip);
            $stmt->execute();
            $user = $stmt->fetch(PDO::FETCH_ASSOC);

            if ($user) {
                $stmt = $this->pdo->prepare("SELECT SUM(assets) as total_assets, SUM(debts) as total_debts FROM assets_debts WHERE user_id = :id");
                $stmt->bindParam(':id', $user['id']);
                $stmt->execute();
                $data = $stmt->fetch(PDO::FETCH_ASSOC);

                if ($data) {
                    $age = calculateAge($user['dob']);
                    $output = [
                        'age' => $age,
                        'sex' => $user['sex'],
                        'residence' => $user['residence'],
                        'assets' => $data['total_assets'],
                        'debts' => $data['total_debts'],
                        'net_worth' => $data['total_assets'] - $data['total_debts']
                    ];
                    return $output;
                }
            }

            return ['error' => 'User not found'];
        } catch (PDOException $e) {
            die("Database query failed: " . $e->getMessage());
        }
    }
}

function calculateAge($birthdate) {
    list($y1, $m1, $d1) = explode('-', $birthdate);
    $y = date('Y');
    $m = date('m');
    $d = date('d');

    $age = $y - $y1;

    if ($m < $m1) {
        $age--;
    }

    if (($m == $m1) && ($d < $d1)) {
        $age--;
    }

    return $age;
}

