function truncateTableAndResetId($entityManager, $tableName) {
    $connection = $entityManager->getConnection();

    try {
        // Disable foreign key checks
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS=0');

        // Truncate the table
        $connection->executeStatement("TRUNCATE TABLE {$tableName}");

        // Reset the auto-incrementing ID column
        $schemaManager = $entityManager->getSchemaManager();
        $table = $schemaManager->listTables($tableName)[0];
        $sequenceName = $schemaManager->getSequenceName($table, 'id');
        $connection->executeStatement("ALTER SEQUENCE {$sequenceName} RESTART WITH 1");

        // Enable foreign key checks
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS=1');
    } catch (\Exception $e) {
        // Handle specific error codes differently
        switch ($e->getCode()) {
            case -EACCES:
            case -EIO:
                throw $e;
            default:
                // Retry the operation on other errors
                break;
        }

        truncateTableAndResetId($entityManager, $tableName);
    }
}
