    );

    private record MethodSpec(Class<?> clazz, String name, Class<?>[] paramTypes, boolean isAbstract, Class<?>[] annotations) {}

    private static Predicate<Method> methodSpecMatches(MethodSpec methodSpec) {
        return method -> method.getDeclaringClass().equals(methodSpec.clazz())
                && method.getName().equals(methodSpec.name())
                && Arrays.equals(method.getParameterTypes(), methodSpec.paramTypes())
