    if (!in_array($algorithm, ['SSHA', 'SHA', 'SMD5'])) {
        $algorithm = 'SSHA'; // Default to SSHA if no algorithm is specified or an invalid one is given
    }

    $salt = uniqid(rand(), true); // Generate a unique salt using uniqid with a random seed

