function processFormSubmission($name, $username, $password, $email, $cpf, $address, $number, $complement, $neighborhood, $zipCode, $city, $state, $phone, $cellPhone) {
    if (
        empty($name) ||
        empty($username) ||
        empty($password) ||
        empty($email) ||
        empty($cpf) ||
        empty($address) ||
        empty($number) ||
        empty($complement) ||
        empty($neighborhood) ||
        empty($zipCode) ||
        empty($city) ||
        empty($state) ||
        empty($phone) ||
        empty($cellPhone)
    ) {
        return 'missing_data';
    }

    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    $db = new PDO('mysql:host=localhost;dbname=database_name', 'username', 'password');
    $stmt = $db->prepare("INSERT INTO users (name, username, password, email, cpf, address, number, complement, neighborhood, zip_code, city, state, phone, cell_phone) VALUES (:name, :username, :password, :email, :cpf, :address, :number, :complement, :neighborhood, :zip_code, :city, :state, :phone, :cell_phone)");
    $stmt->bindParam(':name', $name);
    $stmt->bindParam(':username', $username);
    $stmt->bindParam(':password', $hashedPassword);
    $stmt->bindParam(':email', $email);
    $stmt->bindParam(':cpf', $cpf);
    $stmt->bindParam(':address', $address);
    $stmt->bindParam(':number', $number);
    $stmt->bindParam(':complement', $complement);
    $stmt->bindParam(':neighborhood', $neighborhood);
    $stmt->bindParam(':zip_code', $zipCode);
    $stmt->bindParam(':city', $city);
    $stmt->bindParam(':state', $state);
    $stmt->bindParam(':phone', $phone);
    $stmt->bindParam(':cell_phone', $cellPhone);

