<?php
function generateTextImage($text, $x, $y, $direction = IMAGE_TEXT_TB, $fontFile, $fontSize, $padding, $backgroundColor) {
    // Check for valid input parameters
    if (empty($text) || !is_numeric($x) || !is_numeric($y) || !is_file($fontFile) || !is_numeric($fontSize) || !is_numeric($padding) || !is_array($backgroundColor) || count($backgroundColor) !== 3) {
        throw new InvalidArgumentException("Invalid input parameters.");
    }

    // Create a new image with the specified background color
    $image = imagecreatetruecolor(imagesx($backgroundImage = imagecreatefromjpeg('default_image.jpg')) + 2 * $padding, imagesy($backgroundImage) + 2 * $padding);
    imagefill($image, 0, 0, imagecolorallocate($image, $backgroundColor[0], $backgroundColor[1], $backgroundColor[2]));

    // Load the font
    $font = imageftstype($fontFile);
    if ($font === -1) {
        throw new RuntimeException("Failed to load font.");
    }

    // Calculate text width and height
    $textSize = imagefttextsize($font, $fontSize, $direction, 0, 0, imagecolorsforindex(imagecolorat($image, 0, 0)));
    $textWidth = $textSize[0];
    $textHeight = $textSize[1];

    // Add padding to text position
    $x += $padding;
    $y += $padding;

    // Add text to image
    imagefttext($image, $fontSize, $direction, $x, $y, imagecolorallocate($image, 255, 255, 255), $font);

    // Free memory
    imageftdestroy($font);

    // Return the generated image
    return $image;
}
?>
```

