function generate_boundary_and_read_chunk($content_type, $chunk_size) {
    $boundary = hash("sha256", microtime(true) . mt_rand(1, 100000)); // Generate a unique boundary
    $boundary .= "--" . substr(strtr(bin2hex(random_bytes(16)), '/:', '-_'), 0, 14); // Ensure valid characters

