<?php

function ldapQuery($input, $ldapHost, $ldapPort, $ldapBindDN, $ldapBindPassword, $ldapBaseDN, $ldapFilter) {
    // Sanitize user input using a filter
    $input = filter_var($input, FILTER_SANITIZE_STRING);

    if ($input === FALSE) {
        throw new Exception("Invalid input provided.");
    }

    // Initialize LDAP connection
    $context = ldap_create_context($ldapHost, $ldapPort);

    if ($context === FALSE) {
        throw new Exception("Failed to connect to LDAP server.");
    }

    // Bind to the LDAP server
    if (ldap_bind($context, $ldapBindDN, $ldapBindPassword) === FALSE) {
        ldap_unbind($context);
        throw new Exception("Failed to bind to LDAP server.");
    }

    // Construct LDAP query with sanitized input and proper escaping
    $query = sprintf("(%s=%s)", $ldapFilter, escapeshellarg($input));

    // Perform LDAP query
    $result = ldap_search($context, $ldapBaseDN, $query);

    if ($result === FALSE) {
        ldap_unbind($context);
        throw new Exception("Failed to execute LDAP query.");
    }

    // Fetch query results
    $entries = ldap_get_entries($result);

    // Close LDAP connection
    ldap_free_result($result);
    ldap_unbind($context);

    // Return query results
    return $entries;
}
