  try {
    $db = new PDO('mysql:host=localhost;dbname=database_name', 'username', 'password');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
  } catch (PDOException $e) {
    // Handle database connection error
    http_response_code(500);
    die('Database connection failed.');
  }

  if (empty($newPassword) || empty($confirmPassword)) {
    http_response_code(400);
    die('Both new password and confirmation are required.');
  }

  if ($newPassword !== $confirmPassword) {
    http_response_code(400);
    die('New password and confirmation do not match.');
  }

  $stmt = $db->prepare('SELECT id, password FROM users WHERE id = :userId');
  $stmt->bindParam(':userId', $userId);
  $stmt->execute();

  if ($stmt->rowCount() < 1) {
    http_response_code(404);
    die('User not found.');
  }

  $user = $stmt->fetch(PDO::FETCH_ASSOC);

  if (!password_verify($user['password'], $newPassword)) {
    http_response_code(401);
    die('Current password is incorrect.');
  }

  $stmt = $db->prepare('UPDATE users SET password = :newPassword, force_password_reset = 0 WHERE id = :userId');
  $stmt->bindParam(':newPassword', password_hash($newPassword, PASSWORD_DEFAULT));
  $stmt->bindParam(':userId', $userId);
  $stmt->execute();

  if ($stmt->rowCount() < 1) {
