function getDiskUsageInfo(): array {
    $dfCommand = 'df';
    $whichPath = trim(shell_exec("which {$dfCommand} 2>/dev/null"));

    if (empty($whichPath)) {
        throw new RuntimeException("The 'df' command is not installed or not in the system's PATH.");
    }

    $output = shell_exec("{$whichPath} --human-readable");
    $lines = explode("\n", $output);
    $diskUsageInfo = [];

    foreach ($lines as $line) {
        if (empty($line)) {
            continue;
        }

        $parts = explode(' ', $line);
        if (count($parts) < 6) {
            continue;
        }

