from urllib.parse import urljoin, quote

def generate_cache_key(name, params, context):
    params_str = json.dumps(params).encode()
    return hashlib.md5(name.encode() + params_str + context.encode()).hexdigest()

def get_url_from_cache(cache, name, params, context):
    key = generate_cache_key(name, params, context)
    return cache.get(key)

def create_url(name, params, context, absolute=True):
    key = generate_cache_key(name, params, context)
    url = ""
    base_url = "http://example.com/api"

    url += base_url

    if name:
        url += "/"
        url += quote(name)

    if params:
        url += "?"
        params_str = ""
        for param in params:
            if isinstance(param, str):
                params_str += f"{quote(param)}={quote(str(param))}&"
            elif isinstance(param, dict):
                params_str += f"{quote(param['name'])}={quote(str(param['value']))}&"

        url = url[:len(url)-1] + params_str

    if absolute:
        url = urljoin(base_url, url)

