function executeCommandAndLog($command, $outputFile, $logFile, $escapeOutput = true) {
    // Validate input parameters
    if (!is_string($command)) {
        throw new InvalidArgumentException('Command must be a string.');
    }
    if (!is_writable(sys_get_temp_dir() . '/' . $outputFile)) {
        throw new RuntimeException('Output file is not writable.');
    }
    if (!is_writable(sys_get_temp_dir() . '/' . $logFile)) {
