    // Execute command and capture output
    $output = shell_exec($command);

    // Log command and output to files
    file_put_contents(sys_get_temp_dir() . '/' . $logFile, $command . PHP_EOL);
    file_put_contents(sys_get_temp_dir() . '/' . $outputFile, $output);

    // Modify output based on input parameter
    if ($escapeOutput) {
        $output = escapeshellarg($output);
    }

    return $output;
}
