function deleteContentElementAndUpdatePositions($db, $elementId) {
    // Fetch the content element to be deleted
    $stmt = $db->prepare("SELECT * FROM contents WHERE id = :id");
    $stmt->bindParam(":id", $elementId);
    $stmt->execute();
    $contentElement = $stmt->fetch(PDO::FETCH_ASSOC);

    if (!$contentElement) {
        throw new Exception("Content element not found.");
    }

    // Delete the content element
    $stmt = $db->prepare("DELETE FROM contents WHERE id = :id");
    $stmt->bindParam(":id", $elementId);
    $stmt->execute();

    // Update the positions of subsequent elements
    $stmt = $db->prepare("UPDATE contents SET position = position - 1 WHERE position > :position");
    $stmt->bindParam(":position", $contentElement["position"]);
    $stmt->execute();
}
