```javascript
class InteractiveMap {
  constructor(apiKey, containerElement, locations) {
    this.apiKey = apiKey;
    this.containerElement = containerElement;
    this.locations = locations;
    this.map = null;
    this.markers = {};

    this.init();
  }

  init() {
    this.map = new google.maps.Map(this.containerElement, {
      center: { lat: 0, lng: 0 },
      zoom: 1,
    });

    this.createMenu();

    for (const location of this.locations) {
      this.addMarker(location);
    }
  }

  addMarker(location) {
    const marker = new google.maps.Marker({
      position: location.coordinates,
      map: this.map,
    });

    this.markers[location.category] = this.markers[location.category] || [];
    this.markers[location.category].push(marker);
  }

  createMenu() {
    const container = document.createElement("div");
    container.id = "map-menu";

    for (const category in this.locations[0].categories) {
      const toggle = document.createElement("button");
      toggle.textContent = category;
      toggle.addEventListener("click", () => this.toggleMarkersByCategory(category));
      container.appendChild(toggle);
    }

    document.body.appendChild(container);
  }

  toggleMarkersByCategory(category) {
    for (const markerList of Object.values(this.markers)) {
      for (const marker of markerList) {
        if (marker.category === category) {
          marker.setVisible(event.target.checked);
        }
      }
    }
  }

  get category() {
    return this._category;
  }

  set category(value) {
    if (this._category === value) return;
    this._category = value;
    for (const marker of Object.values(this.markers[value])) {
      marker.setVisible(true);
    }
  }
}

