function pingbackRemoteUrl($remoteUrl) {
    if (empty($remoteUrl)) {
        return "Error: Empty remote URL.";
    }

    $parsedUrl = parse_url($remoteUrl);
    if (!isset($parsedUrl['scheme']) || !in_array($parsedUrl['scheme'], ['http', 'https'])) {
        return "Error: Invalid URL scheme.";
    }

    $remoteHost = $parsedUrl['host'];
    $remotePort = isset($parsedUrl['port']) ? $parsedUrl['port'] : 80;

    // Check if the remote server is pingback-enabled
    $pingbackEnabled = $this->isPingbackEnabled($remoteHost, $remotePort);
    if (!$pingbackEnabled) {
        return "Error: Remote server is not pingback-enabled.";
    }

    // Check if the remote URL has already been pinged
    if ($this->hasBeenPinged($remoteUrl)) {
        return "Error: Remote URL has already been pinged.";
    }

    // Sleep for 1 second before making the request
    usleep(1000000);

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $remoteUrl);
    curl_setopt($ch, CURLOPT_NOBODY, true);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, false);
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 5);

    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

    curl_close($ch);

    if ($httpCode != 200) {
        return "Error: Remote server returned HTTP error code " . $httpCode;
    }

    // Check remote server's IP address and user agent
    $remoteAddress = curl_getinfo($ch, CURLINFO_PRIMARY_IP);
    curl_close($ch);

    $remoteUserAgent = $_SERVER['HTTP_USER_AGENT'];

    if ($remoteAddress === false || $remoteUserAgent === false) {
        return "Error: Unable to retrieve remote server's IP address or user agent.";
    }

    // Store that the remote URL has been pinged
    $this->markAsPinged($remoteUrl);

    return "Pingback successful. Remote server IP address: " . $remoteAddress . ", User Agent: " . $remoteUserAgent;
}

