    $salt = openssl_random_pseudo_bytes(16);
    $hashedPassword = password_hash($newPassword . $salt, PASSWORD_DEFAULT);

    try {
        $db = new PDO('mysql:host=localhost;dbname=database_name', 'username', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $stmt = $db->prepare("UPDATE users SET password = :hashed_password, reset_token = NULL, last_password_change = NOW() WHERE user_id = :userId");
        $stmt->bindParam(':hashed_password', $hashedPassword);
        $stmt->bindParam(':userId', $userId);
        $stmt->execute();

        if ($stmt->rowCount() > 0) {
            $message = "Your password has been successfully changed.";
            $this->sendStatusEmail($email, $message);
        } else {
            throw new Exception("User not found.");
        }

    } catch (PDOException $e) {
        throw new Exception("Database error: " . $e->getMessage());
    }
}

function sendStatusEmail($email, $message) {
    $mail = new PHPMailer\PHPMailer\PHPMailer();

    try {
        $mail->isSMTP();
        $mail->Host = 'smtp.example.com';
        $mail->SMTPAuth = true;
        $mail->Username = 'username@example.com';
        $mail->Password = 'password';
        $mail->SMTPSecure = 'tls';
        $mail->Port = 587;

        $mail->setFrom('noreply@example.com', 'Password Manager');
        $mail->addAddress($email);
        $mail->isHTML(false);
        $mail->Subject = 'Password Changed';
        $mail->Body = $message;

