function initAutocomplete(inputFieldId) {
  // Ensure the input field exists
  const inputField = document.getElementById(inputFieldId);
  if (!inputField) {
    console.error(`Input field with ID '${inputFieldId}' not found.`);
    return;
  }

  // Initialize the Google Maps JavaScript API
  const script = document.createElement("script");
  script.src = "https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&libraries=places";
  document.head.appendChild(script);

  // Wait for the API to load before initializing the autocomplete object
  script.addEventListener("load", () => {
    const places = new google.maps.places.Autocomplete(inputField);
    places.addListener("place_changed", () => {
      const place = places.getPlace();
      if (place.geometry) {
        // Handle the selected place here
      } else {
        console.error("Autocomplete place object contains no geometry.");
      }
    });
  });

  // Attach the autocomplete object to the input field using jQuery
  $(inputField).autocomplete({
    source: function(request, response) {
      // Use the Google Maps Places API to fetch suggestions
      const service = new google.maps.places.AutocompleteService();
      service.getPlacePredictions(
        { input: request.term },
        (predictions, status) => {
          response(predictions.map((prediction) => prediction.description));
        }
      );
    },
    minLength: 2,
  });
}
