```javascript
async function initPage() {
  try {
    // Create and insert script tag for loading external libraries
    const scriptElement = document.createElement("script");
    scriptElement.src = "https://cdn.jsdelivr.net/npm/mapping-api@1.0.0/mapping.min.js";
    scriptElement.type = "text/javascript";
    scriptElement.async = true;
    scriptElement.onload = () => {
      // Initialize mapping API
      initMapping();

      // Create and insert script tag for loading sharing library
      const scriptElement2 = document.createElement("script");
      scriptElement2.src = "https://platform.socialmedia.com/js/sharing.js";
      scriptElement2.type = "text/javascript";
      scriptElement2.async = true;
      scriptElement2.onload = () => {
        // Configure sharing button
        const config = {
          publisher: "publisher-id",
          render: "button",
          theme: "theme-name",
          lang: "en_US",
          text: "Share",
          onShare: function(event) {
            // Handle share event
          }
        };

        const buttonElement = document.createElement("button");
        buttonElement.innerHTML = "Share";
        buttonElement.className = "social-share-button";

        document.body.appendChild(buttonElement);

        socialMedia.buttonInit(buttonElement, config);
      };
      document.head.appendChild(scriptElement2);
    };
    document.head.appendChild(scriptElement);
  } catch (error) {
    console.error("Error initializing page: ", error);
  }
}

// Initialize page
initPage();
