            'response_type' => 'code',
            'redirect_uri' => 'http://your-app.com/callback.php',
            'scope' => 'user_info',
            'state' => uniqid(),
        ],
    ]);

    $code = $authResponse->getQueryParam('code');

    if (!$code) {
        throw new Exception("Authentication failed.");
    }

    $tokenResponse = $httpClient->request('POST', $tokenUrl, [
        'form_params' => [
            'grant_type' => 'authorization_code',
            'client_id' => $clientId,
            'client_secret' => $clientSecret,
            'code' => $code,
            'redirect_uri' => 'http://your-app.com/callback.php',
        ],
    ]);

    $accessToken = json_decode((string) $tokenResponse->getBody(), true)['access_token'];

    if (!$accessToken) {
        throw new Exception("Access token not received.");
