<?php
function createUser($username, $email, $pass) {
    // Validate input
    if (empty($username) || empty($email) || empty($pass) || strlen($pass) < 6) {
        return "Invalid input. Username, email, and password are required, and password must be at least 6 characters long.";
    }

    // Prepare database connection
    $db = new PDO('mysql:host=localhost;dbname=my_database', 'username', 'password');

    // Prepare statement for checking if username or email already exists
    $stmt = $db->prepare("SELECT id FROM users WHERE username = :username OR email = :email");

    // Bind parameters
    $stmt->bindParam(':username', $username);
    $stmt->bindParam(':email', $email);

    // Execute query and check result
    $stmt->execute();
    $result = $stmt->fetch(PDO::FETCH_ASSOC);

    if ($result) {
        // Username or email already exists
        return "Error: Username or email already in use.";
    }

    // Hash password
    $hashedPass = password_hash($pass, PASSWORD_DEFAULT);

    // Prepare statement for inserting new user
    $stmt = $db->prepare("INSERT INTO users (username, email, password) VALUES (:username, :email, :password)");

    // Bind parameters
    $stmt->bindParam(':username', $username);
    $stmt->bindParam(':email', $email);
    $stmt->bindParam(':password', $hashedPass);

    // Execute query and check result
    $stmt->execute();
    $lastId = $db->lastInsertId();

    if ($lastId === false) {
        // Error during insertion
        return "Error: Failed to create user account.";
    }

    // Success
    return "Success";
}
