use ReflectionClass;

class MockBuilderFactory
{
    public function createMockObject(string $className, array $interfaceNames = []): MockObject
    {
        $reflectionClass = new ReflectionClass($className);
        $implementedInterfaces = $reflectionClass->getInterfaces();

        $newClassName = 'Mock' . ucfirst(str_replace('\\', '_', $className)) . '_Mock';
        $newClassCode = "class $newClassName implements {" . implode(', ', array_map(fn ($interface) => '$interface', $implementedInterfaces)) . "} {\n";

