        eval($newClassCode);

        $mockBuilder = \PhpUnit\Framework\MockBuilder::class;
        $reflectionMockBuilder = new ReflectionClass($mockBuilder);

        return $reflectionMockBuilder->newInstanceArgs([new $newClassName()]);
    }
