class UserDao {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updatePassword(string $username, string $newPassword): bool {
        try {
            $stmt = $this->db->prepare("SELECT id FROM users WHERE username = :username");
            $stmt->bindParam(':username', $username);
            $stmt->execute();
            $user = $stmt->fetch(PDO::FETCH_ASSOC);

            if (!$user) {
                throw new Exception("User not found.");
            }

            $hashedNewPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            $stmt = $this->db->prepare("UPDATE users SET password = :hashed_password WHERE id = :id");
            $stmt->bindParam(':id', $user['id']);
            $stmt->bindParam(':hashed_password', $hashedNewPassword);
            $stmt->execute();

            $stmt->closeCursor();

            // Password strength validation using zxcvbn library
            $zxcvbn = new \Zxcvbn\Zxcvbn();
            $passwordStrength = $zxcvbn->passwordStrength($newPassword);

            if ($passwordStrength['score'] < 3) {
                throw new Exception("Password is too weak.");
            }

            return true;
        } catch (Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }
}

