Here's a secure JavaScript function that enqueues scripts in WordPress, including a fallback for jQuery, a Google Maps API script, and a custom script, using the `wp_enqueue_script` function:

```javascript
function enqueueScripts(pageName) {
  // Check if jQuery is already enqueued
  if (wp.scripts.queue.some((script) => script.src === 'https://code.jquery.com/jquery-3.6.0.min.js')) {
    return;
  }

  // Enqueue jQuery with a fallback to a local file
  if (wp.scripts.registered.jquery) {
    wp.dequeueScript('jquery');
  }
  wp.enqueueScript(
    'jquery',
    'https://code.jquery.com/jquery-3.6.0.min.js',
    {
      defer: true,
    }
  );

  // Check if Google Maps API script is needed
  if (pageName.includes('map')) {
    // Check if Google Maps API script is already enqueued
    if (wp.scripts.queue.some((script) => script.src.includes('googlemaps'))) {
      return;
    }

    // Enqueue Google Maps API script
    wp.enqueueScript(
      'google-maps',
      'https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY',
      {
        defer: true,
      }
    );
  }

  // Check if custom script is needed and already enqueued
  const scriptPath = 'path/to/your/custom-script.js';
  const scriptName = 'custom-script';
  if (pageName.includes('custom-page') && !wp.scripts.queue.some((script) => script.src === scriptPath || script.src.startsWith(scriptName))) {
    wp.enqueueScript(
      scriptName,
      scriptPath,
      {
        defer: true,
      }
    );

    // Check for dependencies and enqueue them
    if (wp.scripts.registered[scriptName] && wp.scripts.registered[scriptName].deps) {
      wp.scripts.deps.push(...wp.scripts.registered[scriptName].deps);
      wp.dequeueScript(...wp.scripts.registered[scriptName].deps);
      wp.enqueueScript(...wp.scripts.deps);
    }
  }
}
