<?php

function getUserID($cookieName = "USER_COOKIE_NAME", $sessionName = "SESSION_USER_ID") {
    $isValidCookie = false;
    $cookieValue = $_COOKIE[$cookieName] ?? null;

    if ($cookieValue) {
        $cookieParts = explode(":", $cookieValue); // Assuming cookie value is base64 encoded user ID:token
        list($decodedCookie) = explode("|", base64_decode($cookieParts[0]));
        if (is_numeric($decodedCookie)) {
            $isValidCookie = true;
            $userID = intval($decodedCookie);
        }
    }

    if (!$isValidCookie && session_status() === PHP_SESSION_ACTIVE) {
        $userID = $_SESSION[$sessionName] ?? null;
        if (is_numeric($userID)) {
            $isValidCookie = true;
        }
    }

    return $isValidCookie ? $userID : 1;
}

?>
```

