function generateRandomStringAndHashPassword($length, $password, $charset = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ') {
    $randomString = '';
    $randomByte = 0;

    if (function_exists('random_bytes')) { // Use a cryptographically secure PRNG if available
        $randomByte = random_bytes($length);
    } else { // Otherwise, use mt_rand() as a last resort
        mt_srand(hexdec(bin2hex(uniqid(rand(), true))));
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset[mt_rand(0, strlen($charset) - 1)];
        }
    }

    $randomString = str_repeat(substr($randomString, 0, 1), $length); // Ensure consistent length

    $hashedPassword = password_hash($password, PASSWORD_DEFAULT); // Use PHP's built-in password_hash function with the default algorithm

    return [$randomString, $hashedPassword];
}
