import Moment from moment; // Import Moment.js library

function initCountdown(dateTime) {
  const gettingStartedElement = document.getElementById('getting-started');
  if (!gettingStartedElement) {
    throw new Error('Element with ID "getting-started" not found');
  }

  let countdown = Moment(dateTime); // Initialize countdown using Moment.js

  function updateCountdown() {
    const remainingTime = Moment.duration(countdown.diff(Moment()));
    const secondsLeft = Moment.utc(remainingTime.asMilliseconds()).seconds();

    if (secondsLeft <= 0) {
      gettingStartedElement.innerHTML = 'Countdown completed!';
      return;
    }

    countdown = Moment.utc(remainingTime.asMilliseconds());
    gettingStartedElement.innerHTML = Moment(countdown).format('mm:ss');
  }

  updateCountdown(); // Initial update
  setInterval(updateCountdown, 1000); // Update every second
}

// Usage example:
