<?php

function processFormSubmission($db, $session, $api_url, $comment_data) {
    // Validate input data
    if (empty($comment_data)) {
        $session['error'] = 'Comment data is empty';
        return redirect($api_url . '/error');
    }

    // Create a new comment using the API
    $comment_response = file_get_contents($api_url . '/comment', false, stream_context_create([
        'http' => [
            'method' => 'POST',
            'header' => "Content-Type: application/json\r\n",
            'content' => json_encode($comment_data),
        ],
    ]));

    if ($comment_response === false) {
        $session['error'] = 'Error contacting API';
        return redirect($api_url . '/error');
    }

    $comment_data = json_decode($comment_response, true);

    if (json_last_error() !== JSON_SUCCESS) {
        $session['error'] = 'Invalid API response';
        return redirect($api_url . '/error');
    }

    if (isset($comment_data['error'])) {
        $session['error'] = $comment_data['error'];
        return redirect($api_url . '/error');
    }

    // Store the comment result and success message in session variables
    $session['comment'] = $comment_data;
    $session['message'] = 'Comment created successfully';

    // Redirect to the specified URL
    return redirect($api_url . '/success');
}

