function secure_string_hash($input) {
    if (empty($input)) {
        throw new InvalidArgumentException('Input string cannot be empty.');
    }

    $hashed = '';
    $context = hash_init(hash_algos()['sha256'], HASH_HMAC, null);
    hash_update($context, $input, strlen($input));
    $hashed = hash_final($context, true);

    return bin2hex($hashed);
}
