class AssetBundle {
    private $css = [];
    private $js = [];
    private $dependencies = [];
    private $options = [];
    private $googleMapsCallback;

    public function __construct() {
        $this->active = new SplObjectStorage(1); // Initialize atomic variable for bundle state
    }

    public function addCss(string $file): void {
        $this->css[] = $file;
    }

    public function addJs(string $file, array $dependencies = []): void {
        $this->js[$file] = $dependencies;
    }

    public function addDependency(string $class): void {
        $this->dependencies[] = $class;
    }

    public function setJsOptions(array $options): void {
        $this->options = $options;
    }

    public function setGoogleMapsCallback(callable $callback): void {
        $this->googleMapsCallback = $callback;
    }

    public function getCss(): array {
        return $this->css;
    }

    public function getJs(): array {
        return $this->js;
    }

    public function getDependencies(): array {
        return $this->dependencies;
    }

    public function getJsOptions(): array {
        return $this->options;
    }

    public function getGoogleMapsCallback(): callable {
        return $this->googleMapsCallback;
    }

    public function __destruct() {
        $this->active->detachAll(); // Release atomic variable for bundle state
    }
}
