<?php

function safeInsert($dbConnection, $table, $columns, $values) {
  $hasPassword = false;
  $columnNames = array_map('mysql_real_escape_string', $columns);
  $placeholders = str_repeat('?,', count($values) + ($hasPassword ? 1 : 0)) . '';

  try {
    $stmt = $dbConnection->prepare("INSERT INTO $table (" . implode(',', $columnNames) . ") VALUES ($placeholders)");
    $stmt->bind_param($placeholders);

    for ($i = 0; $i < count($values); $i++) {
      $stmt->bind_param("s", $values[$i]);
    }

    if (isset($values[count($values)])) {
      $hashedPassword = password_hash($values[count($values)], PASSWORD_DEFAULT);
      $values[count($values)] = $hashedPassword;
    }

    $stmt->execute();
    $lastId = $stmt->insert_id;

  } catch (Exception $e) {
    // Return an error message instead of detailed exception information
    echo "An error occurred while inserting data.";
    return;
  }

  $stmt->close();
  return array('result' => true, 'last_id' => $lastId);
}

