import hashlib
import json
import os
from typing import Optional

def get_md5(headers: dict) -> str:
    request_str = json.dumps(headers).encode()
    return hashlib.md5(request_str).hexdigest()

def read_cache(cache_path: str) -> Optional[str]:
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as file:
            return file.read()
    return None

def write_cache(cache_path: str, data: str):
    with open(cache_path, 'w') as file:
        file.write(data)

def handle_request(request) -> str:
    headers = request.headers.as_dict()
    path = request.path

    md5_hash = get_md5(headers)
    cache_path = f"cache/{md5_hash}.json"

    if request.method == "GET":
        cached_data = read_cache(cache_path)
        if cached_data:
            return cached_data

    response = "{}".format(request.json)
    write_cache(cache_path, response)

    return response
