public static int[] GetSubset(int[] originalArray, int[] dimensions, int[][] intervals)
{
    if (originalArray == null || dimensions == null || intervals == null)
    {
        throw new ArgumentNullException();
    }

    if (dimensions.Length == 0 || intervals.Length == 0)
