            intervals[i][0] < 0 || intervals[i][1] > dimensions[i] ||
            intervals[i][0] >= dimensions[i] || intervals[i][1] >= dimensions[i])
        {
            throw new ArgumentOutOfRangeException("intervals", $"Invalid interval for dimension {i}.");
        }
    }

    // Calculate new dimensions
    for (int i = 0; i < dimensions.Length; i++)
    {
        newDimensions[i] = dimensions[i] - (intervals[i][1] - intervals[i][0]);
    }

    int newTotalLength = CalculateTotalLength(newDimensions);
    int[] newArray = new int[newTotalLength];

