                    newArray[destinationIndex++] = originalArray[sourceIndex++];
                }
            });
        }

        if (newTotalLength > 0)
        {
            for (int i = 0; i < newTotalLength; i++)
            {
                if (rng.NextDouble() < 0.5)
                {
                    int temp = newArray[i];
                    int randomIndex = new Random().Next(newTotalLength);
                    newArray[i] = newArray[randomIndex];
                    newArray[randomIndex] = temp;
                }
            }
        }
    }

    Array.Reverse(newArray); // Optional: Shuffle the array for better randomness

    int[] result = new int[newTotalLength];
    Array.Copy(newArray, result, newTotalLength);

    return result;
}

private static int CalculateTotalLength(int[] dimensions)
{
    return Math.Max(1, dimensions.Sum(d => 1 << d));
}
