import json
import re
import xml.etree.ElementTree as ET
class JsonParser:
    _registry = {}

    def __init__(self, id):
        self.id = id

    def to_json_string(self, data):
        return json.dumps(data, default=self.serialize)

    @staticmethod
    def from_json_string(json_str):
        if json_str in JsonParser._registry:
            return JsonParser._registry[json_str].from_json(json_str)
        raise ValueError("Unknown JSON format")

    @classmethod
    def register(cls, id, factory):
        cls._registry[id] = factory

    def serialize(self, obj):
        if isinstance(obj, str):
            return json.quote(obj)
        raise TypeError("Unsupported type")

    @classonlymethod
    def from_json(cls, json_str):
        root = ET.fromstring(json.loads(json_str))
        obj = cls.__new__(cls, root.get("id"))
        for tag, value in root.iter():
            setattr(obj, tag, JsonParser.parse_value(value))
        return obj

    @staticmethod
    def parse_value(value):
        if isinstance(value, list):
            return [JsonParser.parse_value(v) for v in value]
        if isinstance(value, dict):
            return {k: JsonParser.parse_value(v) for k, v in value.items()}
        return value

class Subclass(JsonParser):
    def __init__(self, id, data):
        super().__init__(id)
        self.data = data

JsonParser.register("Subclass", Subclass)

def create_subclass(id, data):
    JsonParser.register(id, Subclass)
    return JsonParser.from_json_string(JsonParser(id).to_json_string(data))
