import pyuid as uid

class Plan:
    def __init__(self, identifier=None):
        self.identifier = identifier or uid.uid()
        self.features = {}

def create_plan(features):
    plan = Plan()
    for feature_name, feature_value in features.items():
        plan.features[feature_name] = feature_value
    return plan

def modify_plan_features(plan, new_features):
    plan.features.update(new_features)

def assert_plan_identical(plan_a, plan_b):
    assert plan_a.identifier == plan_b.identifier, "Plans have different identifiers"
    assert plan_a.features == plan_b.features, "Plans have different features"

def main():
    initial_features = {"feature_1": "value_1", "feature_2": "value_2"}
    plan = create_plan(initial_features)

    new_features = {"feature_1": "updated_value_1", "feature_2": "updated_value_2"}
    modified_plan = modify_plan_features(plan, new_features)

    assert_plan_identical(plan, modified_plan)

if __name__ == "__main__":
    main()
