import subprocess
import sys
import random
def run_command(command, args=None, check_output=True):
    """
    Execute the given command with optional arguments using subprocess.
    Return the output if check_output is True, or the exit code otherwise.
    """
    if args is None:
        cmd = command
    else:
        cmd = f"{command} {' '.join(args)}"

    process = subprocess.Popen(
        cmd,
        shell=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        universal_newlines=True,
    )

    output, error = process.communicate()

    if check_output:
        if error:
            print(f"Error executing command: {error}")
            raise RuntimeError("Command execution failed")
        return output.decode("utf-8")

    exit_code = process.poll()
    if exit_code is not None:
        print(f"Command execution failed with exit code: {exit_code}")
        raise RuntimeError("Command execution failed")

