import random

def rearrange_list(input_list, fazas_state):
    subset_size = int(len(input_list) * 0.5) if fazas_state else int(len(input_list) * 0.8)
    subset = random.sample(input_list, subset_size)

    if fazas_state:
        # Remove elements from the subset
        while len(subset) > len(input_list) // 2:
            index = random.randint(0, len(subset) - 1)
            subset.pop(index)
    else:
        # Add elements to the subset
        while len(subset) < len(input_list):
            element = random.randint(1, 50)
            if element not in subset:
                subset.append(element)

