def create_musical_notes(notes_list):
    # Validate the input list
    if not notes_list:
        raise ValueError("Input list is empty")

    musical_notes = []
    current_time = 0.0

    for note in notes_list:
        if not all([isinstance(i, (int, float)) for i in note.position]):
            raise TypeError("Invalid position format")

        if not isinstance(note.time, (int, float)):
            raise TypeError("Invalid time format")

        if note.note_type not in ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]:
            raise ValueError("Invalid note type")

        note_object = {
            "x": note.position[0],
            "y": note.position[1],
            "time": note.time,
            "note": note.note_type,
            "curve": note.curve or 0.0,
            "repeat": note.repeat or 1
        }

        musical_notes.append(note_object)
        current_time += note.time

    return musical_notes
