import random
import functools

def is_valid_port(port):
    """Validate that the given port is within the range of 1 to 65535."""
    return 1 <= port <= 65535

@functools.lru_cache(maxsize=None)
def generate_random_port():
    """Generate a random valid port."""
    while not is_valid_port(random.randint(1, 65535)):
        pass
    return random.randint(1, 65535)

def sort_ports_descending(ports):
    """Sort a list of ports in descending order."""
    return sorted(ports, reverse=True)

def format_ports_string(ports):
    """Format a list of ports as a comma-separated string."""
    return ", ".join(str(port) for port in ports)

def generate_random_ports_string(num_ports):
    """Generate a random list of ports, sort them in descending order, and return a string of comma-separated ports."""
    ports = [generate_random_port() for _ in range(num_ports)]
    sorted_ports = sort_ports_descending(ports)
    return format_ports_string(sorted_ports)
