class AdbConnection:
    def __init__(self, device_serial):
        self.device_serial = device_serial
        self.adb_path = "/path/to/adb"

    def capture_screenshot(self):
        try:
            cmd = [self.adb_path, "shell", "screencap", "-p", "/data/local/screenshot.png"]
            self._run_command(cmd)
            cmd = [self.adb_path, "pull", "/data/local/screenshot.png", "/tmp/screenshot.png"]
            self._run_command(cmd)
