            error = error.decode() if error else ""
            raise Exception(f"Command '{cmd}' failed with error: {error}")
        return output, error

    def disconnect(self):
        self._run_command([self.adb_path, "disconnect", self.device_serial])

class DeviceMonitor(threading.Thread):
