#define MAX_TIMEOUT 5 // Maximum timeout in seconds
#define INITIAL_SLEEP 1 // Initial sleep time in seconds
#define SLEEP_FACTOR 2 // Factor to increase sleep time by

int terminate_process(pid_t process_id) {
    int status;
    int exit_code = -1;
    pid_t child_pid;

    if (process_id <= 0) {
        perror("Invalid process ID");
        return exit_code;
    }

    // Check if process is already terminated
    if (waitpid(process_id, &status, WNOHANG) > 0) {
        exit_code = WEXITSTATUS(status);
        return exit_code;
    }

    // Send SIGTERM signal to process
    kill(process_id, SIGTERM);

    // Wait for process to terminate with a timeout
    struct timespec timeout;
    clock_gettime(CLOCK_MONOTONIC, &timeout);
    timeout.tv_sec += MAX_TIMEOUT;
    timeout.tv_nsec += (INITIAL_SLEEP * SLEEP_FACTOR * 1000000000LL);

    while (process_id != 0 && kill(process_id, 0) > 0) {
        if (timerexpired(&timeout)) {
            perror("Process termination timeout");
            return exit_code;
        }

        sleep(SLEEP_FACTOR);
        process_id = waitpid(process_id, &status, WNOHANG);

        if (process_id > 0) {
            exit_code = WEXITSTATUS(status);
            break;
