import os
import re
import subprocess
import sys
import tempfile

def extract_text_from_pdf(pdf_file):
    cmd = ["pdftotext", "-layout", pdf_file]
    process = subprocess.run(cmd, capture_output=True, text=True)
    return process.stdout

def tokenize_text(text):
    pattern = re.compile(r'\w+')
    return [word.lower() for word in pattern.findall(text)]

def create_bag_of_words(tokens):
    bag = {}
    for token in tokens:
        if token in bag:
            bag[token] += 1
        else:
            bag[token] = 1
    return bag

def save_bag_of_words_to_file(bag, output_file):
    with open(output_file, 'w') as f:
        for word, count in bag.items():
            f.write(f"{word} {count}\n")

def main():
    if len(sys.argv) != 2:
        print("Usage: python pdf_to_bag_of_words.py <PDF_FILE>")
        sys.exit(1)

    pdf_file = sys.argv[1]

    text = extract_text_from_pdf(pdf_file)
    tokens = tokenize_text(text)
    bag = create_bag_of_words(tokens)

    output_file = tempfile.mktemp(suffix=".txt")
    save_bag_of_words_to_file(bag, output_file)

    print(f"Bag-of-words saved to {output_file}")

if __name__ == "__main__":
