CREATE OR REPLACE FUNCTION create_and_lock_table(p_lock_name VARCHAR)
RETURNS INTEGER AS $$
DECLARE
  table_name VARCHAR;
  index_name VARCHAR;
  row1 VARCHAR;
  row2 VARCHAR;
  row3 VARCHAR;
  num_rows INTEGER;
  write_lock INT;
BEGIN
  -- Create table with auto-incrementing primary key
  table_name := 'my_table';
  EXECUTE format('CREATE TABLE IF NOT EXISTS %I (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR UNIQUE NOT NULL)', table_name);

  -- Insert first two rows with unique names
  row1 := 'John Doe';
  row2 := 'Jane Smith';
  EXECUTE format('INSERT INTO %I (name) VALUES (%L)', table_name, row1);
  EXECUTE format('INSERT INTO %I (name) VALUES (%L)', table_name, row2);

  -- Acquire write lock on table using given lock name
  write_lock := pg_try_advisory_lock(pg_get_serial_number(table_name), p_lock_name, 30);
  IF write_lock THEN
    -- Insert third row with non-unique name
    row3 := 'John Doe'; -- same name as row1
    EXECUTE format('INSERT INTO %I (name) VALUES (%L)', table_name, row3);

    -- Check if number of rows affected by insert operations matches the expected count
    num_rows := (SELECT COUNT(*) FROM %I);
    IF num_rows = 4 THEN
      -- Release lock and return number of rows affected
      EXIT;
    ELSE
      -- Rollback transaction and release lock if insert failed
      RAISE OPERATIONAL ERROR 'Failed to insert non-unique row', SET error_code = 'XYZ123';
      PGSTL_BACKOUT();
      EXECUTE format('RELEASE %I IN %L', p_lock_name, table_name);
      RETURN NULL;
    END IF;
  ELSE
    -- Release lock and return error if lock acquisition failed
    RAISE OPERATIONAL ERROR 'Failed to acquire write lock', SET error_code = 'XYZ456';
    RETURN NULL;
  END IF;

  -- Release lock and return number of rows affected
  EXECUTE format('RELEASE %I IN %L', p_lock_name, table_name);
  num_rows := (SELECT COUNT(*) FROM %I);
  RETURN num_rows;
END;
$$ LANGUAGE plpgsql;
