        query = request.GET.get("query")
    if not query:
        return dict(error="Must specify query parameter, use * to retrieve all")
    col_names = request.GET.getlist("col_names")

    ctx = conn.createServiceOptsDict()
    ctx.setOmeroGroup("-1")

