import sqlite3

def get_table_row_counts(tables):
    """
    Returns a dictionary containing the number of rows in each table in the given list.
    Raises an error if the number of rows in any table is zero or if the tables have different schemas.

    @param tables: list of table names
    @return: dict with keys as table names and values as number of rows
    """

    # Initialize database connection
    conn = sqlite3.connect("database.db")

    try:
        schema = {}
        row_counts = {}

        # Iterate through each table and get its schema and row count
        for table in tables:
            cursor = conn.cursor()
            cursor.execute(f"PRAGMA table_info({table});")
            schema[table] = [desc[1] for desc in cursor.fetchall()]
            cursor.execute(f"SELECT COUNT(*) FROM {table};")
            row_count = cursor.fetchone()[0]
            row_counts[table] = row_count

            # Check if the table schema is consistent with all other tables
            if schema:
                for other_table, other_schema in schema.items():
                    if table != other_table and set(schema[table]) != set(schema[other_table]):
                        raise ValueError("Tables have different schemas")

        # Check if any table has zero rows
        for table, row_count in row_counts.items():
            if row_count == 0:
                raise ValueError(f"Table {table} has zero rows")

        return row_counts

    finally:
        conn.close()
