#include <string.h>
#include <pthread.h>
#include <alsa/asoundlib.h>

#define MAX_VOLUME 100
#define MIN_VOLUME 0

typedef struct user_elem {
    snd_ctl_t *handle;
    snd_mixer_t *mixer;
    int volume;
    pthread_mutex_t lock;
} user_elem;

user_elem *ue;
pthread_mutex_t user_ctl_lock;

int set_volume(const char *input) {
    int new_volume;
    const char *end;

    if (!input || (strlen(input) > 1))
        return -EINVAL;

    new_volume = strtol(input, &end, 10);

    if (end > input && new_volume < MIN_VOLUME || new_volume > MAX_VOLUME)
        return -EINVAL;

    pthread_mutex_lock(&user_ctl_lock);
    ue->volume = new_volume;
    pthread_mutex_unlock(&user_ctl_lock);

    snd_mixer_selem_t *elem;
    snd_mixer_iterator_t iterator;
    snd_mixer_selem_get_name(snd_mixer_firstselem(ue->mixer), 0, &elem);
    snd_mixer_selem_set(ue->mixer, elem, SND_MIXER_SELEMENT_TYPE_MASTER, 0, new_volume);
    snd_mixer_selem_free(elem);

    return ue->volume;
}

void alsa_init() {
    int err;

    ue = malloc(sizeof(user_elem));
    if (!ue)
        return;

    err = snd_init_cards();
    if (err < 0) {
        free(ue);
        return;
    }

    ue->handle = snd_open("default", 0, 0, &err);
    if (err < 0) {
        snd_close(ue->handle);
        free(ue);
        snd_cleanup();
        return;
    }

    ue->mixer = snd_mixer_open(ue->handle, 0, 0, &err);
    if (err < 0) {
        snd_mixer_close(ue->mixer);
        snd_close(ue->handle);
        free(ue);
        snd_cleanup();
        return;
    }

    pthread_mutex_init(&user_ctl_lock, NULL);

    err = snd_mixer_selem_getname(snd_mixer_firstselem(ue->mixer), 0, NULL, 0);
    if (err < 0) {
        snd_mixer_close(ue->mixer);
        snd_close(ue->handle);
        free(ue);
        snd_cleanup();
        return;
    }
}

int main() {
