class LockDefinitionVisitor(ast.NodeVisitor):
    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name):
            raise Exception("Invalid lock definition: function call not in the form function_name(args)")
        self.function_name = node.func.id
        self.args = node.args
        self.kwargs = {} if not node.keywords else {key: value for key, value in node.keywords.args}
