def check_disk_usage(path, warning_threshold):
    """Check if given path has exceeded a warning threshold for disk usage."""
    command = "df -h {} --output=source,pcent {} | grep {} | awk '{print $1}'".format(path, path, re.escape(path))
    output, error = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()

    if error:
        msg = "Error while executing command: {}".format(command)
        logger.error(msg)
        return False, error.decode()

    usage_percent = int(re.search(r"\d+%", output.decode()).group())

    if usage_percent is not None and usage_percent >= warning_threshold:
        logger.warning(
            "Disk usage for path {} has reached {}%".format(path, usage_percent)
        )
        return True, output.decode()

    logger.debug("Disk usage for path {} is below warning threshold ({})".format(path, warning_threshold))
    return False, output.decode()
