import requests

def test_login(base_url, valid_username, valid_password, invalid_username, invalid_password, expected_error_message):
    session = requests.Session()

    # Attempt to log in with invalid credentials
    response = session.post(f"{base_url}/login", json={"username": invalid_username, "password": invalid_password})
    if response.status_code != 401:
        raise ValueError("Unexpected response status code")
    if not response.text or "error" not in response.text:
        raise ValueError("Missing error message in response")
    if response.text.find(expected_error_message) < 0:
        raise ValueError(f"Unexpected error message: {response.text}")

    # Attempt to log in with valid credentials
    response = session.post(f"{base_url}/login", json={"username": valid_username, "password": valid_password})
    if response.status_code != 200:
        raise ValueError("Unexpected response status code")
    if "error" in response.text:
        raise ValueError("Unexpected error message in response")
