import os
import hashlib

def calculate_file_sha1(file_path, max_bytes=None):
    try:
        if max_bytes is not None:
            with open(file_path, 'rb') as file:
                hasher = hashlib.sha1()
                data = file.read(max_bytes)
                hasher.update(data)
                file.close()
        else:
            with open(file_path, 'rb') as file:
                hasher = hashlib.sha1()
                while True:
                    data = file.read(65560)
                    if not data:
                        break
                    hasher.update(data)
                file.close()

        return hasher.hexdigest()
    except FileNotFoundError:
        raise FileNotFoundError(f"File '{file_path}' not found")
    except Exception as e:
        raise e
