import json
import boto3
import os
class InputIterator:
    def __init__(self, file_path=None, bucket_name=None, fail_on_missing=False):
        self.file_path = file_path
        self.bucket_name = bucket_name
        self.fail_on_missing = fail_on_missing
        self.iterator = None

    def _validate_input(self):
        if not self.file_path and not self.bucket_name:
            if self.fail_on_missing:
                raise ValueError("No input provided")
            else:
                return None

        if self.file_path and not os.path.isfile(self.file_path):
            if self.fail_on_missing:
                raise FileNotFoundError(f"File '{self.file_path}' not found")
            else:
                return None

        if self.bucket_name:
            self.s3 = boto3.client('s3')
            try:
                self.object = self.s3.get_object(Bucket=self.bucket_name, Key=self.file_path)
            except Exception as e:
                if self.fail_on_missing:
                    raise e
                else:
                    return None

    def load_object(self):
        self._validate_input()
        if self.file_path:
            with open(self.file_path, 'r') as file:
                self.obj = json.load(file)
        elif self.bucket_name:
            self.obj = json.load(self.object['Body'].iter_content(1024))

    def to_json(self):
        return json.dumps(self.obj)

    def __iter__(self):
        if self.iterator:
            return self.iterator
        self.load_object()
        self.iterator = iter(self.obj)
        return self.iterator
