      // Don't follow shortcuts when saving a shortcut, this can be used
      // to trick users (bug 271732)
      if (IsDefaultPathLink()) fos |= FOS_NODEREFERENCELINKS;
      break;

    case modeGetFolder:
      MOZ_ASSERT(false, "file-picker opened in directory-picker mode");
      return false;
