import re

def read_version_and_populate_metadata(file_path, metadata_dict):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            version_match = re.search(r'Version:\s*(\d+\.\d+)', content)
            if version_match:
                version_number = version_match.group(1)
                metadata_dict['version'] = version_number
            else:
