import os
import hashlib

def validate_filepath(filepath):
    import re
    pattern = re.compile(r'^[a-zA-Z]\:\[/\\]\.*$')
    if not pattern.match(filepath):
        raise ValueError("Invalid file path")

def extract_filename_extension(filepath):
    fileparts = os.path.splitext(filepath)
    filename = fileparts[0]
    extension = fileparts[1] if fileparts else ""
    return filename, extension

def sanitize_filename(filename):
    # Replace invalid characters with "_"
    invalid_chars = ["\\", "/", ":", "*", "?", "\"", "<", ">", "|"]
    for char in invalid_chars:
        filename = filename.replace(char, "_")
    return filename

def hash_filename(filename):
    # Hash the filename using SHA-256
    hash_object = hashlib.sha256(filename.encode())
    return hash_object.hexdigest()

def generate_hashed_filename(filepath):
    try:
        filepath = validate_filepath(filepath)
        filename, extension = extract_filename_extension(filepath)
        sanitized_filename = sanitize_filename(filename)
        hashed_extension = hash_filename(sanitized_filename)
        return f"{sanitized_filename}_{hashed_extension}"
    except Exception as e:
        print(f"Error: {str(e)}")

