    """Validates build folder existence and permissions."""
    if not os.path.exists(build_folder) or not os.access(build_folder, os.W_OK):
        raise IOError(f"Build folder '{build_folder}' does not exist or is not writable.")

def download_package(url, dest_folder):
    """Downloads a package and extracts it to the given folder."""
    response = requests.get(url, stream=True)
    if response.status_code != 200:
        raise Exception(f"Failed to download package from '{url}'.")

