import os
import hashlib

def _safe_open(file_path, mode="rb"):
    try:
        return open(file_path, mode)
    except FileNotFoundError:
        raise ValueError(f"File '{file_path}' not found.")
    except Exception as e:
        raise IOError(f"Error opening file '{file_path}': {str(e)}")

def _chunked_read(file, chunk_size=65536):
    while True:
        data = file.read(chunk_size)
        if not data:
            break
        yield data

def _calculate_md5_hash(file_path):
    with _safe_open(file_path) as file:
        md5_hash = hashlib.md5()
        for chunk in _chunked_read(file):
            md5_hash.update(chunk)
        return md5_hash.hexdigest()

def get_file_md5_hash(file_path):
    if not os.path.isfile(file_path):
        raise ValueError(f"File '{file_path}' does not exist.")
    return _calculate_md5_hash(file_path)
