import hashlib
import urlparse

class RFPDupeFilter:
    def __init__(self):
        self.seen_requests = set()

    def get_request_fingerprint(self, request):
        if not request or not request.headers or not request.url:
            return False

        url = urlparse(request.url).scheme + "://" + urlparse(request.url).netloc.lower() + request.url[len(urlparse(request.url).path):]
        request_fingerprint = hashlib.sha1(url.encode()).hexdigest()

        if request_fingerprint in self.seen_requests:
            return True

        self.seen_requests.add(request_fingerprint)
        return False

class CaseInsensitiveRFPDupeFilter(RFPDupeFilter):
    def get_request_fingerprint(self, request):
        if not request or not request.headers or not request.url:
            return False

        url = urlparse(request.url)
        url_str = url.scheme + "://" + url.netloc.lower() + urlparse(request.url).path.lower() + request.url[len(urlparse(request.url).path):]
        request_fingerprint = hashlib.sha1(url_str.encode()).hexdigest()

        if request_fingerprint in self.seen_requests:
            return True

        self.seen_requests.add(request_fingerprint)
        return False
```

