import json

def fetch_and_verify_api_response(api_url, expected_structure):
    response = requests.get(api_url, auth=("username", "password"))
    response.raise_for_status()  # Raise an HTTPError for non-200 status codes

    parsed_response = json.loads(response.text)

    if not isinstance(parsed_response, list):
        raise ValueError("Unexpected response type, expected a list")

    for item in parsed_response:
        if not isinstance(item, dict):
            raise TypeError(f"Unexpected item type, expected a dictionary, got {type(item)}")

        required_keys = expected_structure.keys()
        for key in required_keys:
            if key not in item:
                raise KeyError(f"Missing key '{key}' in item")

            if not isinstance(item[key], expected_structure[key]):
                raise TypeError(f"Unexpected type for key '{key}', expected {expected_structure[key]}, got {type(item[key])}")

if __name__ == "__main__":
