  DatabaseWithColumnFamilies(const std::string& db_path, const std::string& column_family_name)
      : db_(nullptr), cf_(nullptr) {
    rocksdb::Status status;
    rocksdb::DBOptions db_options;
    db_options.create_if_missing = true;
    db_options.error_if_exists = false;

    status = rocksdb::DB::Open(db_options, db_path, &db_);
    if (!status.ok()) {
      std::cerr << "Error opening database: " << status.ToString() << std::endl;
      return;
    }

    rocksdb::ColumnFamilyOptions cf_options;
    status = db_->CreateColumnFamily(cf_options, column_family_name, &cf_);
    if (!status.ok()) {
      std::cerr << "Error creating column family: " << status.ToString() << std::endl;
      Close();
      return;
    }
  }

  ~DatabaseWithColumnFamilies() {
    Close();
  }

  void Put(const std::string& key, const std::string& value) {
    rocksdb::Status status;
    rocksdb::WriteOptions write_options;
    std::unique_ptr<rocksdb::WriteBatch> batch(new rocksdb::WriteBatch());
    batch->Put(rocksdb::Slice(key), rocksdb::Slice(value));

    status = db_->Write(write_options, batch.get());
    if (!status.ok()) {
      std::cerr << "Error writing to database: " << status.ToString() << std::endl;
    }
  }

  void Close() {
    if (cf_) {
      cf_->Close();
      cf_ = nullptr;
    }

    if (db_) {
      db_->Close();
      db_ = nullptr;
    }
  }

