pub unsafe fn get_geometry_bounds(geometry: *const ID2D1Geometry, transformation_matrix: Option<&ID2D1Matrix3x2>) -> D2D1_RECT_F {
    let mut bounds = mem::zeroed();
    let mut error_code = 0;

