        bounds.left as f32,
        bounds.top as f32,
        bounds.right as f32,
        bounds.bottom as f32,
    );

    D2D1_RECT_F {
        left,
        top,
        right: min(right, left + bounds.size.width),
        bottom: min(bottom, top + bounds.size.height),
    }
}
