audio_device *open_audio_device(const char *device_name, int sample_rate, int num_channels, int buffer_size, int callback(void *userdata), void *userdata) {
    SDL_AudioSpec desired, observed;
    SDL_AudioDevice *device;
    audio_device *audio_device_ptr;

    // Allocate memory for the audio_device structure
    audio_device_ptr = (audio_device *) malloc(sizeof(audio_device));
    if (!audio_device_ptr) {
        fprintf(stderr, "Failed to allocate memory for audio_device structure\n");
        return NULL;
    }

    // Initialize SDL audio subsystem
    if (SDL_Init(SDL_INIT_AUDIO) < 0) {
        fprintf(stderr, "Failed to initialize SDL audio subsystem: %s\n", SDL_GetError());
        free(audio_device_ptr);
        return NULL;
    }

    // Set up desired audio specification
    desired.freq = sample_rate;
    desired.format = AUDIO_S16SYS;
    desired.channels = num_channels;
    desired.samples = buffer_size / num_channels;
    desired.callback = NULL;

    // Open audio device
    device = SDL_OpenAudioDevice(device_name, 0, &desired, &observed, 0);
    if (!device) {
        fprintf(stderr, "Failed to open audio device: %s\n", SDL_GetError());
        SDL_Quit();
        free(audio_device_ptr);
        return NULL;
    }

    // Set up callback function
    if (callback) {
        audio_device_ptr->callback = callback;
        audio_device_ptr->userdata = userdata;
        SDL_QueueSysEvent(SDL_SYSEVENT_USER1, 0);
        SDL_Delay(1); // Give SDL some time to process the event
    }

    // Set device name
    strncpy(audio_device_ptr->name, device_name, MAX_DEVICE_NAME_LENGTH);
    audio_device_ptr->id = device->id;

    return audio_device_ptr;
}

// Callback function to handle SDL audio events
void handle_audio_events(void *userdata) {
    audio_device *audio_device_ptr = (audio_device *) userdata;
    if (audio_device_ptr->callback) {
        audio_device_ptr->callback(audio_device_ptr->userdata);
    }
}

// Close the audio device and free resources
void close_audio_device(audio_device *audio_device_ptr) {
    if (audio_device_ptr->callback) {
        SDL_RemoveCallback(SDL_SYSEVENT, handle_audio_events);
        SDL_QueueSysEvent(SDL_SYSEVENT_USER1, 0);
        SDL_Delay(1); // Give SDL some time to process the event
    }
    SDL_CloseAudioDevice(audio_device_ptr->id);
    free(audio_device_ptr);
}
