use std::collections::VecDeque;
use std::sync::{Arc, Mutex, RwLock};
use std::thread;
use std::sync::atomic::{AtomicUsize, Ordering};

type Bag = Arc<RwLock<VecDeque<i32>>>;

struct ConcurrentBag {
    bag: Bag,
}

impl ConcurrentBag {
    fn new() -> Self {
        ConcurrentBag {
            bag: Arc::new(RwLock::new(VecDeque::new())),
        }
    }

    fn insert(&self, value: i32) {
        let mut bag = self.bag.write().lock().unwrap();
        bag.push_back(value);
    }

    fn collect(&self) -> Vec<i32> {
        let mut result = Vec::new();
        let mut bag = self.bag.read().lock().unwrap();

        while let Some(value) = bag.pop_front() {
            result.push(value);
        }

        result
    }
}

struct ThreadData {
    bag: Arc<ConcurrentBag>,
    index: AtomicUsize,
}

impl Drop for ThreadData {
    fn drop(&mut self) {
        self.bag.insert(self.index.load(Ordering::SeqCst, &mut |value| {
            if *value == self.index.load(Ordering::SeqCst) {
                self.bag.collect();
            }
        }));

        self.index.fetch_add(1, Ordering::SeqCst);
    }
}

fn main() {
    let mut bag = ConcurrentBag::new();

    let num_threads = 10;
    let threads = (0..num_threads)
        .map(|i| {
            thread::spawn(move || {
                let data = Arc::new(ThreadData {
                    bag: Arc::clone(&bag),
                    index: AtomicUsize::new(i),
                });

                for j in 0..100 {
                    data.bag.insert(j);
                }
            });
        })
        .collect::<Vec<_>>();

    for thread in threads {
        thread.join().unwrap();
    }

    let collected = bag.collect();
    println!("Collected {:?}", collected);
}
