```rust use std::env; use std::fs; use pelite::{FileMap, PE_FILE_DISPOSITION_NORMAL, PE_FILE_FLAGS_NONE, PE_FILE_OPEN_EXISTING, PE_MEM_COMMIT, PE_MEM_RESERVE, PE_OPEN_READ, PE_OPEN_EXECUTE_READ}; use imphash::imphash64;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <path_to_file>", args[0]);
        std::process::exit(1);
    }

    let file_path = &args[1];
    let file_map = match FileMap::open_file(file_path, PE_OPEN_READ, PE_FILE_DISPOSITION_NORMAL, PE_FILE_FLAGS_NONE) {
        Ok(file_map) => file_map,
        Err(e) => {
            eprintln!("Error opening file {}: {}", file_path, e);
            std::process::exit(1);
        }
    };

    let pe = match file_map.get_file_header() {
        Some(pe) => pe,
        None => {
            eprintln!("Error: File is not a valid PE file.");
            std::process::exit(1);
        }
    };

    let import_table = match pe.data_directory(PE_DIRECTORY_ENTRY_IMPORT) {
        Some(dir) => dir,
        None => {
            eprintln!("Error: PE file does not have an import table.");
            std::process::exit(1);
        }
    };

    let mut ctx = imphash64::context();

    for import in import_table.iter() {
        if let Some(name) = import.name() {
            ctx.update(name.as_bytes());
        }
    }

    let import_hash = ctx.finalize();
    println!("Import hash of {}: {:x}", file_path, import_hash);

    file_map.close();
}

