```rust
use std::fs::File;
use std::io::{BufWriter, Write};
use std::path::PathBuf;

fn create_and_write_to_files(file_paths: Vec<String>) -> Result<(), Box<dyn std::error::Error>> {
    let mut writers: Vec<(PathBuf, BufWriter<File>)> = Vec::new();

    for file_path in file_paths {
        let path = PathBuf::from(file_path);
        let file = File::create(&path)?;
        let writer = BufWriter::new(file);
        writers.push((path, writer));
    }

    for (path, mut writer) in writers {
        writer.write_all(b"Data to be written\n")?;
        writer.flush()?;
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let file_paths: Vec<String> = vec!["file1.txt", "file2.txt"];
    create_and_write_to_files(file_paths)
}
```

