mod base64 {
    use std::error::Error;
    use std::fs::File;
    use std::io::{Read, Write};
    use std::str;

    pub fn encode<T: AsRef<[u8]>>(data: T) -> String {
        let mut input = data.as_ref();
        let mut output = Vec::new();
        base64::write_all(&mut output, input).unwrap();
        str::from_utf8(&output).unwrap().to_string()
    }

    pub fn write_all<W: Write>(writer: &mut W, data: &[u8]) -> Result<(), Box<dyn Error>> {
        let mut input = data;
        let mut buffer = [0u8; 3];
        let mut len = 0;

        while len < input.len() {
            let n = input.len().min(buffer.len());
            let bytes_written = writer.write_all(&buffer[..n])?;
            if bytes_written != n {
                return Err(Box::new(std::io::Error::new(
                    std::io::ErrorKind::WriteZero,
                    "base64: write error",
                )));
            }
            len += n;
            input = &input[n..];

            if len % 3 == 0 {
                let padding = if len % 4 == 0 { 4 } else { 3 };
                writer.write_all(&[b'='; padding as u8])?;
            }

            let slice = &buffer[..len];
            let chunk = slice[..len - 1];
            let (i, j, k) = (0, 0, 0);
            let mut tval = 0;

            for b in chunk.iter().rev() {
                let bval = (*b as u8 & 0xfc) >> 2;
                tval |= bval << i;
                i += 2;

                if bval == 0 {
                    continue;
