use std::net::{TcpListener,TcpStream};
use std::sync::{Arc,Mutex};
use flate2::write::GzEncoder;
use flate2::Compression;

const PORT: u16 = 8080;
const MAX_BUFFER_SIZE: usize = 1024;

fn main() -> Result<(), io::Error> {
    let listener = TcpListener::bind("127.0.0.1:{}", &PORT).unwrap();
    println!("Listening on {}:{}", "127.0.0.1", PORT);

    let thread_pool_size = num_cpus::get();
    let thread_pool = Arc::new(rayon::ThreadPool::new(thread_pool_size));

    loop {
        let (socket, _) = listener.accept()?;
        println!("Accepted connection from {}", socket.peer_addr().unwrap().toString());

        let socket = Arc::new(Mutex::new(socket));
        let socket_clone = socket.clone();
        thread_pool.spawn(move || {
            handle_connection(socket_clone);
        });
    }
}

fn handle_connection(socket: Arc<Mutex<TcpStream>>) {
    let mut socket = socket.lock().unwrap();
    let reader = BufReader::new(socket);
    let mut buffer = [0; MAX_BUFFER_SIZE];

    loop {
        let num_bytes_read = reader.read(&mut buffer)?;
        if num_bytes_read == 0 {
            break;
        }

        let compressed_data = compress_data(&buffer[..num_bytes_read]);
        socket.write_all(&compressed_data)?;
    }

    drop(socket);
}

fn compress_data(data: &[u8]) -> Vec<u8> {
    let mut encoded_data = Vec::new();
    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
    encoder.write_all(data)?;
    encoder.finish().unwrap();
    encoded_data.extend_from_slice(&encoder.into_inner().unwrap());
    encoded_data
}
