```rust use getopts::Options;

fn print_usage(program_name: &str, options: &[(&str, char, String)]) {
    let mut opts = Options::new();
    opts.optflag("", "help", "Print usage information.");
    let matches = match opts.parse(std::args()) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error parsing options: {}", e);
            return;
        }
    };

    if matches.opt_present("help") {
        println!("{}", program_usage(program_name, options));
        std::process::exit(0);
    }

    let usage = format!("Usage: {} [options]\n\nOptions:\n", program_name);
    for option in options {
        let long_option = option.1.to_string();
        let short_option = option.0.chars().next().unwrap_or(' ').to_string();
        let description = option.2;
        let option_line = format!("  --{:<10} {:<5} {}\n", long_option, short_option, description);
        print!("{}{}", &usage, &option_line);
    }
}

