```rust use std::env; use std::path::Path;

fn get_binary_path(binary_name: &str) -> Result<Path, Box<dyn std::error::Error>> {
    let current_exe = env::current_exe()?;
    let parent_dir = current_exe.parent()?;
    let grandparent_dir = parent_dir.parent()?;

    let binary_path = _join_and_check_path_within_fs(grandparent_dir, binary_name)?;

    Ok(binary_path)
}

fn _join_and_check_path_within_fs(base_path: &Path, segment: &str) -> Result<Path, Box<dyn std::error::Error>> {
    let path = base_path.join(segment);
    if path.is_abs() {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Absolute paths are not allowed",
        )));
    }

    let parent_path = path.parent().ok_or_else(|| {
        Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Failed to get parent path",
        ))
    })?;

    if parent_path != base_path {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Path is not within the intended directory",
        )));
    }

    Ok(path)
}
```

