use hex_literal::hex; // For hexadecimal literals
use sha2::Sha256; // Use SHA-256 for hashing

fn hash_password(username: &str, password: &str, salt: Option<&str>) -> String {
    let mut input = Vec::new();
    input.extend_from_slice(username.as_bytes());
    input.extend_from_slice(b":mongo:");
    if let Some(s) = salt {
        input.extend_from_slice(s.as_bytes());
    }
    input.extend_from_slice(password.as_bytes());

    let mut hasher = Sha256::new();
    hasher.update(&input);
    let result = hasher.finalize();

    hex::encode(result)
}
```

