```rust use iron::prelude::*; use std::net::SocketAddr; use std::path::PathBuf;

fn create_web_server(listen_addr: &str) -> Result<Manager<IronService>, Box<dyn std::error::Error>> {
    let mut config = Configuration::default();
    config.log_level = LogLevel::Debug;

    let mut router = Router::new();

    let static_dir = PathBuf::from("./static");
    let static_mount = Mount::new(static_dir.to_str().unwrap(), StaticDirectory::new(static_dir));

    let api_handler = move |req: &mut Request, _res: &mut Response| {
        let body = req.get_ref("query").unwrap().parse::<i32>().unwrap();
        let response_body = format!("Received query: {} ", body);
        Ok(Response::with((Status::Ok, response_body)));
    };

    let api_mount = Mount::new("/api", Box::new(api_handler));

    router.mount("/", &static_mount);
    router.mount("/api", &api_mount);

    let service = IronService::new(router);

    let addr = SocketAddr::from((listen_addr.parse()?, 0));
    let mut server = Configuration::default().with_addr(addr).build(&service)?;

    server.handle_signals();

    Ok(server.start())
}
```

