use std::env;
use std::path::{Path, PathBuf};

fn get_executable_path(suffix: Option<&str>) -> Option<PathBuf> {
    let current_exe = match env::current_exe() {
        Some(path) => path,
        None => return None,
    };

    let base_name = Path::new(&current_exe).file_name().unwrap().to_str().unwrap();
    let base_path = Path::new(&env::current_dir().unwrap()).parent().unwrap();

    let mut output_path = PathBuf::new();
    output_path.push(base_path);
    output_path.push(base_name);

    if let Some(suffix) = suffix {
        output_path.push(suffix);
    }

    match output_path.canonicalize() {
        Ok(path) => Some(path),
        Err(_) => None,
    }
