use std::collections::HashMap;
use std::iter::Iterator;

struct Sha256HashedNumbersIterator {
    input: String,
    hashed_numbers: HashMap<String, String>,
}

impl Sha256HashedNumbersIterator {
    fn new(input: String) -> Self {
        let mut hasher = Sha256::new();
        let mut hashed_numbers = HashMap::new();
        let mut number = input.clone();

        hashed_numbers.insert(input, number.as_bytes().to_vec().to_hex());

        while number.len() > 0 {
            hasher.update(&number.as_bytes());
            let hash = hasher.finalize();
            let hex_hash = hex::encode(hash);
            number = hex_hash;
            hashed_numbers.insert(hex_hash, number);
        }

        Self { input, hashed_numbers }
    }
}

