use std::env;
use std::process;

fn print_env_info() {
    let os = process::Command::new("")
        .arg("--version")
        .output()
        .expect("Failed to execute command")
        .status
        .code()
        .unwrap_or(1);

    if os == Some(libc::ELF_EXECUTABLE) {
        let os = env::consts::OS;
        let executable = process::command_line().unwrap_or_default();
        let suffix = {
            let mut parts: Vec<&str> = executable.splitn(2, ".").collect();
            if parts.len() < 2 {
                String::new()
            } else {
                parts.last().unwrap().to_owned()
            }
        };

        println!(
            "Operating System: {}",
            env::consts::OS
        );
        println!(
            "Executable family: {:?}",
            match os {
                Some(libc::ELF) => "ELF",
                Some(libc::PE) => "PE",
                Some(libc::VXD) => "VXD",
                Some(_) => "Unknown",
                None => "Unknown",
            }
        );
        println!("Executable suffix: {}", suffix);
        println!("Current directory: {}", env::current_dir().unwrap().display());
        println!("Home directory: {}", env::home_dir().unwrap().display());
    } else {
        eprintln!("Error: Unsupported operating system");
    }
}
