fn compile_and_execute_c_program(probe: &Probe, c_program: &str) -> Result<String, Box<dyn std::error::Error>> {
    let temp_dir = tempdir::TempDir::new()?;
    let temp_file_path = temp_dir.path().join("c_program.c");

    let mut file = std::fs::File::create(temp_file_path)?;
    file.write_all(c_program.as_bytes())?;

    let output = Command::new("gcc")
        .arg("-o")
        .arg("c_program")
        .arg(&temp_file_path)
        .output()?;

    if output.status.success() {
        let output = Command::new("./c_program")
            .current_dir(temp_dir.path())
            .output()?;

        if output.status.success() {
            let output = String::from_utf8_lossy(&output.stdout);
            Ok(output.to_string())
        } else {
            Err(Box::new(output.status.to_string()))
        }
    } else {
        Err(Box::new(output.status.to_string()))
    }
}

