use actix_web::{middleware, web, App, Error, HttpResponse, Result;
use diesel::Connection;
use dotenv::dotenv;
use std::env;
use std::error::Error;
use std::fmt;
use std::io::{BufRead, BufReader};
use std::path::Path;

#[derive(Debug, PartialEq)]
enum DatabaseError {
    ConnectionError(String),
    MigrationError(String),
}

impl fmt::Display for DatabaseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            DatabaseError::ConnectionError(ref msg) => write!(f, "Database connection error: {}", msg),
            DatabaseError::MigrationError(ref msg) => write!(f, "Database migration error: {}", msg),
        }
    }
}

impl Error for DatabaseError {}

struct DatabaseMiddleware {
    connection: Connection,
}

impl middleware::ResultResponseMiddleware for DatabaseMiddleware {
    fn handle(&self, req: &web::Context<App>, r: Result<(), Error>, next: web::FunctionNext) -> Result<(), Error> {
        match r {
            Ok(_) => {
                self.connection.commit_transaction().map_err(|e| DatabaseError::ConnectionError(e.to_string()))?;
                next.respond(HttpResponse::Ok().finish())
            }
            Err(e) => next.respond(ErrorResponse(DatabaseError::MigrationError(e.to_string()))),
        }
    }
}

fn setup_database(db_url: &str) -> Result<(Connection, DatabaseMiddleware, Box<fn(web::Scope, web::ServiceRequest) -> Result<HttpResponse<Vec<u8>>, Error> + Send + 'static>, Error), DatabaseError> {
    dotenv().ok();
    let db_file = env::var("DB_FILE").expect("DB_FILE environment variable is missing");
    let mut migration_cmd = String::from("diesel migration run ");
    migration_cmd.push_str(&db_url);
    migration_cmd.push_str(" --database postgresql --schema public");

    let connection = match Connection::establish(&db_url) {
        Ok(connection) => connection,
        Err(e) => return Err(DatabaseError::ConnectionError(e.to_string())),
    };

    let mut process = match std::process::Command::new("sh")
                         .arg("-c")
                         .arg(&migration_cmd)
                         .output() {
        Ok(output) => output,
        Err(e) => return Err(DatabaseError::MigrationError(e.to_string())),
    };

    if process.status.success() {
        println!("Database migration successful.");
    } else {
        eprintln!("Database migration failed: {}", String::from_utf8_lossy(&process.stderr));
        return Err(DatabaseError::MigrationError(String::from_utf8_lossy(&process.stderr).to_string()));
    }

    let middleware = DatabaseMiddleware { connection };

    let app = App::new()
        .data(middleware.clone())
        .service(move |scope, req| {
            let transaction = match req.extensions().get::<Option<web::Data<Connection>>>() {
                Some(transaction) => transaction,
                None => return Err(DatabaseError::ConnectionError("No transaction found in request.".to_string())),
            };

            Box::new(move |req, next| {
                transaction.commit().map_err(|e| DatabaseError::ConnectionError(e.to_string()))?;
                next.call(req)
            })
        });

    Ok((connection, middleware, app, middleware))
}
