use mach::{header::fat_magic::FAT_MAGIC_64, header::fat_arch::FAT_ARCH64, file::arch::Architecture};

fn parse_macho_file(file_path: &str) -> Result<(), Box<dyn Error>> {
    let mut file = File::open(file_path)?;
    let mut data = Vec::new();
    file.read_to_end(&mut data)?;

    let fat_header = FAT_MAGIC_64.as_bytes();
    if data.starts_with(fat_header) {
        let mut fat_data = &data[..sizeof()];
        let mut fat_archs = Vec::new();

        while fat_data.len() >= std::mem::size_of::<yr_fat_header_t>() {
            let fat_header = unsafe { std::mem::transmute::<&[u8; std::mem::size_of::<yr_fat_header_t>>, yr_fat_header_t>(&fat_data) };
            let fat_arch = unsafe { std::mem::transmute::<&[u8; std::mem::size_of::<yr_fat_arch_64_t>>, yr_fat_arch_64_t>(&fat_data[std::mem::size_of::<yr_fat_header_t>()..]) };

            if fat_arch.offset + fat_arch.size < fat_arch.offset {
                continue;
            }

            if data.len() < fat_arch.offset + fat_arch.size {
                break;
            }

            let architecture = Architecture::new(None, None)?;
            architecture.parse(&data[fat_arch.offset..(fat_arch.offset + fat_arch.size)])?;
            fat_archs.push(architecture);

            fat_data = &data[(fat_arch.offset + fat_arch.size)..];
        }

        for architecture in fat_archs {
            println!("Architecture: {:?}", architecture);
