void sha1_hash(const unsigned char *input, unsigned char output[SHA1_DIGEST_LENGTH]) {
  SHA1_CTX ctx;
  SHA1_Init(&ctx);
  SHA1_Update(&ctx, input, strlen((const char *)input));
  SHA1_Final(output, &ctx);
}

char *generate_hash(const char *input, size_t input_len) {
