use crypto::md::Md5;
use crypto::hmac;
use pbkdf2;
use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct SaltError {
    message: String,
}

impl Error for SaltError {
    fn description(&self) -> &str {
        &self.message
    }
}

impl fmt::Display for SaltError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

fn validate_salt(salt: &[u8]) -> Result<(), SaltError> {
    if salt.is_empty() {
        Err(SaltError {
            message: String::from("Invalid salt: it must not be empty."),
        })
    } else {
        Ok(())
    }
}

fn pbhmac_sha1(password: &[u8], salt: &[u8]) -> Vec<u8> {
    let mut md = Md5::new();
    let mut hmac = hmac::Hmac::<Md5>::new(password, salt).expect("Failed to create HMAC.");
    md.input(&hmac);
    hmac.result().to_vec()
}

fn pkdf2_sha1(password: &[u8], salt: &[u8], iterations: u32, key_len: u32) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut derived_key = vec![0; key_len as usize];
    pbkdf2::derive(
        password,
        salt,
        iterations,
        &Md5::new(),
        &mut derived_key,
    )
    .map_err(|e| Box::new(e))
}

pub fn hash_password_with_salt(password: &str, salt: &[u8]) -> Result<Vec<u8>, Box<dyn Error>> {
    validate_salt(salt)?;
    let password_bytes = password.as_bytes();
    let salted_password = pbhmac_sha1(password_bytes, salt);
    let hashed_password = pkdf2_sha1(password_bytes, salt, 10000, 32)?;
    Ok(hashed_password)
}
