fn find_command(command_name: &str) -> Option<PathBuf> {
    let mut search_paths: Vec<PathBuf> = Vec::new();

    // Add current executable's directory and parent directory to the search paths
    let mut current_path = Path::new(env!("CARGO_BIN"));
    search_paths.push(current_path.ancestors().next().unwrap().to_owned());
    search_paths.push(current_path.to_owned());

