use std::iter; use std::fmt; use std::error::Error; use std::hash::Hasher; use md5::Md5;

#[derive(Debug, PartialEq)]
enum HashError {
    IoError(std::io::Error),
    HashError(Box<dyn Error>)
}

impl From<std::io::Error> for HashError {
    fn from(error: std::io::Error) -> Self {
        HashError::IoError(error)
    }
}

impl From<Box<dyn Error>> for HashError {
    fn from(error: Box<dyn Error>) -> Self {
        HashError::HashError(error)
    }
}

impl fmt::Display for HashError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            HashError::IoError(ref err) => write!(f, "I/O error: {}", err),
            HashError::HashError(ref err) => write!(f, "Hash error: {}", err),
        }
    }
}

fn hash_string(input: &str, iterations: u32) -> Result<String, HashError> {
    let mut hasher = Md5::new();
    let mut output = Vec::new();

    for _ in 0..iterations {
        hasher.update(input.as_bytes());
        hasher.finalize().write_all(&mut output)?;
        hasher = Md5::new();
    }

    let hex = hex_literal::hex::encode(output.as_slice());
    Ok(hex)
}

