fn generate_pact_file(pact: &Pact, output_dir: &PathBuf) -> Result<String, Box<dyn std::error::Error>> {
    let temp_dir = tempfile::NamedTempDir::new("pact_file")?;
    let temp_file_path = temp_dir.path().join("pact_file.pact");

    let file = File::create(temp_file_path)?;
    let mut file_writer = BufWriter::new(file);

    // Write PACT file header
    writeln!(file_writer, "{{}}")?;

    // Write Pact Interaction section
    writeln!(file_writer, "interactions:")?;
    writeln!(file_writer, "  - name: interaction_name")?;
    writeln!(file_writer, "    input:")?;
    writeln!(file_writer, "      {}: {}", pact.input.name, pact.input.content.as_str())?;
    writeln!(file_writer, "    output:")?;
    writeln!(file_writer, "      {}: {}", pact.output.name, pact.output.content.as_str())?;

    // Write Pact Outcome section
    writeln!(file_writer, "    outcomes:")?;
    for outcome in &pact.outcomes {
        writeln!(file_writer, "      - name: outcome_name")?;
        writeln!(file_writer, "        paths:")?;
        writeln!(file_writer, "          - path: output_path")?;
        writeln!(file_writer, "          - path: error_path")?;
        writeln!(file_writer, "        status: {}", outcome.status)?;
        writeln!(file_writer, "        error_message: {}", outcome.error_message)?;
    }

    file_writer.flush()?;

    let file_contents = File::open(temp_file_path)?.bytes().map(|b| b.to_vec()).collect::<Vec<_>>();
    let pact_file_contents = String::from_utf8(file_contents).unwrap();

    // Remove the temporary directory after generating the PACT file
    drop(temp_dir);

    Ok(pact_file_contents)
}
