fn get_file_check_path(target: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let current_dir = env::current_dir()?;
    let cargo_toml = current_dir.join("Cargo.toml");
    let cargo_manifest = match fs::File::open(&cargo_toml) {
        Ok(file) => serde_toml::from_reader(file)?,
        Err(e) => return Err(Box::new(e)),
