    if path_buf.exists() {
        return Ok(path_buf);
    }

    let mut search_dirs = vec![current_dir];
    search_dirs.extend(cargo_manifest.workspace.members.iter().map(|m| m.path));

    for dir in &search_dirs {
        let path = dir.join(format!("{}-{}", file_check_name, target_triple));
        if path.exists() {
            return Ok(path);
        }
    }

    Err(Box::new(std::io::Error::new(
        std::io::ErrorKind::NotFound,
        format!("FileCheck binary not found for target {}", target),
