use std::error::Error;
use std::fmt;

#[derive(Debug, PartialEq)]
enum FoldError {
    InvalidInput,
    Overflow,
}

impl fmt::Display for FoldError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            FoldError::InvalidInput => write!(f, "Invalid input"),
            FoldError::Overflow => write!(f, "Overflow"),
        }
    }
}

impl Error for FoldError {}

fn fold_header(input: &str, max_length: usize) -> Result<String, FoldError> {
    if input.is_empty() {
        return Err(FoldError::InvalidInput);
    }

    let mut lines = input.lines();
    let mut folded_lines = Vec::new();

    while let Some(line) = lines.next() {
        let parts: Vec<&str> = line.splitn(max_name_length(), ": ").collect();

        if parts.len() < 2 {
            return Err(FoldError::InvalidInput);
        }

        let name = parts[0].trim();
        let value = parts[1];

        let folded_value = if value.len() > max_value_length() {
            value[..max_value_length()]
                .chars()
                .rev()
                .take_while(|c| c.is_whitespace())
                .position(|_| !value.is_char_boundary(value.len() - 1))
                .map(|pos| value[..pos].to_string())
                .unwrap_or_else(|| value[..max_value_length()].to_string())
        } else {
            value.to_string()
        };

        folded_lines.push(format!("{}: {}\r\n", name, folded_value));
    }

    Ok(folded_lines.join(""))
}

const max_name_length: usize = 72;
const max_value_length: usize = 72;

fn main() {
    let input = "header1: value1\nheader2: value2 value3\nheader3: value4 value5 value6";

    match fold_header(input, max_name_length) {
        Ok(folded) => println!("Folded header: {}", folded),
        Err(e) => println!("Error: {}", e),
    }
}
