struct DBActor {
    db: Arc<Mutex<sqlx::Pool>>,
}

impl DBActor {
    fn new(db_pool: Arc<Mutex<sqlx::Pool>>) -> Self {
        DBActor { db: db_pool }
    }

    async fn process_query(&self, query: String) -> Result<String, String> {
        let mut db = self.db.lock().unwrap();
        let result = sqlx::query_as::<_, sqlx::query_result::QueryResult<i32>>("SELECT id FROM users WHERE id = $1")
            .bind(query)
            .fetch_one(&mut *db)
            .await
            .map_err(|e| e.to_string())?;

        Ok(result.ok().map(|r| r.id.to_string()).unwrap_or("Invalid user ID".to_string()))
    }
}

struct QueryClient {
    channel: Channel<String>,
    db_actor: Arc<DBActor>,
}

impl QueryClient {
    fn new(db_actor: Arc<DBActor>, channel: Channel<String>) -> Self {
        QueryClient { channel, db_actor }
    }

    async fn handle_query(&mut self, query: String) {
        match self.db_actor.process_query(query).await {
            Ok(result) => self.channel.send(result).unwrap(),
            Err(error) => self.channel.send(error).unwrap(),
        }
    }
}

fn main() {
    let db_pool = Arc::new(Mutex::new(sqlx::Pool::new("postgresql://user:password@localhost/database").unwrap()));
    let db_actor = Arc::new(DBActor::new(db_pool.clone()));

    let thread_pool = ThreadPoolExecutor::new(10);

    let query_client = Arc::new(QueryClient::new(db_actor.clone(), Channel::bounded(10)));

    thread_pool.execute(move || {
        loop {
            match query_client.channel.recv() {
                Ok(query) => query_client.handle_query(query),
                Err(e) => println!("Error receiving query: {}", e),
            }
        }
    });

    let client = Arc::new(Mutex::new(QueryClient::new(db_actor, Channel::bounded(10))));

    let client_handle = client.lock().unwrap();

    let mut input = String::new();
    loop {
        print!("Enter a user ID: ");
        std::io::stdin().read_line(&mut input).unwrap();

        if input.trim().is_empty() {
            break;
        }

        let client_clone = client.clone();
        thread_pool.execute(move || {
            let client = client_clone.lock().unwrap();
            client.handle_query(input).await;
        });
    }

    thread_pool.shutdown().unwrap();
}
